window.KQ_GUIDE = {"ids":["shark","dolphin","octopus","crab","seaturtle","puffer","bear","fox","wolf","owl","squirrel","koala","penguin","cow","pig","horse","chick","frog","duck","lion","elephant","giraffe","kangaroo","tiger","monkey","parrot","crocodile","rabbit","bee","butterfly","bat","eagle","mouse","fennec","peregrine","cheetah"],"a":{"shark":{"id":"shark","i":0,"latin":"Carcharodon carcharias","group":"fish","home":"ocean","diet":"carn","active":"day and night","continents":["North America","South America","Europe","Africa","Asia","Australia"],"iucn":"VU","en":{"name":"Great white shark","habitat_text":"Cool and warm coastal seas and the open ocean, from the surface down to more than 1,000 m","menu":"Seals, sea lions, dolphins, fish, rays, smaller sharks, squid and sea turtles. Young sharks eat mostly fish, rays and squid.","iucn_note":"Vulnerable worldwide (IUCN, 2019); the Mediterranean population is Critically Endangered. It recovers slowly: females first breed at about 33 years old and give birth only every two or three years.","page_facts":["I have about 300 teeth.","I must keep swimming to breathe.","My back is grey, my belly white.","I can live over 70 years."],"powers":[{"title":"A sense for electricity","kid":"Tiny jelly-filled pores on its snout can feel the weak electricity made by the muscles of animals close by.","teen":"Ampullae of Lorenzini, gel-filled pores on the snout, sense the faint electric fields made by the muscles and nerves of prey, helping it find food at close range.","part":"snout"},{"title":"Conveyor-belt teeth","kid":"It has about 300 sharp, jagged teeth in rows. When a front tooth falls out, one from the row behind moves forward.","teen":"Broad, triangular, serrated teeth sit in several rows. Replacement teeth keep moving forward like a conveyor belt, so a broken or lost tooth is always replaced.","part":"teeth"},{"title":"A warm-bodied fish","kid":"Most fish are as cold as the water around them, but this shark keeps much of its body warmer than the sea.","teen":"It is partly warm-blooded: a rete mirabile, a network of blood vessels, traps heat made by its swimming muscles instead of losing it at the gills.","part":"body"}],"field_note":{"place":"","text":"A white shark named Nicole, tagged by scientists off South Africa, swam to Australia in 99 days and was later seen back off South Africa: a round trip of more than 20,000 km."},"lab_note":"In 2014, Li Ling Hamady and colleagues at Woods Hole Oceanographic Institution dated white shark backbones using carbon left in the sea by 1950s–60s bomb tests. One male was about 73 years old.","myth":{"claim":"Great white sharks like to hunt people.","verdict":"myth","why":"Its normal food is seals, fish and dolphins. Scientists say white sharks do not seem to find people suitable as prey, and many bites on people look like exploratory test bites."},"clues":["My skeleton is made of cartilage, not bone.","I have rows of teeth, and new ones replace any I lose.","People call me 'great white' after my big white belly."],"compare":{"stat":"Length","value":6,"unit":"m","text":"up to about 6 m"},"stats":[{"label":"Length","value":"3.4–4.9 m","note":"adults; rarely up to about 6 m"},{"label":"Length at birth","value":"about 1.1–1.8 m","note":"pups are born live"},{"label":"Weight","value":"680–1,900 kg","note":"adults; females are bigger"},{"label":"Dive depth","value":"about 1,300 m","note":"deepest dives recorded"}],"taxonomy":["Animals","Cartilaginous fishes · Chondrichthyes","Mackerel sharks · Lamniformes","White sharks, makos and porbeagles · Lamnidae","Carcharodon carcharias"]},"he":{"name":"כריש לבן","habitat_text":"מים קרירים וחמים ליד החופים ובאוקיינוס הפתוח, מפני המים ועד עומק של יותר מ־1,000 מ׳","menu":"כלבי ים, אריות ים, דולפינים, דגים, בטאים, כרישים קטנים יותר, דיונונים וצבי ים. כרישים צעירים אוכלים בעיקר דגים, בטאים ודיונונים.","iucn_note":"פגיע בכל העולם (IUCN, 2019); האוכלוסייה של הים התיכון בסכנת הכחדה חמורה. המין מתאושש לאט: הנקבות מתרבות לראשונה בגיל 33 בערך, ויולדות רק פעם בשנתיים או בשלוש שנים.","page_facts":["יש לי בערך 300 שיניים.","אני חייב להמשיך לשחות כדי לנשום.","הגב שלי אפור והבטן שלי לבנה.","אני יכול לחיות יותר מ־70 שנה."],"powers":[{"title":"חוש לחשמל","kid":"נקבוביות זעירות מלאות ג׳לי על החרטום שלו מרגישות את החשמל החלש שמייצרים השרירים של בעלי חיים קרובים.","teen":"אמפולות לורנציני, נקבוביות מלאות ג׳ל על החרטום, קולטות את השדות החשמליים החלשים שמייצרים השרירים והעצבים של הטרף, ועוזרות לו למצוא מזון מטווח קצר.","part":"snout"},{"title":"שיניים על מסוע","kid":"יש לו בערך 300 שיניים חדות ומשוננות בשורות. כששן קדמית נופלת, שן מהשורה שמאחוריה זזה קדימה.","teen":"שיניים רחבות, משולשות ומשוננות מסודרות בכמה שורות. שיניים חלופיות נעות קדימה כל הזמן, כמו על מסוע, כך שכל שן שנשברה או אבדה מוחלפת תמיד.","part":"teeth"},{"title":"דג עם גוף חם","kid":"רוב הדגים קרים כמו המים שסביבם, אבל הכריש הזה שומר על חלק גדול מהגוף שלו חם יותר מהים.","teen":"הוא חם־דם בחלקו: \"רשת מופלאה\" (rete mirabile), רשת של כלי דם, לוכדת את החום שמייצרים שרירי השחייה במקום לאבד אותו בזימים.","part":"body"}],"field_note":{"place":"","text":"כרישה לבנה בשם ניקול, שמדענים הצמידו לה תג מול חופי דרום אפריקה, שחתה לאוסטרליה ב־99 ימים, ואחר כך נראתה שוב מול דרום אפריקה: מסע הלוך ושוב של יותר מ־20,000 ק״מ."},"lab_note":"ב־2014 קבעו לי לינג האמדי ועמיתים במכון האוקיינוגרפי וודס הול את הגיל של חוליות עמוד שדרה של כרישים לבנים, בעזרת פחמן שנשאר בים מניסויי פצצות בשנות ה־50 וה־60. זכר אחד היה בן 73 בערך.","myth":{"claim":"כרישים לבנים אוהבים לצוד בני אדם.","verdict":"myth","why":"המזון הרגיל שלו הוא כלבי ים, דגים ודולפינים. לפי המדענים, נראה שכרישים לבנים לא מוצאים בבני אדם טרף מתאים, ורבות מהנשיכות בבני אדם נראות כמו נשיכות גישוש, לבדיקה."},"clues":["השלד שלי עשוי סחוס, לא עצם.","יש לי שורות של שיניים, ושיניים חדשות מחליפות כל שן שאני מאבד.","קוראים לי \"הכריש הלבן הגדול\" בגלל הבטן הלבנה והגדולה שלי."],"compare":{"stat":"Length","value":6,"unit":"m","text":"עד כ־6 מ׳"},"stats":[{"label":"אורך","value":"3.4–4.9 מ׳","note":"בוגרים; לעיתים רחוקות עד כ־6 מ׳"},{"label":"אורך בלידה","value":"בערך 1.1–1.8 מ׳","note":"הגורים נולדים חיים"},{"label":"משקל","value":"680–1,900 ק״ג","note":"בוגרים; הנקבות גדולות יותר"},{"label":"עומק צלילה","value":"בערך 1,300 מ׳","note":"הצלילות העמוקות ביותר שתועדו"}],"taxonomy":["בעלי חיים","דגי סחוס · Chondrichthyes","עמלצאים · Lamniformes","עמלציים · Lamnidae","Carcharodon carcharias"]}},"dolphin":{"id":"dolphin","i":1,"latin":"Tursiops truncatus","group":"mammal","home":"ocean","diet":"carn","active":"day and night","continents":["North America","South America","Europe","Africa","Asia","Australia"],"iucn":"LC","en":{"name":"Common bottlenose dolphin","habitat_text":"Coasts, bays, harbours and open seas in warm and temperate oceans; absent only from polar waters","menu":"Mostly fish, plus squid, eels, shrimp and crabs. An adult eats about 4.5–16 kg of food a day.","iucn_note":"Least Concern worldwide. The Mediterranean population, listed as Vulnerable in 2009, was reassessed as Least Concern in 2021. Dangers: getting caught in fishing gear, pollution and ocean plastic.","page_facts":["I breathe air through my blowhole.","My baby drinks my milk.","I find fish with echoes.","I have my own whistle name."],"powers":[{"title":"Seeing with sound","kid":"It makes clicking sounds and listens for the echoes. The echoes tell it where fish are, even in dark or muddy water.","teen":"Clicks are focused into a beam by the melon, a fatty organ in the forehead. Returning echoes are picked up through an 'acoustic window' in the lower jaw.","part":"forehead"},{"title":"A nose on top","kid":"Its nostril is a blowhole on top of its head, so it can breathe just by rising to the surface.","teen":"The blowhole is a single nostril on top of the head. Breathing is voluntary, so a dolphin sleeps with half its brain at a time while the other half stays alert.","part":"blowhole"},{"title":"An up-and-down tail","kid":"Its tail moves up and down, not side to side like a fish's tail.","teen":"Its flat, horizontal tail flukes beat up and down to push it forward, while a fish's upright tail fin sweeps from side to side.","part":"tail flukes"}],"field_note":{"place":"Israel","text":"Bottlenose dolphins live along Israel's whole Mediterranean coast. Scientists from the University of Haifa and the IMMRAC dolphin group have surveyed them for about 20 years and often find them following fishing trawlers."},"lab_note":"In 2013, Stephanie King and Vincent Janik of the University of St Andrews played wild dolphins recordings of their own signature whistles. Each dolphin answered its own 'name' by whistling it back.","myth":{"claim":"Dolphins are fish.","verdict":"myth","why":"Dolphins are mammals. They breathe air with lungs, give birth to live babies and feed them milk, often for well over a year."},"clues":["I live in the sea, but I must come up to breathe air.","I find fish by clicking and listening to the echoes.","My short, rounded beak gave me my name: bottlenose."],"compare":{"stat":"Weight","value":650,"unit":"kg","text":"up to about 650 kg"},"stats":[{"label":"Length","value":"1.8–4 m","note":"adults, beak to tail"},{"label":"Length at birth","value":"0.8–1.4 m","note":"a newborn calf"},{"label":"Weight","value":"135–650 kg","note":"males are usually bigger"},{"label":"Lifespan","value":"40–60 years","note":"in the wild; females often live longer"}],"taxonomy":["Animals","Mammals · Mammalia","Whales and dolphins · Cetacea","Oceanic dolphins · Delphinidae","Tursiops truncatus"]},"he":{"name":"דולפין (דולפינן מצוי)","habitat_text":"חופים, מפרצים, נמלים וים פתוח באוקיינוסים חמים וממוזגים; נעדר רק ממי הקטבים","menu":"בעיקר דגים, וגם דיונונים, צלופחים, שרימפס וסרטנים. דולפין בוגר אוכל בערך 4.5–16 ק״ג מזון ביום.","iucn_note":"ללא חשש בכל העולם. האוכלוסייה בים התיכון, שהוגדרה \"פגיעה\" ב־2009, הוערכה מחדש ב־2021 כ\"ללא חשש\". סכנות: הסתבכות בציוד דיג, זיהום ופלסטיק באוקיינוס.","page_facts":["אני נושם אוויר דרך פתח הנשימה שלי.","הגור שלי שותה ממני חלב.","אני מוצא דגים בעזרת הדים.","יש לי שריקה שהיא השם שלי."],"powers":[{"title":"לראות בעזרת קול","kid":"הוא משמיע קולות נקישה ומקשיב להדים. ההדים מגלים לו איפה יש דגים, גם במים חשוכים או עכורים.","teen":"\"המלון\", איבר שומני במצח, ממקד את הנקישות לאלומה. ההדים שחוזרים נקלטים דרך \"חלון אקוסטי\" בלסת התחתונה.","part":"forehead"},{"title":"אף על הראש","kid":"הנחיר שלו הוא פתח נשימה על קודקוד הראש, כך שמספיק לו לעלות אל פני המים כדי לנשום.","teen":"פתח הנשימה הוא נחיר יחיד על קודקוד הראש. הנשימה רצונית, ולכן דולפין ישן עם חצי מוח בכל פעם, והחצי השני נשאר ערני.","part":"blowhole"},{"title":"זנב שזז למעלה ולמטה","kid":"הזנב שלו זז למעלה ולמטה, ולא מצד לצד כמו זנב של דג.","teen":"אונות הזנב השטוחות והאופקיות שלו מכות למעלה ולמטה ודוחפות אותו קדימה, ואילו סנפיר הזנב הזקוף של דג נע מצד לצד.","part":"tail flukes"}],"field_note":{"place":"Israel","text":"דולפינים מהמין הזה חיים לאורך כל חוף הים התיכון של ישראל. מדענים מאוניברסיטת חיפה ומקבוצת הדולפינים IMMRAC סוקרים אותם כבר בערך 20 שנה, ולעיתים קרובות מוצאים אותם שוחים בעקבות ספינות מכמורת."},"lab_note":"ב־2013 השמיעו וינסנט יאניק וסטפני קינג מאוניברסיטת סנט אנדרוז לדולפינים בטבע הקלטות של שריקות החתימה שלהם עצמם. כל דולפין ענה ל\"שם\" שלו ושרק אותו בחזרה.","myth":{"claim":"דולפינים הם דגים.","verdict":"myth","why":"דולפינים הם יונקים. הם נושמים אוויר בריאות, יולדים גורים חיים ומניקים אותם בחלב, לעיתים קרובות במשך הרבה יותר משנה."},"clues":["אני חי בים, אבל אני חייב לעלות למעלה כדי לנשום אוויר.","אני מוצא דגים בעזרת נקישות והקשבה להדים.","באנגלית קוראים לי \"אף בקבוק\", בגלל המקור הקצר והעגול שלי."],"compare":{"stat":"Weight","value":650,"unit":"kg","text":"עד כ־650 ק״ג"},"stats":[{"label":"אורך","value":"1.8–4 מ׳","note":"בוגרים, מהמקור עד הזנב"},{"label":"אורך בלידה","value":"0.8–1.4 מ׳","note":"גור שזה עתה נולד"},{"label":"משקל","value":"135–650 ק״ג","note":"הזכרים בדרך כלל גדולים יותר"},{"label":"אורך חיים","value":"40–60 שנים","note":"בטבע; הנקבות חיות לעיתים קרובות יותר זמן"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","לווייתנאים · Cetacea","דולפיניים · Delphinidae","Tursiops truncatus"]}},"octopus":{"id":"octopus","i":2,"latin":"Octopus vulgaris","group":"mollusc","home":"ocean","diet":"carn","active":"night","continents":["Europe","Africa","Asia"],"iucn":"LC","en":{"name":"Common octopus","habitat_text":"Rocky reefs and the sea floor in shallow coastal water, usually less than 200 m deep","menu":"Crabs, lobsters, clams, scallops, sea snails and sometimes fish, bitten open with a small, sharp beak.","iucn_note":"Least Concern. It is fished heavily around the Mediterranean and the eastern Atlantic, so local stocks need careful management to avoid overfishing.","page_facts":["I have eight arms.","I can change my colour.","I squirt ink to escape.","I have three hearts."],"powers":[{"title":"Colour-changing skin","kid":"Its skin can change colour, pattern and even bumpiness to match rocks, sand or seaweed.","teen":"Chromatophores, tiny pigment sacs pulled open by muscles under nerve control, work with reflective cells to change colour and pattern; raised skin bumps called papillae change its texture.","part":"skin"},{"title":"Arms that think","kid":"About two-thirds of its nerve cells are in its arms, so each arm can feel and grab with little help from the brain.","teen":"Of its roughly 500 million neurons, about two-thirds lie in the arms. Movement programs are built into each arm: even a cut-off arm still grabs objects with its suckers.","part":"arms"},{"title":"Suckers that sense","kid":"Each arm has hundreds of suckers. They grip tightly, and they can sense chemicals, a little like tasting by touch.","teen":"The suckers carry chemical sensors. A chemical in octopus skin switches off the suckers' grabbing reflex, so its own arms do not stick to each other.","part":"suckers"}],"field_note":{"place":"Israel","text":"At the Hebrew University of Jerusalem, scientists study common octopuses collected by local anglers in the Mediterranean, to learn how a brain controls eight soft, bendy arms."},"lab_note":"In 2014, Nir Nesher and Binyamin Hochner at the Hebrew University of Jerusalem found that octopuses can tell their own cut-off arm from another octopus's arm, and treat the stranger's arm more like food.","myth":{"claim":"An octopus has eight tentacles.","verdict":"myth","why":"Scientists call an octopus's eight limbs arms. Tentacles are the two longer feeding limbs that squid and cuttlefish have in addition to their eight arms. An octopus has none."},"clues":["I have no bones at all.","I have three hearts and blue blood.","I have eight sucker-covered arms and no tentacles at all."],"compare":{"stat":"Length","value":1,"unit":"m","text":"about 1 m with arms"},"stats":[{"label":"Body length","value":"15–25 cm","note":"the head-like body, without arms"},{"label":"Length with arms","value":"up to about 1 m","note":"arms stretched out"},{"label":"Weight","value":"up to 9 kg","note":"the very largest"},{"label":"Lifespan","value":"1–2 years","note":"a short life for a clever animal"}],"taxonomy":["Animals","Molluscs · Mollusca","Cephalopods · Cephalopoda","Octopuses · Octopoda","Octopus family · Octopodidae","Octopus vulgaris"]},"he":{"name":"תמנון החוף","habitat_text":"שוניות סלעיות וקרקעית הים במים רדודים ליד החוף, בדרך כלל בעומק של פחות מ־200 מ׳","menu":"סרטנים, לובסטרים, צדפות, מסרקניות, חלזונות ים ולפעמים דגים. הוא פותח אותם בנשיכה של מקור קטן וחד.","iucn_note":"ללא חשש. דגים אותו הרבה סביב הים התיכון ובמזרח האוקיינוס האטלנטי, ולכן צריך לנהל בזהירות את האוכלוסיות המקומיות כדי למנוע דיג־יתר.","page_facts":["יש לי שמונה זרועות.","אני יכול לשנות את הצבע שלי.","אני מתיז דיו כדי לברוח.","יש לי שלושה לבבות."],"powers":[{"title":"עור שמחליף צבעים","kid":"העור שלו יכול לשנות צבע, דוגמה ואפילו בליטות, כדי להתאים את עצמו לסלעים, לחול או לאצות.","teen":"כרומטופורים, שקיקי צבען זעירים ששרירים בשליטת העצבים מותחים ופותחים, פועלים יחד עם תאים מחזירי אור כדי לשנות צבע ודוגמה; בליטות עור שנקראות פפילות משנות את המרקם שלו.","part":"skin"},{"title":"זרועות שחושבות","kid":"בערך שני שלישים מתאי העצב שלו נמצאים בזרועות, ולכן כל זרוע יכולה להרגיש ולתפוס בלי הרבה עזרה מהמוח.","teen":"מתוך כ־500 מיליון תאי העצב שלו, בערך שני שלישים נמצאים בזרועות. תוכניות התנועה בנויות בתוך כל זרוע: אפילו זרוע כרותה עדיין תופסת חפצים בעזרת כוסות היניקה שלה.","part":"arms"},{"title":"כוסות יניקה שמרגישות","kid":"על כל זרוע יש מאות כוסות יניקה. הן נצמדות חזק, והן יכולות לחוש חומרים כימיים, קצת כמו לטעום בנגיעה.","teen":"בכוסות היניקה יש חיישנים כימיים. חומר כימי בעור של התמנון מנטרל את רפלקס התפיסה של כוסות היניקה, וכך הזרועות שלו לא נדבקות זו לזו.","part":"suckers"}],"field_note":{"place":"Israel","text":"באוניברסיטה העברית בירושלים חוקרים מדענים תמנוני חוף שדייגי חכה מקומיים אספו בים התיכון, כדי ללמוד איך מוח שולט בשמונה זרועות רכות וגמישות."},"lab_note":"ב־2014 גילו ניר נשר ובנימין הוכנר מהאוניברסיטה העברית בירושלים שתמנונים מבחינים בין זרוע כרותה שלהם לבין זרוע של תמנון אחר, ומתייחסים לזרוע הזרה יותר כמו לאוכל.","myth":{"claim":"לתמנון יש שמונה מחושים.","verdict":"myth","why":"מדענים קוראים לשמונה הגפיים של התמנון \"זרועות\". מחושים הם שתי גפיים ארוכות יותר לאכילה, שיש לדיונונים ולספיות בנוסף לשמונה הזרועות שלהם. לתמנון אין מחושים בכלל."},"clues":["אין לי עצמות בכלל.","יש לי שלושה לבבות ודם כחול.","יש לי שמונה זרועות מכוסות כוסות יניקה, ואין לי מחושים בכלל."],"compare":{"stat":"Length","value":1,"unit":"m","text":"בערך 1 מ׳ עם הזרועות"},"stats":[{"label":"אורך הגוף","value":"15–25 ס״מ","note":"הגוף שנראה כמו ראש, בלי הזרועות"},{"label":"אורך עם הזרועות","value":"עד בערך 1 מ׳","note":"כשהזרועות פרושות"},{"label":"משקל","value":"עד 9 ק״ג","note":"הגדולים ביותר"},{"label":"אורך חיים","value":"1–2 שנים","note":"חיים קצרים לחיה חכמה כל כך"}],"taxonomy":["בעלי חיים","רכיכות · Mollusca","רגלי־ראש · Cephalopoda","תמנונאים · Octopoda","תמנוניים · Octopodidae","Octopus vulgaris"]}},"crab":{"id":"crab","i":3,"latin":"Ocypode cursor","group":"crustacean","home":"ocean","diet":"omni","active":"night","continents":["Europe","Africa","Asia"],"iucn":null,"en":{"name":"Tufted ghost crab","habitat_text":"Sandy beaches, in burrows dug near or above the high-tide line","menu":"Sea turtle eggs and hatchlings, small crabs, snails, clams, ants, dead animals, washed-up seaweed and food scraps people leave on the beach.","iucn_note":"Not yet assessed by the IUCN. It is one of nine marine crustacean species protected across the Mediterranean Sea.","page_facts":["I dig my home in sand.","I come out at night.","My eyes stand up on stalks.","I eat almost anything I find."],"powers":[{"title":"Periscope eyes","kid":"Its big eyes sit on long stalks that stand up from its shell, and each one ends in a little tuft of bristles.","teen":"Long, swollen eyestalks carry very large corneas on their lower half. In this species each eyestalk ends in a tuft of bristles, which tells it apart from other ghost crabs.","part":"eyes"},{"title":"A cool, damp burrow","kid":"It digs an L- or J-shaped burrow in the sand and hides there through the hottest part of the day.","teen":"Its burrow, usually with one opening facing the sea, stays cooler and more humid than surface sand, which can pass 50 °C at midday. Damp air helps its gills work.","part":"legs"},{"title":"A sand-coloured ghost","kid":"Its pale, sandy colour makes it hard to spot. It is called a ghost crab because it is pale and comes out at night.","teen":"Like most ghost crabs, it has a pale body that blends with sand, and ghost crabs can slowly shift their colouring to suit their surroundings and the time of day.","part":"shell"}],"field_note":{"place":"Israel","text":"In August 2021, at Zikim Dunes Nature Reserve in Israel, Tel Aviv University scientists found ghost crab burrows dug all around five dead loggerhead turtles washed up on the beach. The crabs had moved inland to feed."},"lab_note":"In Northern Cyprus, P. H. Strachan and colleagues found ghost crabs on 68 of 77 sandy beaches. The crabs were mostly active at night and fed on food scraps left by tourists (published in 1999).","myth":{"claim":"All crabs live in the sea.","verdict":"myth","why":"The ghost crab lives on land, in a burrow on the beach above the waves. It still needs seawater or damp sand to keep its gills wet."},"clues":["I have ten legs and a hard shell.","I dig a burrow on a sandy beach and come out at night.","I am the only ghost crab in the Mediterranean, and my eye stalks end in tufts of bristles."],"compare":{"stat":"Shell width","value":5.5,"unit":"cm","text":"up to 5.5 cm across"},"stats":[{"label":"Shell width","value":"up to 5.5 cm","note":"across the shell"},{"label":"Shell length","value":"up to 4.6 cm","note":"front to back"},{"label":"Burrow opening","value":"2–6 cm","note":"bigger crabs dig wider holes"},{"label":"Burrow depth","value":"up to about 1 m","note":"down into the sand"}],"taxonomy":["Animals","Crustaceans · Crustacea","Decapods · Decapoda","Ghost crabs and fiddler crabs · Ocypodidae","Ocypode cursor"]},"he":{"name":"חולון החוף","habitat_text":"חופי חול, במחילות שהוא חופר ליד קו הגאות או מעליו","menu":"ביצים וצבונים של צבי ים, סרטנים קטנים, חלזונות, צדפות, נמלים, בעלי חיים מתים, אצות שנפלטו לחוף ושאריות אוכל שאנשים משאירים על החוף.","iucn_note":"ה־IUCN עוד לא העריך את מצבו. הוא אחד מתשעה מיני סרטנאים ימיים שמוגנים בכל הים התיכון.","page_facts":["אני חופר את הבית שלי בחול.","אני יוצא בלילה.","העיניים שלי עומדות על גבעולים.","אני אוכל כמעט כל מה שאני מוצא."],"powers":[{"title":"עיני פריסקופ","kid":"העיניים הגדולות שלו יושבות על גבעולים ארוכים שמזדקרים מעל השריון, ובקצה של כל אחד מהם יש ציצה קטנה של זיפים.","teen":"על גבעולי העיניים הארוכים והתפוחים יש קרניות גדולות מאוד, בחצי התחתון שלהם. במין הזה כל גבעול עין מסתיים בציצת זיפים, וכך אפשר להבדיל אותו מחולונים אחרים.","part":"eyes"},{"title":"מחילה קרירה ולחה","kid":"הוא חופר בחול מחילה בצורת L או J, ומתחבא בה בשעות החמות ביותר של היום.","teen":"המחילה שלו, בדרך כלל עם פתח אחד שפונה אל הים, נשארת קרירה ולחה יותר מהחול שעל פני השטח, שיכול להתחמם ליותר מ־50 מעלות צלזיוס בצהריים. האוויר הלח עוזר לזימים שלו לעבוד.","part":"legs"},{"title":"רוח רפאים בצבע חול","kid":"הצבע החיוור שלו, בגוון של חול, מקשה לראות אותו. באנגלית קוראים לו \"סרטן רפאים\", כי הוא חיוור ויוצא בלילה.","teen":"כמו לרוב החולונים, יש לו גוף חיוור שמתמזג עם החול, וחולונים יכולים לשנות לאט את הצבע שלהם כדי להתאים לסביבה ולשעה ביום.","part":"shell"}],"field_note":{"place":"Israel","text":"באוגוסט 2021, בשמורת חולות זיקים בישראל, מצאו מדענים מאוניברסיטת תל אביב מחילות של חולונים שנחפרו מסביב לחמישה צבי ים חומים מתים שנפלטו לחוף. הסרטנים התרחקו מהים אל היבשה כדי לאכול."},"lab_note":"בצפון קפריסין מצאו פ. ה. סטרכן ועמיתים חולונים ב־68 מתוך 77 חופי חול. הסרטנים היו פעילים בעיקר בלילה ואכלו שאריות אוכל שהשאירו תיירים (המחקר פורסם ב־1999).","myth":{"claim":"כל הסרטנים חיים בים.","verdict":"myth","why":"החולון חי ביבשה, במחילה על החוף מעל הגלים. ובכל זאת הוא צריך מי ים או חול לח כדי שהזימים שלו יישארו רטובים."},"clues":["יש לי עשר רגליים ושריון קשה.","אני חופר מחילה בחוף חולי ויוצא בלילה.","אני החולון היחיד בים התיכון, וגבעולי העיניים שלי מסתיימים בציצות של זיפים."],"compare":{"stat":"Shell width","value":5.5,"unit":"cm","text":"עד 5.5 ס״מ לרוחב"},"stats":[{"label":"רוחב השריון","value":"עד 5.5 ס״מ","note":"מצד לצד"},{"label":"אורך השריון","value":"עד 4.6 ס״מ","note":"מלפנים לאחור"},{"label":"פתח המחילה","value":"2–6 ס״מ","note":"סרטנים גדולים יותר חופרים פתחים רחבים יותר"},{"label":"עומק המחילה","value":"עד בערך 1 מ׳","note":"לתוך החול"}],"taxonomy":["בעלי חיים","סרטנאים · Crustacea","עשרה־רגליים · Decapoda","חולוניים · Ocypodidae","Ocypode cursor"]}},"seaturtle":{"id":"seaturtle","i":4,"latin":"Caretta caretta","group":"reptile","home":"ocean","diet":"omni","active":"day and night","continents":["North America","South America","Europe","Africa","Asia","Australia"],"iucn":"VU","en":{"name":"Loggerhead sea turtle","habitat_text":"Warm and temperate seas, from the open ocean to coastal bays; females come ashore to nest on sandy beaches","menu":"Mostly hard-shelled animals: crabs, whelks and other sea snails, clams and sea urchins, plus jellyfish. Sometimes fish, and a little algae.","iucn_note":"Vulnerable worldwide (IUCN, 2015). The Mediterranean population, which nests in Israel, is listed as Least Concern but still faces fishing nets, building on beaches and pollution.","page_facts":["I lay about 100 eggs.","I crunch crabs with my jaws.","Warm sand makes my babies girls.","My babies crawl to the sea."],"powers":[{"title":"A big head with a crushing bite","kid":"Its big head holds strong jaw muscles that crush crabs, clams and sea snails.","teen":"The oversized head that gives the loggerhead its name anchors powerful jaw muscles, letting it crack hard-shelled prey such as whelks, conchs and crabs.","part":"head"},{"title":"Flippers for flying and digging","kid":"It flaps its front flippers like wings to fly through the water. On the beach, a mother digs her nest with her back flippers.","teen":"Long front flippers sweep in a figure-8 pattern to drive it through water while the rear flippers steer; a nesting female uses her rear flippers to dig a flask-shaped egg chamber.","part":"flippers"},{"title":"Salty tears","kid":"Glands behind its eyes push out the extra salt it takes in from the sea, as salty tears.","teen":"Lachrymal salt glands behind each eye pour out very salty fluid, keeping the body's salt balance while it lives in seawater and eats salty prey.","part":"eyes"}],"field_note":{"place":"Israel","text":"Since the 1980s, Israel Nature and Parks Authority rangers have guarded loggerhead nests on Israel's Mediterranean beaches, moving some to protected hatcheries. A rescue centre opened in 1999 treats injured sea turtles and returns most to the sea."},"lab_note":"In 2001, Kenneth Lohmann's team at the University of North Carolina showed that loggerhead hatchlings sense magnetic fields: in a pool, they swam in directions that would keep them on their ocean migration route.","myth":{"claim":"A turtle can climb out of its shell.","verdict":"myth","why":"The shell is part of its skeleton: the backbone and ribs are joined to it. A turtle can never leave its shell."},"clues":["I have a hard shell and lay my eggs on land.","I live in the sea and swim with flippers.","I am a sea turtle named for my big head, and I nest on Israel's beaches."],"compare":{"stat":"Weight","value":160,"unit":"kg","text":"up to about 160 kg"},"stats":[{"label":"Shell length","value":"76–107 cm","note":"adults; about 90 cm on average"},{"label":"Hatchling shell","value":"about 4–5 cm","note":"just out of the egg"},{"label":"Weight","value":"90–160 kg","note":"adults"},{"label":"Eggs per nest","value":"about 100","note":"a female may lay 3–5 nests in one season"}],"taxonomy":["Animals","Reptiles · Reptilia","Turtles · Testudines","Sea turtles · Cheloniidae","Caretta caretta"]},"he":{"name":"צב ים חום","habitat_text":"ימים חמים וממוזגים, מהאוקיינוס הפתוח ועד מפרצים ליד החוף; הנקבות עולות ליבשה כדי לקנן בחופי חול","menu":"בעיקר בעלי חיים עם קונכייה או שריון קשה: סרטנים, חלזונות ים גדולים ואחרים, צדפות וקיפודי ים, וגם מדוזות. לפעמים דגים, וקצת אצות.","iucn_note":"פגיע בכל העולם (IUCN, 2015). האוכלוסייה של הים התיכון, שמקננת בישראל, מוגדרת \"ללא חשש\", אבל היא עדיין מאוימת על ידי רשתות דיג, בנייה על החופים וזיהום.","page_facts":["אני מטיל בערך 100 ביצים.","אני מפצח סרטנים בלסתות שלי.","חול חם הופך את הצבונים שלי לנקבות.","הצבונים שלי זוחלים אל הים."],"powers":[{"title":"ראש גדול ונשיכה מרסקת","kid":"בראש הגדול שלו יש שרירי לסת חזקים, שמרסקים סרטנים, צדפות וחלזונות ים.","teen":"הראש הגדול במיוחד, שעל שמו המין נקרא באנגלית loggerhead, מחזיק שרירי לסת חזקים, וכך הוא יכול לפצח טרף עם קונכייה קשה, כמו חלזונות ים גדולים וסרטנים.","part":"head"},{"title":"סנפירים לעוף ולחפור","kid":"הוא מנפנף בסנפירים הקדמיים כמו בכנפיים ו\"עף\" במים. על החוף, האם חופרת את הקן שלה בסנפירים האחוריים.","teen":"הסנפירים הקדמיים הארוכים נעים בתנועה בצורת הספרה 8 ודוחפים אותו במים, והסנפירים האחוריים מכוונים; נקבה מקננת חופרת בסנפירים האחוריים תא ביצים בצורת בקבוק.","part":"flippers"},{"title":"דמעות מלוחות","kid":"בלוטות מאחורי העיניים מוציאות את המלח העודף שנכנס לגוף מהים, בצורת דמעות מלוחות.","teen":"בלוטות מלח דמעיות מאחורי כל עין מפרישות נוזל מלוח מאוד, ושומרות על מאזן המלח בגוף בזמן שהוא חי במי ים ואוכל טרף מלוח.","part":"eyes"}],"field_note":{"place":"Israel","text":"מאז שנות ה־80 פקחי רשות הטבע והגנים שומרים על קנים של צבי ים חומים בחופי הים התיכון של ישראל, ומעבירים חלק מהם למדגרות מוגנות. מרכז הצלה שנפתח ב־1999 מטפל בצבי ים פצועים ומחזיר את רובם לים."},"lab_note":"ב־2001 הראה הצוות של קנת לוהמן באוניברסיטת צפון קרוליינה שצבונים של צב ים חום חשים שדות מגנטיים: בבריכה הם שחו בכיוונים שהיו משאירים אותם על נתיב הנדידה שלהם באוקיינוס.","myth":{"claim":"צב יכול לצאת מהשריון שלו.","verdict":"myth","why":"השריון הוא חלק מהשלד: עמוד השדרה והצלעות מחוברים אליו. צב אף פעם לא יכול לצאת מהשריון שלו."},"clues":["יש לי שריון קשה, ואני מטיל את הביצים שלי ביבשה.","אני חי בים ושוחה בעזרת סנפירים.","אני צב ים שהשם שלי באנגלית בא מהראש הגדול שלי, ואני מקנן בחופי ישראל."],"compare":{"stat":"Weight","value":160,"unit":"kg","text":"עד כ־160 ק״ג"},"stats":[{"label":"אורך השריון","value":"76–107 ס״מ","note":"בוגרים; בממוצע בערך 90 ס״מ"},{"label":"שריון של צבון","value":"בערך 4–5 ס״מ","note":"רגע אחרי שבקע מהביצה"},{"label":"משקל","value":"90–160 ק״ג","note":"בוגרים"},{"label":"ביצים בקן","value":"בערך 100","note":"נקבה עשויה להטיל ב־3–5 קנים בעונה אחת"}],"taxonomy":["בעלי חיים","זוחלים · Reptilia","צבים · Testudines","צבי ים · Cheloniidae","Caretta caretta"]}},"puffer":{"id":"puffer","i":5,"latin":"Arothron hispidus","group":"fish","home":"ocean","diet":"omni","active":null,"continents":["Africa","Asia","Australia","North America"],"iucn":"LC","en":{"name":"White-spotted puffer","habitat_text":"Coral reefs, lagoons and sandy or rubble sea floor, 1–50 m deep; young ones in estuaries and on shallow sandy shores","menu":"Fleshy and chalky algae, sponges, corals, sea snails, clams, crabs, tube worms, starfish and sea urchins, crushed with its beak.","iucn_note":"Least Concern (IUCN, assessed 2011). It lives across a huge area, from the Red Sea and East Africa to Hawaii, and along the Pacific coast from Mexico to Panama.","page_facts":["I puff up like a ball.","I have white spots all over.","My teeth make a hard beak.","I am poisonous to eat."],"powers":[{"title":"Puffing up","kid":"When it is scared, it gulps water into a stretchy stomach and swells up, too big and awkward for most hunters to handle.","teen":"It pumps water into a very elastic stomach. Its short ribs do not form a cage around the stomach, so the whole body can swell to two or three times its normal width.","part":"belly"},{"title":"A beak of four teeth","kid":"Its four teeth are joined into a strong beak that crunches crabs, snails and hard, chalky algae.","teen":"The family name Tetraodontidae means 'four teeth': the upper and lower teeth are fused into beak-like plates that crush shelled animals and scrape coralline algae.","part":"mouth"},{"title":"Poison skin","kid":"Its skin and some organs hold a strong poison called tetrodotoxin, so it is very dangerous to eat.","teen":"Tetrodotoxin is a powerful nerve poison, probably made by bacteria living inside pufferfish. Tests on this species found the highest amounts in the skin, with less in the liver, ovaries and flesh.","part":"skin"}],"field_note":{"place":"Israel","text":"Scientists have collected white-spotted puffers in the Gulf of Eilat since 1949, and many are kept in the Hebrew University fish collection. Divers still photograph them on Eilat's reefs today."},"lab_note":"In 2015, chemists at Tohoku University in Japan tested white-spotted puffers from the Solomon Islands and Okinawa. The poison tetrodotoxin was most concentrated in the skin, so they advised that these fish should not be eaten.","myth":{"claim":"A pufferfish fills itself with air.","verdict":"myth","why":"In the sea it pumps water into its stretchy stomach. It only takes in air when it is pulled out of the water."},"clues":["I swim slowly over coral reefs.","When I am scared, I swell up into a ball.","I am grey with many small white spots, and white rings circle my eyes and side fins."],"compare":{"stat":"Length","value":50,"unit":"cm","text":"up to 50 cm"},"stats":[{"label":"Length","value":"up to 50 cm","note":"nose to tail"},{"label":"Puffed-up size","value":"2–3 times wider","note":"when it swells with water"},{"label":"Weight","value":"up to 2 kg","note":"heaviest recorded"},{"label":"Depth","value":"1–50 m","note":"where it lives"}],"taxonomy":["Animals","Ray-finned fishes · Actinopterygii","Pufferfishes and relatives · Tetraodontiformes","Pufferfishes · Tetraodontidae","Arothron hispidus"]},"he":{"name":"נפוחית לבנת־כתמים","habitat_text":"שוניות אלמוגים, לגונות וקרקעית ים של חול או של שברי סלעים, בעומק 1–50 מ׳; הצעירות חיות בשפכי נהרות ובחופי חול רדודים","menu":"אצות בשרניות ואצות גירניות, ספוגים, אלמוגים, חלזונות ים, צדפות, סרטנים, תולעי צינור, כוכבי ים וקיפודי ים. היא מרסקת אותם במקור שלה.","iucn_note":"ללא חשש (IUCN, הערכה מ־2011). היא חיה באזור עצום, מהים האדום ומזרח אפריקה ועד הוואי, ולאורך חוף האוקיינוס השקט ממקסיקו ועד פנמה.","page_facts":["אני מתנפחת כמו כדור.","יש לי כתמים לבנים על כל הגוף.","השיניים שלי יוצרות מקור קשה.","אני רעילה כשאוכלים אותי."],"powers":[{"title":"להתנפח","kid":"כשהיא מפחדת, היא בולעת מים לתוך קיבה גמישה ומתנפחת, וכך היא גדולה ומגושמת מדי בשביל רוב הטורפים.","teen":"היא שואבת מים לתוך קיבה גמישה מאוד. הצלעות הקצרות שלה לא יוצרות כלוב סביב הקיבה, ולכן כל הגוף יכול להתנפח לרוחב של פי שניים או שלושה מהרגיל.","part":"belly"},{"title":"מקור של ארבע שיניים","kid":"ארבע השיניים שלה מחוברות למקור חזק, שמפצח סרטנים, חלזונות ואצות גירניות קשות.","teen":"שם המשפחה Tetraodontidae פירושו \"ארבע שיניים\": השיניים העליונות והתחתונות מאוחות ללוחות דמויי מקור, שמרסקים בעלי חיים עם קונכייה ומגרדים אצות אלמוגיות.","part":"mouth"},{"title":"עור רעיל","kid":"בעור שלה ובכמה מהאיברים שלה יש רעל חזק בשם טטרודוטוקסין, ולכן מסוכן מאוד לאכול אותה.","teen":"טטרודוטוקסין הוא רעל עצבים חזק, שכנראה מייצרים חיידקים שחיים בתוך נפוחיות. בבדיקות של המין הזה נמצאו הכמויות הגבוהות ביותר בעור, ופחות בכבד, בשחלות ובבשר.","part":"skin"}],"field_note":{"place":"Israel","text":"מדענים אוספים נפוחיות לבנות־כתמים במפרץ אילת מאז 1949, ורבות מהן שמורות באוסף הדגים של האוניברסיטה העברית. צוללנים מצלמים אותן בשוניות של אילת גם היום."},"lab_note":"ב־2015 בדקו כימאים מאוניברסיטת טוהוקו ביפן נפוחיות לבנות־כתמים מאיי שלמה ומאוקינאווה. הרעל טטרודוטוקסין היה מרוכז בעיקר בעור, ולכן הם המליצו לא לאכול את הדגים האלה.","myth":{"claim":"נפוחית מתמלאת באוויר.","verdict":"myth","why":"בים היא שואבת מים לתוך הקיבה הגמישה שלה. היא בולעת אוויר רק כשמוציאים אותה מהמים."},"clues":["אני שוחה לאט מעל שוניות אלמוגים.","כשאני מפחדת, אני מתנפחת לכדור.","אני אפורה עם הרבה כתמים לבנים קטנים, וטבעות לבנות מקיפות את העיניים שלי ואת סנפירי הצד."],"compare":{"stat":"Length","value":50,"unit":"cm","text":"עד 50 ס״מ"},"stats":[{"label":"אורך","value":"עד 50 ס״מ","note":"מהאף עד הזנב"},{"label":"גודל כשהיא נפוחה","value":"פי 2–3 ברוחב","note":"כשהיא מתמלאת במים"},{"label":"משקל","value":"עד 2 ק״ג","note":"הכבדה ביותר שנמדדה"},{"label":"עומק","value":"1–50 מ׳","note":"שבו היא חיה"}],"taxonomy":["בעלי חיים","מקריני סנפיר · Actinopterygii","נפוחיתאים · Tetraodontiformes","נפוחיתיים · Tetraodontidae","Arothron hispidus"]}},"bear":{"id":"bear","i":6,"latin":"Ursus arctos","group":"mammal","home":"forest","diet":"omni","active":"dawn and dusk","continents":["North America","Europe","Asia"],"iucn":"LC","en":{"name":"Brown bear","habitat_text":"Forests, mountains, meadows and tundra","menu":"Mostly plants: grass, roots, berries and nuts. Also insects, fish such as salmon, dead animals and sometimes young elk or moose. It will raid a beehive for honey.","iucn_note":"Least Concern worldwide. Some small populations are in trouble, such as the Syrian brown bear of the Middle East, which has disappeared from Israel and Jordan.","page_facts":["I sleep through winter in a den.","I eat berries, roots and fish.","My nose smells food from far away.","I have long claws for digging."],"powers":[{"title":"A digging engine","kid":"The hump on its shoulders is a big muscle. It gives the front legs power for digging.","teen":"The shoulder hump is a mass of muscle that powers the forelimbs, letting the bear dig out roots, burrowing rodents and its winter den.","part":"shoulder hump"},{"title":"Rake-like claws","kid":"Its front claws are 5–10 cm long and only a little curved, like a garden rake.","teen":"Long, gently curved front claws, 5–10 cm long, work like a rake, tearing up turf and soil to reach roots, bulbs and burrowing animals.","part":"front claws"},{"title":"A super nose","kid":"Its nose is amazing. A brown bear may smell food more than 1.5 km away.","teen":"Smell is its main sense for finding food. Park biologists report that brown bears may detect odours more than 1.6 km away, leading them to carcasses and other food.","part":"nose"}],"field_note":{"place":"Israel","text":"The Bible tells how young David guarded his sheep from a lion and a bear. Bears of the Bible were Syrian brown bears, pale and straw-coloured. They vanished from the Land of Israel by the early 1900s."},"lab_note":"In south-eastern Alaska, Volker Deecke (University of Cumbria) watched a young brown bear pick up barnacle-covered rocks and rub its neck and muzzle with them: the first report of tool use by a wild brown bear.","myth":{"claim":"Bears live mostly on honey.","verdict":"myth","why":"Brown bears will raid a beehive for honey, but most of their food is plants such as grass, roots and berries, plus insects, fish and meat."},"clues":["I sleep through the winter in a den.","I dig with long claws and catch fish in rivers.","I'm a big brown bear with a muscle hump on my shoulders."],"compare":{"stat":"Weight","value":600,"unit":"kg","text":"up to about 600 kg"},"stats":[{"label":"Length","value":"1–2.8 m","note":"nose to rump"},{"label":"Shoulder height","value":"up to 1.5 m","note":"standing on all fours"},{"label":"Weight","value":"80–600 kg","note":"males much heavier than females"},{"label":"Top speed","value":"about 56 km/h","note":"in a short sprint"}],"taxonomy":["Animals","Mammals · Mammalia","Carnivores · Carnivora","Bears · Ursidae","Ursus arctos"]},"he":{"name":"דוב חום","habitat_text":"יערות, הרים, כרי דשא וטונדרה","menu":"בעיקר צמחים: עשב, שורשים, פירות יער ואגוזים. וגם חרקים, דגים כמו סלמון, בעלי חיים מתים, ולפעמים וַפִּיטִים או מוסים צעירים. הוא גם פושט על כוורת כדי לאכול דבש.","iucn_note":"ללא חשש בכל העולם. כמה אוכלוסיות קטנות בצרה, כמו הדוב החום הסורי של המזרח התיכון, שנעלם מישראל ומירדן.","page_facts":["אני ישן כל החורף במאורה.","אני אוכל פירות יער, שורשים ודגים.","האף שלי מריח אוכל מרחוק.","יש לי ציפורניים ארוכות לחפירה."],"powers":[{"title":"מנוע חפירה","kid":"הדבשת שעל הכתפיים שלו היא שריר גדול. היא נותנת לרגליים הקדמיות כוח לחפור.","teen":"דבשת הכתפיים היא גוש של שריר שמניע את הגפיים הקדמיות, וכך הדוב יכול לחפור ולהוציא שורשים ומכרסמים שחיים במחילות, ולחפור את מאורת החורף שלו.","part":"shoulder hump"},{"title":"טפרים כמו מגרפה","kid":"הציפורניים הקדמיות שלו באורך 5–10 ס״מ ומעוקלות רק קצת, כמו מגרפה של גינה.","teen":"הטפרים הקדמיים, ארוכים ומעוקלים מעט, באורך 5–10 ס״מ, פועלים כמו מגרפה: הם תולשים דשא ואדמה כדי להגיע לשורשים, לפקעות ולבעלי חיים שחיים במחילות.","part":"front claws"},{"title":"אף מופלא","kid":"האף שלו מדהים. דוב חום עשוי להריח אוכל ממרחק של יותר מ־1.5 ק״מ.","teen":"חוש הריח הוא החוש העיקרי שלו למציאת מזון. ביולוגים בפארקים הלאומיים מדווחים שדובים חומים עשויים לקלוט ריחות ממרחק של יותר מ־1.6 ק״מ, והריחות מובילים אותם לפגרים ולמזון אחר.","part":"nose"}],"field_note":{"place":"Israel","text":"התנ״ך מספר איך דוד הצעיר שמר על הצאן שלו מפני אריה ודוב. הדובים של התנ״ך היו דובים חומים סוריים, בהירים ובצבע קש. הם נעלמו מארץ ישראל עד תחילת המאה ה־20."},"lab_note":"בדרום־מזרח אלסקה צפה פולקר דיקה (אוניברסיטת קמבריה) בדוב חום צעיר שהרים אבנים מכוסות בלוטי ים ושפשף בהן את הצוואר ואת החוטם שלו: הדיווח הראשון על שימוש בכלי אצל דוב חום בטבע.","myth":{"claim":"דובים ניזונים בעיקר מדבש.","verdict":"myth","why":"דובים חומים אכן פושטים על כוורות כדי לאכול דבש, אבל רוב המזון שלהם הוא צמחים כמו עשב, שורשים ופירות יער, וגם חרקים, דגים ובשר."},"clues":["אני ישן כל החורף במאורה.","אני חופר בציפורניים ארוכות ותופס דגים בנהרות.","אני דוב חום גדול, עם דבשת של שריר על הכתפיים."],"compare":{"stat":"Weight","value":600,"unit":"kg","text":"עד כ־600 ק״ג"},"stats":[{"label":"אורך","value":"1–2.8 מ׳","note":"מהאף עד האחוריים"},{"label":"גובה הכתפיים","value":"עד 1.5 מ׳","note":"כשהוא עומד על ארבע"},{"label":"משקל","value":"80–600 ק״ג","note":"הזכרים כבדים הרבה יותר מהנקבות"},{"label":"מהירות מרבית","value":"בערך 56 קמ״ש","note":"בריצה קצרה"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","טורפים · Carnivora","דוביים · Ursidae","Ursus arctos"]}},"fox":{"id":"fox","i":7,"latin":"Vulpes vulpes","group":"mammal","home":"forest","diet":"omni","active":"night","continents":["North America","Europe","Asia","Africa"],"iucn":"LC","en":{"name":"Red fox","habitat_text":"Forests, farmland, grassland, deserts and even cities","menu":"Mostly mice and voles, also rabbits, birds, insects and other small animals, plus fruit and berries. It hides spare food and is very good at finding it again.","iucn_note":"Least Concern: one of the most widespread wild carnivores on Earth. People brought it to Australia, where it now hunts native rodents and marsupials.","page_facts":["I can hear mice under snow.","I pounce on mice from above.","My tail keeps my nose warm.","I eat mice, fruit and insects."],"powers":[{"title":"Radar ears","kid":"Its big ears can hear a mouse squeak under the snow, up to about 30 metres away.","teen":"Its ears pick up both low rustling and high squeaks; a fox can locate a rodent about 30 m away beneath roughly a metre of snow.","part":"ears"},{"title":"A tail that is a blanket","kid":"In cold wind it wraps its bushy tail over its nose and feet, and it steers with its tail when it leaps.","teen":"The long, bushy tail covers the bare nose and foot pads in winter wind and acts as a rudder during the high, arcing 'mousing' leap.","part":"tail"},{"title":"A snow-diving snout","kid":"Its pointed snout slices into snow, so it can dive in head first after a mouse without getting hurt.","teen":"Cornell engineers dropped 3D-printed fox skulls into fresh snow: the sharper the snout, the lower the impact force, so foxes can dive headfirst without injury.","part":"snout"}],"field_note":{"place":"Israel","text":"The red fox is Israel's most common fox and lives along the whole country. One local kind is even named after this region: Vulpes vulpes palaestina."},"lab_note":"In the Czech Republic, Jaroslav Červený and colleagues recorded wild red foxes pouncing on hidden prey. Jumps aimed roughly north-east succeeded far more often than others. They suggest foxes may use Earth's magnetic field to aim.","myth":{"claim":"Foxes live only in wild forests and fields.","verdict":"myth","why":"Red foxes moved into most British cities over 80 years ago, and some cities have several times more foxes per area than the countryside."},"clues":["I have a long, bushy tail.","I leap high and pounce on mice hiding in grass or snow.","I'm orange-red, with a white tip on my bushy tail."],"compare":{"stat":"Top speed","value":48,"unit":"km/h","text":"about 48–50 km/h"},"stats":[{"label":"Length","value":"45–90 cm","note":"head and body"},{"label":"Tail","value":"30–55 cm","note":"bushy, with a white tip"},{"label":"Weight","value":"2.2–14 kg","note":"females lighter than males"},{"label":"Top speed","value":"about 48–50 km/h","note":"running flat out"}],"taxonomy":["Animals","Mammals · Mammalia","Carnivores · Carnivora","Dog family · Canidae","Vulpes vulpes"]},"he":{"name":"שועל מצוי","habitat_text":"יערות, שדות חקלאיים, שטחי עשב, מדבריות ואפילו ערים","menu":"בעיקר עכברים ונברנים, וגם ארנבים, ציפורים, חרקים ובעלי חיים קטנים אחרים, וגם פירות ופירות יער. הוא מחביא מזון עודף, ויודע היטב למצוא אותו שוב.","iucn_note":"ללא חשש: אחד מטורפי הבר הנפוצים ביותר בכדור הארץ. בני אדם הביאו אותו לאוסטרליה, ושם הוא צד היום מכרסמים וחיות כיס מקומיים.","page_facts":["אני שומע עכברים מתחת לשלג.","אני קופץ על עכברים מלמעלה.","הזנב שלי מחמם לי את האף.","אני אוכל עכברים, פירות וחרקים."],"powers":[{"title":"אוזני מכ״ם","kid":"האוזניים הגדולות שלו שומעות עכבר מצייץ מתחת לשלג, ממרחק של עד בערך 30 מטרים.","teen":"האוזניים שלו קולטות גם רשרוש נמוך וגם ציוצים גבוהים; שועל יכול לאתר מכרסם במרחק של בערך 30 מ׳, מתחת לשכבת שלג של כמטר.","part":"ears"},{"title":"זנב שהוא שמיכה","kid":"ברוח קרה הוא עוטף את האף ואת כפות הרגליים בזנב העבות שלו, והוא מנווט בעזרת הזנב כשהוא קופץ.","teen":"הזנב הארוך והעבות מכסה את האף החשוף ואת כריות כפות הרגליים ברוח החורף, ומשמש כהגה בזמן \"קפיצת העכבר\", הקפיצה הגבוהה בקשת שבה הוא צד.","part":"tail"},{"title":"חוטם שצולל לשלג","kid":"החוטם המחודד שלו חותך את השלג, וכך הוא יכול לצלול פנימה עם הראש קדימה אחרי עכבר בלי להיפגע.","teen":"מהנדסים מאוניברסיטת קורנל הפילו גולגולות שועל מודפסות בתלת־ממד לתוך שלג טרי: ככל שהחוטם חד יותר, כוח המכה נמוך יותר, וכך שועלים יכולים לצלול עם הראש קדימה בלי להיפצע.","part":"snout"}],"field_note":{"place":"Israel","text":"השועל המצוי הוא השועל הנפוץ ביותר בישראל, והוא חי לאורך כל הארץ. תת־מין מקומי אחד אפילו נקרא על שם האזור הזה: Vulpes vulpes palaestina."},"lab_note":"בצ׳כיה תיעדו ירוסלב צ׳רבני ועמיתים שועלים מצויים בטבע מזנקים על טרף מוסתר. קפיצות בכיוון צפון־מזרח בערך הצליחו הרבה יותר מאחרות. לדעת החוקרים, ייתכן ששועלים משתמשים בשדה המגנטי של כדור הארץ כדי לכוון.","myth":{"claim":"שועלים חיים רק ביערות ובשדות בטבע.","verdict":"myth","why":"שועלים מצויים עברו לגור ברוב הערים בבריטניה לפני יותר מ־80 שנה, ובכמה ערים יש פי כמה יותר שועלים על אותו שטח מאשר באזורים הכפריים."},"clues":["יש לי זנב ארוך ועבות.","אני קופץ גבוה ומזנק על עכברים שמסתתרים בעשב או בשלג.","אני כתום־אדמדם, ויש קצה לבן לזנב העבות שלי."],"compare":{"stat":"Top speed","value":48,"unit":"km/h","text":"בערך 48–50 קמ״ש"},"stats":[{"label":"אורך","value":"45–90 ס״מ","note":"ראש וגוף"},{"label":"זנב","value":"30–55 ס״מ","note":"עבות, עם קצה לבן"},{"label":"משקל","value":"2.2–14 ק״ג","note":"הנקבות קלות מהזכרים"},{"label":"מהירות מרבית","value":"בערך 48–50 קמ״ש","note":"בריצה במלוא המהירות"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","טורפים · Carnivora","כלביים · Canidae","Vulpes vulpes"]}},"wolf":{"id":"wolf","i":8,"latin":"Canis lupus","group":"mammal","home":"forest","diet":"carn","active":"day and night","continents":["North America","Europe","Asia"],"iucn":"LC","en":{"name":"Grey wolf","habitat_text":"Forests, grasslands, tundra, mountains and deserts","menu":"Mostly hoofed animals such as deer, elk and moose, hunted as a pack. Also smaller animals and dead animals it finds. Now and then, fruit and berries.","iucn_note":"Least Concern: about 200,000–250,000 wolves live in the wild. People wiped wolves out of many places where they once lived. In Israel, wolves are protected by law.","page_facts":["I live with my family pack.","I howl to call my family.","I hunt deer with my pack.","My babies are called pups."],"powers":[{"title":"A long-range nose","kid":"Its nose can smell prey at least 2.4 km away.","teen":"Smell is its key hunting sense: wolves can scent prey at least 2.4 km away and read the scent marks other packs leave on their borders.","part":"nose"},{"title":"Legs for the long haul","kid":"Long legs let it trot for hours. A wolf travels about 25 km a day on average.","teen":"Legs long for its body size and an energy-saving trot let a wolf cover about 25 km a day on average, and up to 76 km in 12 hours.","part":"legs"},{"title":"A voice that carries","kid":"Its howl carries far, so pack members can find each other.","teen":"Howling keeps a scattered pack in touch and warns rival packs away; in good conditions a howl can be heard across an area of up to 130 km².","part":"throat"}],"field_note":{"place":"Israel","text":"Israel has a few hundred wild wolves. In the Negev and Arava live Arabian wolves, among the smallest wolves on Earth at about 20 kg, with big ears that probably help them shed heat."},"lab_note":"On Ellesmere Island in the Canadian Arctic, L. David Mech (US Geological Survey) watched wild wolves over 13 summers. He found a pack is usually a family: two parents leading their young, not rivals battling to be 'alpha'.","myth":{"claim":"Wolves howl at the moon.","verdict":"myth","why":"The moon makes no difference. Wolves howl to keep in touch with their pack and warn other packs away, and they are often active at night."},"clues":["I live in a family called a pack.","I howl to talk to my pack.","Pet dogs are my closest living relatives."],"compare":{"stat":"Top speed","value":60,"unit":"km/h","text":"about 50–60 km/h in a sprint"},"stats":[{"label":"Length","value":"1–1.6 m","note":"head and body; the tail adds 30–56 cm"},{"label":"Shoulder height","value":"66–85 cm","note":"standing"},{"label":"Weight","value":"13–78 kg","note":"average about 40 kg; desert wolves smallest"},{"label":"One meal","value":"up to 10 kg","note":"of meat at one sitting"}],"taxonomy":["Animals","Mammals · Mammalia","Carnivores · Carnivora","Dog family · Canidae","Canis lupus"]},"he":{"name":"זאב","habitat_text":"יערות, שטחי עשב, טונדרה, הרים ומדבריות","menu":"בעיקר בעלי פרסות, כמו איילים, וַפִּיטִים ומוסים, שהוא צד עם הלהקה. וגם בעלי חיים קטנים יותר ובעלי חיים מתים שהוא מוצא. מדי פעם גם פירות ופירות יער.","iucn_note":"ללא חשש: בערך 200,000–250,000 זאבים חיים בטבע. בני אדם השמידו זאבים במקומות רבים שבהם הם חיו פעם. בישראל זאבים מוגנים בחוק.","page_facts":["אני חי עם הלהקה המשפחתית שלי.","אני מיילל כדי לקרוא למשפחה שלי.","אני צד איילים עם הלהקה שלי.","לתינוקות שלי קוראים גורים."],"powers":[{"title":"אף לטווח ארוך","kid":"האף שלו יכול להריח טרף ממרחק של 2.4 ק״מ לפחות.","teen":"חוש הריח הוא חוש הציד העיקרי שלו: זאבים יכולים להריח טרף ממרחק של 2.4 ק״מ לפחות, ולקרוא את סימני הריח שלהקות אחרות משאירות בגבולות שלהן.","part":"nose"},{"title":"רגליים למרחקים ארוכים","kid":"בזכות הרגליים הארוכות הוא יכול לרוץ ריצה קלה במשך שעות. זאב עובר בממוצע בערך 25 ק״מ ביום.","teen":"רגליים ארוכות ביחס לגודל הגוף וריצה קלה שחוסכת אנרגיה מאפשרות לזאב לעבור בממוצע בערך 25 ק״מ ביום, ועד 76 ק״מ ב־12 שעות.","part":"legs"},{"title":"קול שמגיע רחוק","kid":"היללה שלו נשמעת למרחקים, וכך בני הלהקה יכולים למצוא זה את זה.","teen":"היללות שומרות על קשר בין בני להקה מפוזרת ומזהירות להקות יריבות להתרחק; בתנאים טובים אפשר לשמוע יללה בשטח של עד 130 קמ״ר.","part":"throat"}],"field_note":{"place":"Israel","text":"בישראל חיים כמה מאות זאבים בטבע. בנגב ובערבה חיים זאבים ערביים, מהזאבים הקטנים ביותר בכדור הארץ, במשקל של בערך 20 ק״ג, עם אוזניים גדולות שכנראה עוזרות להם להיפטר מחום."},"lab_note":"באי אלסמיר שבארקטיקה הקנדית צפה ל. דייוויד מיץ׳ (המכון הגאולוגי של ארצות הברית) בזאבים בטבע במשך 13 קיצים. הוא גילה שלהקה היא בדרך כלל משפחה: שני הורים שמובילים את הצאצאים שלהם, ולא יריבים שנלחמים מי יהיה \"אלפא\".","myth":{"claim":"זאבים מייללים אל הירח.","verdict":"myth","why":"לירח אין שום השפעה. זאבים מייללים כדי לשמור על קשר עם הלהקה ולהזהיר להקות אחרות להתרחק, ולעיתים קרובות הם פעילים בלילה."},"clues":["אני חי במשפחה שנקראת להקה.","אני מיילל כדי לדבר עם הלהקה שלי.","מבין כל בעלי החיים היום, כלבי הבית הם הקרובים ביותר אליי."],"compare":{"stat":"Top speed","value":60,"unit":"km/h","text":"בערך 50–60 קמ״ש בריצה מהירה"},"stats":[{"label":"אורך","value":"1–1.6 מ׳","note":"ראש וגוף; הזנב מוסיף 30–56 ס״מ"},{"label":"גובה הכתפיים","value":"66–85 ס״מ","note":"בעמידה"},{"label":"משקל","value":"13–78 ק״ג","note":"בממוצע בערך 40 ק״ג; זאבי המדבר הכי קטנים"},{"label":"ארוחה אחת","value":"עד 10 ק״ג","note":"של בשר, בבת אחת"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","טורפים · Carnivora","כלביים · Canidae","Canis lupus"]}},"owl":{"id":"owl","i":9,"latin":"Tyto alba","group":"bird","home":"farm","diet":"carn","active":"night","continents":["Europe","Africa","Asia"],"iucn":"LC","en":{"name":"Barn owl","habitat_text":"Open country: farmland, grassland, marshes and savanna","menu":"Mostly mice, voles, rats and shrews, swallowed whole; sometimes small birds or lizards. Fur and bones come back up later as a pellet.","iucn_note":"Least Concern. Barn owls of the Americas and of South-East Asia and Australia are now counted as separate sister species. A local danger is rat poison: owls that eat poisoned rodents can die.","page_facts":["I hunt at night.","I hear mice in the dark.","I fly almost without a sound.","I don't hoot. I screech!"],"powers":[{"title":"A face like a satellite dish","kid":"Its heart-shaped face works like a satellite dish, catching sounds and sending them to its ears.","teen":"Stiff feathers form a facial disc, a ruff that reflects and channels sound into the ear openings, much like a satellite dish.","part":"face"},{"title":"Lopsided ears","kid":"One ear opening is higher than the other, so it can tell if a squeak comes from above or below.","teen":"Its ear openings are asymmetrical, one higher than the other, so a sound arrives slightly differently at each ear, letting it pinpoint prey up-down as well as left-right.","part":"ears"},{"title":"Silent wings","kid":"Comb-like edges and soft, fringed feathers on its wings hush the air, so a mouse cannot hear it coming.","teen":"Tiny serrations on the leading edge of the flight feathers, a hair-like fringe on the trailing edge and velvety feather surfaces break up turbulence and muffle flight noise.","part":"wing edge"}],"field_note":{"place":"Israel","text":"In 1983, 14 nest boxes for barn owls went up at Kibbutz Sde Eliyahu. By 2020 Israel had over 5,000. A pair and its chicks eat 2,000–6,000 rodents a year, so farmers need less poison."},"lab_note":"In the 1970s, Roger Payne showed barn owls can catch prey in total darkness by sound alone. Masakazu Konishi then trained an owl, named Roger, to strike at loudspeakers: it aimed to within about 1–2 degrees.","myth":{"claim":"Owls can turn their heads all the way around.","verdict":"myth","why":"Owls can turn their heads about 270 degrees, not a full circle. Their big eyes are fixed in their sockets, so the whole head turns instead."},"clues":["I fly almost without a sound.","I hunt mice in the dark by listening.","My pale face is shaped like a heart, and I screech instead of hooting."],"compare":{"stat":"Wingspan","value":95,"unit":"cm","text":"up to 95 cm"},"stats":[{"label":"Length","value":"33–39 cm","note":"beak to tail"},{"label":"Wingspan","value":"80–95 cm","note":"tip to tip"},{"label":"Weight","value":"about 310–360 g","note":"average adults; females heavier"},{"label":"Rodents eaten","value":"2,000–6,000 a year","note":"one pair and its chicks"}],"taxonomy":["Animals","Birds · Aves","Owls · Strigiformes","Barn owls · Tytonidae","Tyto alba"]},"he":{"name":"תנשמת","habitat_text":"שטחים פתוחים: שדות חקלאיים, שטחי עשב, ביצות וסוואנה","menu":"בעיקר עכברים, נברנים, חולדות וחדפים, שנבלעים בשלמותם; לפעמים גם ציפורים קטנות או לטאות. הפרווה והעצמות נפלטות אחר כך בחזרה, בגוש שנקרא צנפה.","iucn_note":"ללא חשש. התנשמות של יבשות אמריקה, ושל דרום־מזרח אסיה ואוסטרליה, נחשבות היום למינים אחים נפרדים. סכנה מקומית היא רעל עכברים: תנשמות שאוכלות מכרסמים מורעלים עלולות למות.","page_facts":["אני צדה בלילה.","אני שומעת עכברים בחושך.","אני עפה כמעט בלי קול.","אני לא עושה הו־הו. אני צורחת!"],"powers":[{"title":"פנים כמו צלחת לוויין","kid":"הפנים שלה, בצורת לב, פועלות כמו צלחת לוויין: הן אוספות צלילים ומעבירות אותם אל האוזניים.","teen":"נוצות נוקשות יוצרות דיסקת פנים: צווארון נוצות שמחזיר את הקול ומתעל אותו אל פתחי האוזניים, בדומה לצלחת לוויין.","part":"face"},{"title":"אוזניים בגבהים שונים","kid":"פתח אוזן אחד גבוה מהשני, כך שהיא יודעת אם צפצוף מגיע מלמעלה או מלמטה.","teen":"פתחי האוזניים שלה אסימטריים, אחד גבוה מהשני, ולכן צליל מגיע מעט אחרת לכל אוזן. כך היא מאתרת טרף במדויק גם למעלה ולמטה, ולא רק ימינה ושמאלה.","part":"ears"},{"title":"כנפיים שקטות","kid":"קצוות דמויי מסרק ונוצות רכות עם פרנזים על הכנפיים משקיטים את רעש האוויר, כך שעכבר לא שומע אותה מתקרבת.","teen":"שיניים זעירות בשפה הקדמית של נוצות התעופה, שוליים דמויי שערות בשפה האחורית ומשטח נוצות קטיפתי מפרקים מערבולות אוויר ומעמעמים את רעש המעוף.","part":"wing edge"}],"field_note":{"place":"Israel","text":"ב־1983 הוצבו 14 תיבות קינון לתנשמות בקיבוץ שדה אליהו. עד 2020 היו בישראל יותר מ־5,000. זוג תנשמות והגוזלים שלו אוכלים 2,000–6,000 מכרסמים בשנה, וכך החקלאים צריכים פחות רעל."},"lab_note":"בשנות ה־70 הראה רוג'ר פיין שתנשמות יכולות לתפוס טרף בחושך מוחלט, רק לפי הקול. אחר כך אימן מסאקאזו קונישי תנשמת בשם רוג'ר לתקוף רמקולים: היא כיוונה בדיוק של כ־1–2 מעלות.","myth":{"claim":"ינשופים יכולים לסובב את הראש סיבוב שלם.","verdict":"myth","why":"ינשופים יכולים לסובב את הראש בערך 270 מעלות, לא סיבוב שלם. העיניים הגדולות שלהם קבועות בארובות, ולכן במקומן מסתובב כל הראש."},"clues":["אני עפה כמעט בלי קול.","אני צדה עכברים בחושך בעזרת השמיעה.","הפנים הבהירות שלי בצורת לב, ואני צורחת במקום לקרוא הו־הו."],"compare":{"stat":"Wingspan","value":95,"unit":"cm","text":"עד 95 ס״מ"},"stats":[{"label":"אורך","value":"33–39 ס״מ","note":"מהמקור עד הזנב"},{"label":"מוטת כנפיים","value":"80–95 ס״מ","note":"מקצה כנף לקצה כנף"},{"label":"משקל","value":"כ־310–360 גרם","note":"ממוצע לבוגרים; הנקבות כבדות יותר"},{"label":"מכרסמים שנאכלים","value":"2,000–6,000 בשנה","note":"זוג אחד והגוזלים שלו"}],"taxonomy":["בעלי חיים","עופות · Aves","ינשופים · Strigiformes","תנשמתיים · Tytonidae","Tyto alba"]}},"squirrel":{"id":"squirrel","i":10,"latin":"Sciurus vulgaris","group":"mammal","home":"forest","diet":"herb","active":"day","continents":["Europe","Asia"],"iucn":"LC","en":{"name":"Eurasian red squirrel","habitat_text":"Conifer forests and broadleaf woodlands of Europe and northern Asia","menu":"Mostly seeds from conifer cones, plus nuts, acorns, berries, buds, fungi and tree sap. Very rarely, a bird's egg or chick.","iucn_note":"Least Concern worldwide. In Britain and Ireland it has vanished from many areas since grey squirrels from North America were brought in; greys carry squirrelpox, which kills reds.","page_facts":["I hide nuts and seeds for winter.","I climb down trees head first.","In winter I grow ear tufts.","My bushy tail helps me jump."],"powers":[{"title":"Back-to-front feet","kid":"Its ankles can turn right round, so its back feet point backwards and grip the bark as it runs down head first.","teen":"Highly mobile ankle joints rotate about 180 degrees, reversing the hind feet so the claws hook into bark from above, letting it descend trunks headfirst.","part":"hind feet"},{"title":"A tail for balance","kid":"Its bushy tail helps it balance and steer when it leaps from branch to branch.","teen":"The long, bushy tail works as a counterbalance and rudder during leaps between branches, and the squirrel flicks it to signal to other squirrels.","part":"tail"},{"title":"Self-sharpening teeth","kid":"Its front teeth never stop growing, and gnawing keeps them sharp for cracking nuts.","teen":"Like all rodents it has ever-growing incisors with hard enamel only on the front; gnawing wears the softer back faster, keeping a chisel-sharp edge.","part":"front teeth"}],"field_note":{"place":"","text":"Not every red squirrel is red. Its fur can be red, brown, chestnut, grey or even black. In winter it grows a thicker, darker coat and bigger ear tufts."},"lab_note":"At Queen's University Belfast, Joshua Twining's team put pine marten scent near squirrel feeders. Red squirrels kept away and stayed alert; invasive grey squirrels ignored it. This may help explain why returning martens reduce greys but not reds.","myth":{"claim":"Squirrels sleep all winter.","verdict":"myth","why":"Red squirrels do not hibernate. They stay active and eat food they hid in autumn, though in very bad weather they may stay in their nest for several days."},"clues":["I live high up in the trees.","I bury seeds and nuts to eat in winter.","I'm a red-brown squirrel with tufts on my ears."],"compare":{"stat":"Weight","value":340,"unit":"g","text":"up to about 340 g"},"stats":[{"label":"Length","value":"19–23 cm","note":"head and body"},{"label":"Tail","value":"15–20 cm","note":"almost as long as its body"},{"label":"Weight","value":"250–340 g","note":"adults"},{"label":"Time spent on food","value":"60–80%","note":"of its waking time, finding and eating food"}],"taxonomy":["Animals","Mammals · Mammalia","Rodents · Rodentia","Squirrels · Sciuridae","Sciurus vulgaris"]},"he":{"name":"סנאי אדום","habitat_text":"יערות מחטניים וחורשות של עצים רחבי־עלים באירופה ובצפון אסיה","menu":"בעיקר זרעים מאצטרובלים של עצי מחט, וגם אגוזים, בלוטים, פירות יער, ניצנים, פטריות ומוהל עצים. לעיתים רחוקות מאוד, ביצה או גוזל של ציפור.","iucn_note":"ללא חשש בעולם כולו. בבריטניה ובאירלנד הוא נעלם מאזורים רבים מאז שהובאו לשם סנאים אפורים מצפון אמריקה; הסנאים האפורים נושאים את אבעבועות הסנאים, מחלה שהורגת סנאים אדומים.","page_facts":["אני מחביא אגוזים וזרעים לחורף.","אני יורד מהעץ עם הראש למטה.","בחורף צומחות לי ציציות על האוזניים.","הזנב העבות שלי עוזר לי לקפוץ."],"powers":[{"title":"רגליים הפוכות","kid":"הקרסוליים שלו יכולים להסתובב לגמרי, כך שכפות הרגליים האחוריות פונות לאחור ונאחזות בקליפת העץ כשהוא רץ למטה עם הראש קדימה.","teen":"מפרקי קרסול גמישים מאוד מסתובבים בכ־180 מעלות והופכים את כפות הרגליים האחוריות, כך שהטפרים ננעצים בקליפה מלמעלה והוא יכול לרדת בגזעים עם הראש למטה.","part":"hind feet"},{"title":"זנב לשיווי משקל","kid":"הזנב העבות שלו עוזר לו לשמור על שיווי משקל ולנווט כשהוא מזנק מענף לענף.","teen":"הזנב הארוך והעבות משמש משקל נגד והגה בזינוקים בין ענפים, והסנאי גם מנער אותו כדי לאותת לסנאים אחרים.","part":"tail"},{"title":"שיניים שמשחיזות את עצמן","kid":"השיניים הקדמיות שלו אף פעם לא מפסיקות לגדול, והכרסום שומר עליהן חדות לפיצוח אגוזים.","teen":"כמו לכל המכרסמים, יש לו חותכות שגדלות כל החיים, עם אמייל קשה רק בצד הקדמי. הכרסום שוחק מהר יותר את הצד האחורי הרך, וכך נשמר קצה חד כמו אזמל.","part":"front teeth"}],"field_note":{"place":"","text":"לא כל סנאי אדום הוא אדום. הפרווה שלו יכולה להיות אדומה, חומה, ערמונית, אפורה ואפילו שחורה. בחורף צומחת לו פרווה עבה וכהה יותר, וציציות גדולות יותר על האוזניים."},"lab_note":"באוניברסיטת קווינס בבלפסט הניח הצוות של ג'ושוע טווינינג ריח של דלק אורנים ליד מתקני האכלה של סנאים. הסנאים האדומים התרחקו ונשארו דרוכים; הסנאים האפורים הפולשים התעלמו ממנו. אולי זה עוזר להסביר למה דלקים שחוזרים לאזור מצמצמים את האפורים אבל לא את האדומים.","myth":{"claim":"סנאים ישנים כל החורף.","verdict":"myth","why":"סנאים אדומים לא נכנסים לתרדמת חורף. הם נשארים פעילים ואוכלים מזון שהחביאו בסתיו, אבל במזג אוויר קשה מאוד הם יכולים להישאר בקן כמה ימים."},"clues":["אני גר גבוה בעצים.","אני טומן זרעים ואגוזים כדי לאכול אותם בחורף.","אני סנאי בצבע אדום־חום, עם ציציות על האוזניים."],"compare":{"stat":"Weight","value":340,"unit":"g","text":"עד כ־340 גרם"},"stats":[{"label":"אורך","value":"19–23 ס״מ","note":"ראש וגוף"},{"label":"זנב","value":"15–20 ס״מ","note":"כמעט באורך הגוף שלו"},{"label":"משקל","value":"250–340 גרם","note":"בוגרים"},{"label":"זמן לאוכל","value":"60–80%","note":"מהזמן שהוא ער, בחיפוש אוכל ובאכילה"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","מכרסמים · Rodentia","סנאיים · Sciuridae","Sciurus vulgaris"]}},"koala":{"id":"koala","i":11,"latin":"Phascolarctos cinereus","group":"mammal","home":"forest","diet":"herb","active":"night","continents":["Australia"],"iucn":"VU","en":{"name":"Koala","habitat_text":"Eucalyptus forests and woodlands of eastern Australia","menu":"Leaves of certain kinds of eucalyptus (gum) trees, plus some flowers and stems. It gets most of the water it needs from the leaves.","iucn_note":"Vulnerable. In 2022 Australia listed koalas in Queensland, New South Wales and the ACT as Endangered. Dangers: forest clearing, cars, dogs, disease, bushfires and drought.","page_facts":["I eat eucalyptus leaves.","I sleep most of the day.","My baby grows in my pouch.","I am not a bear!"],"powers":[{"title":"Two thumbs on each hand","kid":"Each front paw has two thumb-like fingers, so it can grip branches and trunks tightly.","teen":"On each forepaw the first two digits oppose the other three, and every digit has a strongly curved claw, giving a secure grip on smooth eucalyptus bark.","part":"front paws"},{"title":"A leaf-processing gut","kid":"Its gut has a very long pouch, about 2 metres, full of microbes that help break down tough leaves.","teen":"A caecum 2–2.5 m long, among the largest for its size, holds microbes that ferment fibrous leaves, while liver enzymes (cytochrome P450) neutralise the leaves' toxins.","part":"belly"},{"title":"A giant's voice","kid":"Male koalas make deep, snoring bellows, far lower than you would expect from such a small animal.","teen":"Males have extra 'velar' vocal folds in the soft palate, outside the larynx, producing bellows about 20 times lower in pitch than expected for an 8 kg animal.","part":"throat"}],"field_note":{"place":"Israel","text":"Koalas eat eucalyptus, a tree from Australia. Between 1895 and 1899, people planted a big eucalyptus forest at Hadera to help dry the swamps. A eucalyptus forest still grows there, but wild koalas live only in Australia."},"lab_note":"In 1997, Maciej Henneberg and colleagues in Adelaide compared koala and human fingerprints. Even under a microscope, the koala's loops and whorls looked almost the same as ours.","myth":{"claim":"Koalas are bears.","verdict":"myth","why":"Koalas are marsupials: the mother carries her baby in a pouch. Their closest living relatives are wombats, not bears."},"clues":["I spend almost my whole life up in trees.","My baby lives in my pouch for about six months.","I'm a furry Australian tree-dweller that munches eucalyptus leaves."],"compare":{"stat":"Weight","value":15,"unit":"kg","text":"up to 15 kg"},"stats":[{"label":"Length","value":"60–85 cm","note":"head and body"},{"label":"Caecum","value":"2–2.5 m","note":"gut pouch for digesting leaves"},{"label":"Weight","value":"4–15 kg","note":"males and southern koalas heavier"},{"label":"Sleep","value":"up to 20 hours a day","note":"sleeping and resting"}],"taxonomy":["Animals","Mammals · Mammalia","Kangaroos, wombats and kin · Diprotodontia","Koalas · Phascolarctidae","Phascolarctos cinereus"]},"he":{"name":"קואלה","habitat_text":"יערות וחורשות של אקליפטוס במזרח אוסטרליה","menu":"עלים של סוגים מסוימים של עצי אקליפטוס, וגם קצת פרחים וגבעולים. את רוב המים שהוא צריך הוא מקבל מהעלים.","iucn_note":"פגיע. ב־2022 הכריזה אוסטרליה שהקואלה בקווינסלנד, בניו סאות' ויילס ובטריטוריית הבירה האוסטרלית נמצא בסכנת הכחדה. סכנות: כריתת יערות, מכוניות, כלבים, מחלות, שרפות ובצורת.","page_facts":["אני אוכל עלי אקליפטוס.","אני ישן רוב היום.","הגור שלי גדל בכיס שלי.","אני לא דוב!"],"powers":[{"title":"שני אגודלים בכל יד","kid":"בכל כפה קדמית יש לו שתי אצבעות שדומות לאגודל, כך שהוא יכול לאחוז חזק בענפים ובגזעים.","teen":"בכל כפה קדמית שתי האצבעות הראשונות נגדיות לשלוש האחרות, ולכל אצבע יש טופר מעוקל מאוד. כך הוא נאחז היטב בקליפה החלקה של האקליפטוס.","part":"front paws"},{"title":"מעי לעיבוד עלים","kid":"במעי שלו יש כיס ארוך מאוד, כ־2 מטרים, מלא מיקרובים שעוזרים לפרק עלים קשים.","teen":"המעי העיוור, באורך 2–2.5 מ׳ ומהגדולים ביחס לגודל הגוף, מכיל מיקרובים שמתסיסים את העלים הסיביים, ואנזימים בכבד (ציטוכרום P450) מנטרלים את הרעלים שבעלים.","part":"belly"},{"title":"קול של ענק","kid":"זכרי קואלה משמיעים קריאות עמוקות שנשמעות כמו נחירות, נמוכות הרבה יותר ממה שמצפים מבעל חיים קטן כל כך.","teen":"לזכרים יש מיתרי קול נוספים, וילוניים, בחך הרך, מחוץ לבית הקול. הם מפיקים קריאות נמוכות בערך פי 20 ממה שצפוי לבעל חיים של 8 ק״ג.","part":"throat"}],"field_note":{"place":"Israel","text":"הקואלה אוכל אקליפטוס, עץ שמקורו באוסטרליה. בין 1895 ל־1899 נטעו בחדרה יער אקליפטוס גדול כדי לעזור לייבש את הביצות. יער אקליפטוס עדיין צומח שם, אבל בטבע קואלה חי רק באוסטרליה."},"lab_note":"ב־1997 השוו מאצ'יי הנברג ועמיתיו באדלייד בין טביעות אצבע של קואלה לטביעות אצבע של בני אדם. אפילו במיקרוסקופ, הלולאות והמערבולות של הקואלה נראו כמעט זהות לשלנו.","myth":{"claim":"הקואלה הוא דוב.","verdict":"myth","why":"הקואלה הוא כיסאי: האם נושאת את הגור שלה בכיס. קרובי המשפחה הקרובים ביותר שלו שחיים היום הם הוומבטים, לא הדובים."},"clues":["אני מבלה כמעט את כל חיי למעלה בעצים.","הגור שלי גר בכיס שלי בערך שישה חודשים.","אני פרוותי, גר בעצים באוסטרליה ולועס עלי אקליפטוס."],"compare":{"stat":"Weight","value":15,"unit":"kg","text":"עד 15 ק״ג"},"stats":[{"label":"אורך","value":"60–85 ס״מ","note":"ראש וגוף"},{"label":"מעי עיוור","value":"2–2.5 מ׳","note":"כיס במעי לעיכול עלים"},{"label":"משקל","value":"4–15 ק״ג","note":"הזכרים כבדים יותר, וגם הקואלות שבדרום"},{"label":"שינה","value":"עד 20 שעות ביום","note":"שינה ומנוחה"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","קנגורו, וומבטים וקרוביהם · Diprotodontia","משפחת הקואלה · Phascolarctidae","Phascolarctos cinereus"]}},"penguin":{"id":"penguin","i":12,"latin":"Aptenodytes forsteri","group":"bird","home":"ice","diet":"carn","active":"day and night","continents":["Antarctica"],"iucn":"EN","en":{"name":"Emperor penguin","habitat_text":"Sea ice and icy seas around Antarctica","menu":"Fish, mostly Antarctic silverfish, plus krill and squid caught on deep dives. An adult usually eats 2–3 kg a day, and up to 6 kg before breeding or moulting.","iucn_note":"Endangered since April 2026 (it was Near Threatened). It needs stable sea ice to breed, raise chicks and moult, and that ice is shrinking as the climate warms. Its numbers could halve by the 2080s.","page_facts":["I live on Antarctic ice.","I cannot fly, but I swim.","Dad keeps the egg on his feet.","We huddle together to keep warm."],"powers":[{"title":"A double winter coat","kid":"Thick, overlapping feathers and a layer of fat keep it warm through winter storms on the ice.","teen":"Densely packed, overlapping feathers supply 80–90% of its insulation, and before breeding a fat layer up to 3 cm thick adds more, letting it stand on ice through the polar winter.","part":"feathers"},{"title":"Dad's warm feet","kid":"The father balances the egg on his feet, tucked against warm belly skin, for about two months without eating.","teen":"The male incubates the single egg on his feet against a bare brood patch for 65–75 days; by hatching he has fasted about 120 days and may lose up to 20 kg.","part":"feet"},{"title":"Holding its breath","kid":"When it dives, its heart slows right down to save oxygen, so it can stay underwater for up to about 20 minutes.","teen":"On dives its heart rate can fall to 15–20 beats a minute and non-essential organs shut down; its blood works at very low oxygen levels, and solid bones resist the pressure.","part":"chest"}],"field_note":{"place":"","text":"Scientists find emperor penguin colonies from space: in satellite photos, the birds' brown droppings show up as stains on the white sea ice. In 2024 the British Antarctic Survey reported four new colonies found this way."},"lab_note":"Filming a huddle, Daniel Zitterbart and colleagues (2011) found that every 30–60 seconds all the penguins take tiny steps together. These waves slowly reshuffle the huddle, so birds take turns in the warm middle.","myth":{"claim":"Penguins and polar bears live together.","verdict":"myth","why":"Emperor penguins live only around Antarctica, in the far south. Polar bears live in the Arctic, in the far north. They never meet in the wild."},"clues":["I am a bird, but I cannot fly.","I dive in freezing seas to catch fish.","I am the biggest penguin, and dads keep our eggs on their feet all winter."],"compare":{"stat":"Dive depth","value":564,"unit":"m","text":"down to 564 m"},"stats":[{"label":"Length","value":"110–120 cm","note":"beak to tail; the biggest penguin"},{"label":"Weight","value":"22–45 kg","note":"males heavier; a fasting male can lose up to 20 kg"},{"label":"Egg","value":"about 12 cm long","note":"460–470 g, kept warm on dad's feet"},{"label":"Dive depth","value":"up to 564 m","note":"deepest recorded; deeper than any other bird"}],"taxonomy":["Animals","Birds · Aves","Penguins · Sphenisciformes","Penguin family · Spheniscidae","Aptenodytes forsteri"]},"he":{"name":"פינגווין קיסרי","habitat_text":"קרח ים וימים קפואים סביב אנטארקטיקה","menu":"דגים, בעיקר דג הכסף האנטארקטי, וגם קריל ודיונונים שהוא תופס בצלילות עמוקות. פינגווין בוגר אוכל בדרך כלל 2–3 ק״ג ביום, ועד 6 ק״ג לפני עונת הרבייה או לפני החלפת הנוצות.","iucn_note":"בסכנת הכחדה מאז אפריל 2026 (לפני כן: קרוב לסיכון). הוא זקוק לקרח ים יציב כדי להתרבות, לגדל גוזלים ולהחליף נוצות, והקרח הזה הולך ומצטמצם ככל שהאקלים מתחמם. מספר הפינגווינים הקיסריים עלול לרדת בחצי עד שנות ה־80 של המאה.","page_facts":["אני גר על הקרח באנטארקטיקה.","אני לא יכול לעוף, אבל אני שוחה.","אבא שומר את הביצה על הרגליים.","אנחנו מצטופפים יחד כדי להתחמם."],"powers":[{"title":"מעיל חורף כפול","kid":"נוצות צפופות שחופפות זו לזו ושכבת שומן שומרות עליו חם בסופות החורף על הקרח.","teen":"נוצות צפופות וחופפות מספקות 80–90% מהבידוד שלו, ולפני עונת הרבייה מוסיפה עוד שכבת שומן בעובי של עד 3 ס״מ, וכך הוא יכול לעמוד על הקרח לאורך החורף הקוטבי.","part":"feathers"},{"title":"הרגליים החמות של אבא","kid":"האבא מחזיק את הביצה בשיווי משקל על כפות הרגליים, צמודה לעור החם של הבטן, במשך כחודשיים בלי לאכול.","teen":"הזכר דוגר על הביצה היחידה כשהיא מונחת על כפות רגליו, צמודה לכתם דגירה חשוף, במשך 65–75 ימים. עד הבקיעה הוא כבר צם כ־120 יום ועלול לאבד עד 20 ק״ג.","part":"feet"},{"title":"לעצור את הנשימה","kid":"כשהוא צולל, הלב שלו מאט מאוד כדי לחסוך בחמצן, כך שהוא יכול להישאר מתחת למים עד כ־20 דקות.","teen":"בצלילה הדופק שלו יכול לרדת ל־15–20 פעימות בדקה, ואיברים שאינם חיוניים מושבתים; הדם שלו מתפקד ברמות חמצן נמוכות מאוד, ועצמות מלאות עומדות בלחץ.","part":"chest"}],"field_note":{"place":"","text":"מדענים מוצאים מושבות של פינגווינים קיסריים מהחלל: בתצלומי לוויין, הלשלשת החומה של הציפורים נראית ככתמים על קרח הים הלבן. ב־2024 דיווח המכון הבריטי לחקר אנטארקטיקה על ארבע מושבות חדשות שנמצאו כך."},"lab_note":"כשצילמו פינגווינים מצטופפים, גילו דניאל ציטרברט ועמיתיו (2011) שכל 30–60 שניות כל הפינגווינים צועדים יחד צעדים זעירים. הגלים האלה מערבבים לאט את הגוש, כך שהציפורים מתחלפות במרכז החם.","myth":{"claim":"פינגווינים ודובי קוטב חיים יחד.","verdict":"myth","why":"פינגווינים קיסריים חיים רק סביב אנטארקטיקה, בדרום הרחוק. דובי קוטב חיים באזור הארקטי, בצפון הרחוק. בטבע הם אף פעם לא נפגשים."},"clues":["אני ציפור, אבל אני לא יכול לעוף.","אני צולל בים קפוא כדי לתפוס דגים.","אני הפינגווין הגדול ביותר, ואצלנו האבות מחזיקים את הביצים על הרגליים כל החורף."],"compare":{"stat":"Dive depth","value":564,"unit":"m","text":"עד עומק 564 מ׳"},"stats":[{"label":"אורך","value":"110–120 ס״מ","note":"מהמקור עד הזנב; הפינגווין הגדול ביותר"},{"label":"משקל","value":"22–45 ק״ג","note":"הזכרים כבדים יותר; זכר בצום יכול לאבד עד 20 ק״ג"},{"label":"ביצה","value":"באורך של כ־12 ס״מ","note":"460–470 גרם, מחוממת על הרגליים של אבא"},{"label":"עומק צלילה","value":"עד 564 מ׳","note":"העמוק ביותר שנמדד; עמוק יותר מכל ציפור אחרת"}],"taxonomy":["בעלי חיים","עופות · Aves","פינגווינים · Sphenisciformes","פינגוויניים · Spheniscidae","Aptenodytes forsteri"]}},"cow":{"id":"cow","i":13,"latin":"Bos taurus","group":"mammal","home":"farm","diet":"herb","active":"day and night","continents":["Worldwide (farms)"],"iucn":"domestic","en":{"name":"Holstein-Friesian cow","habitat_text":"Dairy farms and pastures; the breed comes from the Netherlands and northern Germany","menu":"Grass and hay; on dairy farms also silage and some grain. It brings swallowed food back up and chews it again, almost 8 hours a day.","iucn_note":"A domestic animal, so the IUCN does not assess it. Its wild ancestor, the aurochs, once lived in Israel too; the last one died in a Polish forest in 1627.","page_facts":["I say moo.","I eat grass and hay.","I chew my food twice.","I give milk for my calf."],"powers":[{"title":"One stomach, four rooms","kid":"Its stomach has four parts. Tiny microbes in the biggest part, the rumen, help break down tough grass.","teen":"A ruminant: one stomach with four compartments (rumen, reticulum, omasum, abomasum). Food is brought back up as cud and re-chewed, and the saliva this makes buffers the rumen.","part":"belly"},{"title":"Nearly all-round view","kid":"Its eyes sit on the sides of its head, so it can see almost all the way around without turning.","teen":"Side-set eyes give a field of view of about 330°, with only 30–50° seen by both eyes. Like most mammals, cattle are dichromats and cannot tell red from green.","part":"eyes"},{"title":"A milk factory","kid":"Her udder makes milk after she has a calf. On a dairy farm, she is milked every day.","teen":"Milk flows only after calving, so a dairy cow usually has one calf a year. Israeli dairy cows average about 12,000 kg of milk a year, among the highest yields per cow anywhere.","part":"udder"}],"field_note":{"place":"Israel","text":"Israeli dairy cows give about 12,000 kg of milk a year each, one of the highest averages of any country. To beat summer heat, almost every Israeli dairy farm cools its cows with water sprays and fans."},"lab_note":"Following more than 130,000 Israeli dairy cows over 12 years, Claire Palandri, Ram Fishman and colleagues (2025) found that hot, humid days cut milk by up to 10 percent, even with sprays and fans.","myth":{"claim":"Brown cows give chocolate milk.","verdict":"myth","why":"Every cow makes white milk, whatever colour her coat is. Chocolate milk is ordinary milk with cocoa and sugar mixed in."},"clues":["I live on a farm and eat plants.","I swallow my food, bring it back up and chew it again.","I am black and white, I say moo, and farmers milk me every day."],"compare":{"stat":"Weight","value":770,"unit":"kg","text":"up to about 770 kg"},"stats":[{"label":"Height","value":"145–165 cm","note":"at the shoulder"},{"label":"Weight","value":"680–770 kg","note":"adult cow"},{"label":"Milk","value":"about 12,000 kg a year","note":"average Israeli dairy cow"},{"label":"Cud chewing","value":"almost 8 hours a day","note":"nearly 30,000 chews"}],"taxonomy":["Animals","Mammals · Mammalia","Even-toed hoofed mammals · Artiodactyla","Cattle family · Bovidae","Bos taurus"]},"he":{"name":"פרת הולשטיין","habitat_text":"רפתות ושטחי מרעה; מקור הגזע בהולנד ובצפון גרמניה","menu":"עשב ושחת; ברפתות גם תחמיץ וקצת גרעינים. היא מעלה בחזרה מזון שבלעה ולועסת אותו שוב, כמעט 8 שעות ביום.","iucn_note":"חיית משק מבויתת, ולכן האיגוד העולמי לשימור הטבע (IUCN) אינו מדרג אותה. אביה הקדמון בטבע, שור הבר, חי פעם גם בישראל; האחרון מת ביער בפולין ב־1627.","page_facts":["אני עושה מו.","אני אוכלת עשב ושחת.","אני לועסת את האוכל פעמיים.","אני נותנת חלב לעגל שלי."],"powers":[{"title":"קיבה אחת, ארבעה חדרים","kid":"לקיבה שלה יש ארבעה חלקים. מיקרובים זעירים בחלק הגדול ביותר, הכרס, עוזרים לפרק עשב קשה.","teen":"מעלת גירה: קיבה אחת עם ארבעה תאים (כרס, בית הכוסות, המסס וקבה). המזון עולה בחזרה כגירה ונלעס שוב, והרוק שהלעיסה מייצרת מאזן את החומציות בכרס.","part":"belly"},{"title":"ראייה כמעט מסביב","kid":"העיניים שלה נמצאות בצדי הראש, כך שהיא רואה כמעט מסביב בלי להסתובב.","teen":"עיניים בצדי הראש נותנות שדה ראייה של כ־330°, ורק 30–50° מתוכו נראים בשתי העיניים. כמו לרוב היונקים, לבקר יש ראייה דו־צבעית, והוא לא מבחין בין אדום לירוק.","part":"eyes"},{"title":"מפעל חלב","kid":"העטין שלה מייצר חלב אחרי שנולד לה עגל. ברפת חולבים אותה כל יום.","teen":"חלב מופק רק אחרי המלטה, ולכן לפרת חלב נולד בדרך כלל עגל אחד בשנה. פרות החלב בישראל נותנות בממוצע כ־12,000 ק״ג חלב בשנה, מהתנובות הגבוהות בעולם לפרה.","part":"udder"}],"field_note":{"place":"Israel","text":"כל פרת חלב בישראל נותנת כ־12,000 ק״ג חלב בשנה, אחד הממוצעים הגבוהים מכל המדינות. כדי להתמודד עם חום הקיץ, כמעט כל רפת בישראל מקררת את הפרות בהתזות מים ובמאווררים."},"lab_note":"קלייר פלנדרי, רם פישמן ועמיתיהם (2025) עקבו אחרי יותר מ־130,000 פרות חלב בישראל במשך 12 שנה, ומצאו שימים חמים ולחים מורידים את כמות החלב בעד 10 אחוזים, גם עם התזות מים ומאווררים.","myth":{"claim":"פרות חומות נותנות שוקו.","verdict":"myth","why":"כל פרה מייצרת חלב לבן, לא משנה מה צבע הפרווה שלה. שוקו הוא חלב רגיל שמערבבים בו קקאו וסוכר."},"clues":["אני גרה בחווה ואוכלת צמחים.","אני בולעת את האוכל, מעלה אותו בחזרה ולועסת אותו שוב.","אני שחורה ולבנה, אני עושה מו, והרפתנים חולבים אותי כל יום."],"compare":{"stat":"Weight","value":770,"unit":"kg","text":"עד כ־770 ק״ג"},"stats":[{"label":"גובה","value":"145–165 ס״מ","note":"בגובה הכתפיים"},{"label":"משקל","value":"680–770 ק״ג","note":"פרה בוגרת"},{"label":"חלב","value":"כ־12,000 ק״ג בשנה","note":"פרת חלב ישראלית ממוצעת"},{"label":"לעיסת גירה","value":"כמעט 8 שעות ביום","note":"כמעט 30,000 לעיסות"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","מכפילי פרסה · Artiodactyla","פריים · Bovidae","Bos taurus"]}},"pig":{"id":"pig","i":14,"latin":"Sus domesticus","group":"mammal","home":"farm","diet":"omni","active":"day","continents":["Worldwide (farms)"],"iucn":"domestic","en":{"name":"Domestic pig","habitat_text":"Farms worldwide","menu":"Almost anything. Farm pigs are mostly fed grain such as corn. Pigs that roam dig up roots and eat leaves, stems, fruit and flowers, and sometimes small animals.","iucn_note":"A domestic animal, so the IUCN does not assess it. Its wild ancestor, the wild boar, is Least Concern and lives in Israel.","page_facts":["I say oink.","I dig with my snout.","I roll in mud to cool down.","My babies are called piglets."],"powers":[{"title":"A digging snout","kid":"Its snout has a special extra bone and a tough disc at the tip, perfect for digging up food.","teen":"A prenasal bone and a cartilage disc stiffen the snout for rooting in soil; it is also a keen sense organ, and pigs carry 1,113 smell-receptor genes to dogs' 1,094.","part":"snout"},{"title":"Mud for cooling","kid":"Pigs can hardly sweat, so they roll in mud or water. As the wet coating dries, it carries heat away.","teen":"Eccrine sweat glands are limited to the snout, so pigs cool by wallowing: evaporating water carries heat off the body. The mud may also guard against sunburn and parasites.","part":"skin"},{"title":"A milk timetable","kid":"Each piglet picks its own teat and keeps feeding there. Mum grunts in a pattern that tells the piglets when milk is coming.","teen":"Piglets set up a stable teat order, each feeding from the same teat or group of teats. The sow's grunts change in frequency, tone and loudness to signal each stage of nursing.","part":"teats"}],"field_note":{"place":"Israel","text":"The pig's wild ancestor, the wild boar, lives in Israel. In Haifa, wild boars come down from the Carmel into city neighbourhoods, digging up gardens and searching rubbish bins for food."},"lab_note":"Candace Croney (Purdue University) and Sarah Boysen (2021) trained four pigs to steer a cursor on a screen with a joystick moved by their snouts. All four hit targets more often than chance.","myth":{"claim":"Pigs are dirty animals.","verdict":"myth","why":"Pigs roll in mud to cool off, because they can hardly sweat. When they have enough room, they keep their toilet area away from where they lie down."},"clues":["I live on a farm and eat almost anything.","I roll in mud to keep cool.","I have a flat round snout and a curly tail, and I say oink."],"compare":{"stat":"Weight","value":300,"unit":"kg","text":"up to about 300 kg"},"stats":[{"label":"Weight","value":"140–300 kg","note":"adult; some grow much heavier"},{"label":"Piglets","value":"about 11–14","note":"per litter on modern farms"},{"label":"Smell genes","value":"1,113","note":"smell-receptor genes; dogs have 1,094"},{"label":"Pregnancy","value":"112–120 days","note":"about four months"}],"taxonomy":["Animals","Mammals · Mammalia","Even-toed hoofed mammals · Artiodactyla","Pig family · Suidae","Sus domesticus"]},"he":{"name":"חזיר בית","habitat_text":"חוות בכל העולם","menu":"כמעט הכול. בחוות מאכילים חזירים בעיקר בגרעינים, כמו תירס. חזירים שמסתובבים בחופשיות חופרים שורשים ואוכלים עלים, גבעולים, פירות ופרחים, ולפעמים גם בעלי חיים קטנים.","iucn_note":"בעל חיים מבוית, ולכן האיגוד העולמי לשימור הטבע (IUCN) אינו מדרג אותו. אביו הקדמון, חזיר הבר, חי בישראל, ומצבו ללא חשש.","page_facts":["אני עושה אוינק.","אני חופר עם החוטם שלי.","אני מתגלגל בבוץ כדי להתקרר.","התינוקות שלי נקראים חזרזירים."],"powers":[{"title":"חוטם לחפירה","kid":"בחוטם שלו יש עצם מיוחדת נוספת ודיסקה קשה בקצה, מושלמים לחפירה ולמציאת אוכל באדמה.","teen":"עצם קדם־אפית ודיסקת סחוס מקשיחות את החוטם לחיטוט באדמה. החוטם הוא גם איבר חישה רגיש, ולחזירים יש 1,113 גנים לקולטני ריח, לעומת 1,094 אצל כלבים.","part":"snout"},{"title":"בוץ לקירור","kid":"חזירים כמעט לא מזיעים, ולכן הם מתגלגלים בבוץ או במים. כשהשכבה הרטובה מתייבשת, היא לוקחת איתה את החום.","teen":"בלוטות זיעה אקריניות נמצאות אצלם רק בחוטם, ולכן חזירים מתקררים בהתפלשות: המים המתאדים מוציאים חום מהגוף. ייתכן שהבוץ גם מגן מפני כוויות שמש ומפני טפילים.","part":"skin"},{"title":"לוח זמנים לחלב","kid":"כל חזרזיר בוחר לעצמו פטמה וממשיך לינוק ממנה. אמא נוחרת בדפוס מיוחד שמודיע לחזרזירים מתי החלב מגיע.","teen":"החזרזירים קובעים סדר פטמות יציב, וכל אחד יונק מאותה פטמה או מאותה קבוצת פטמות. הנחירות של החזירה משתנות בתדירות, בטון ובעוצמה כדי לסמן כל שלב בהנקה.","part":"teats"}],"field_note":{"place":"Israel","text":"אביו הקדמון של החזיר, חזיר הבר, חי בישראל. בחיפה יורדים חזירי בר מהכרמל אל שכונות העיר, חופרים בגינות ומחפשים אוכל בפחי האשפה."},"lab_note":"קנדס קרוני (אוניברסיטת פרדו) ושרה בויסן (2021) אימנו ארבעה חזירים להזיז סמן על מסך בעזרת ג'ויסטיק שהם הזיזו בחוטם. כל הארבעה פגעו במטרות יותר פעמים ממה שהיה קורה במקרה.","myth":{"claim":"חזירים הם בעלי חיים מלוכלכים.","verdict":"myth","why":"חזירים מתגלגלים בבוץ כדי להתקרר, כי הם כמעט לא מזיעים. כשיש להם מספיק מקום, הם עושים את הצרכים רחוק מהמקום שבו הם שוכבים."},"clues":["אני גר בחווה ואוכל כמעט הכול.","אני מתגלגל בבוץ כדי להתקרר.","יש לי חוטם שטוח ועגול וזנב מסולסל, ואני עושה אוינק."],"compare":{"stat":"Weight","value":300,"unit":"kg","text":"עד כ־300 ק״ג"},"stats":[{"label":"משקל","value":"140–300 ק״ג","note":"חזיר בוגר; יש שמגיעים למשקל גבוה הרבה יותר"},{"label":"חזרזירים","value":"כ־11–14","note":"בכל המלטה, בחוות מודרניות"},{"label":"גנים של ריח","value":"1,113","note":"גנים לקולטני ריח; לכלבים יש 1,094"},{"label":"היריון","value":"112–120 ימים","note":"בערך ארבעה חודשים"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","מכפילי פרסה · Artiodactyla","חזיריים · Suidae","Sus domesticus"]}},"horse":{"id":"horse","i":15,"latin":"Equus caballus","group":"mammal","home":"farm","diet":"herb","active":"day and night","continents":["Worldwide (farms)"],"iucn":"domestic","en":{"name":"Horse","habitat_text":"Farms, stables and pastures worldwide","menu":"Grass and hay, eaten little by little through the day: a 450 kg horse eats 7–11 kg of food a day. Some also get grain. Apples are only a treat.","iucn_note":"A domestic animal, so the IUCN does not assess it.","page_facts":["I can sleep standing up.","I eat grass and hay.","My baby is called a foal.","I gallop fast on my hooves."],"powers":[{"title":"Eyes on the sides","kid":"Its big eyes sit on the sides of its head, so it can see almost all the way around itself.","teen":"Its eyes are among the largest of any land mammal. Set on the sides of the head, they give over 350° of vision: about 65° with both eyes, 285° with one.","part":"eyes"},{"title":"Built-in leg locks","kid":"Special tendons and ligaments lock its legs, so it can doze standing up without falling over.","teen":"The stay apparatus, an arrangement of muscles, tendons and ligaments, holds the legs straight with almost no muscle effort, so a horse can enter light sleep while standing.","part":"legs"},{"title":"Swivelling ears","kid":"Each ear can swivel around to catch sounds from different directions, without the horse turning its head.","teen":"Each outer ear (pinna) can rotate up to 180°, which gives a horse the potential for all-round, 360° hearing without having to move its head.","part":"ears"}],"field_note":{"place":"Israel","text":"At Tel Megiddo, archaeologists found buildings from the 800s BCE with stone mangers and pillars bored with holes for tying horses. Many experts think they were stables for hundreds of chariot horses; others think they were storehouses."},"lab_note":"In 1907, psychologist Oskar Pfungst showed that Clever Hans, a horse said to do sums, was really reading tiny changes in the questioner's posture and face. Unable to see the questioner, Hans got only 2 of 35 right.","myth":{"claim":"Horses sleep standing up.","verdict":"fact","why":"They doze standing, held up by locking leg tendons. But for deep dream sleep (REM) they must lie down, and they need at least about 30 minutes lying down a day."},"clues":["I have hooves and eat grass.","People ride on my back.","Jockeys race me, and my long mane flies as I gallop."],"compare":{"stat":"Top speed","value":70,"unit":"km/h","text":"about 70 km/h in a record sprint"},"stats":[{"label":"Height","value":"142–163 cm","note":"at the shoulder, riding horses; heavy breeds up to 183 cm"},{"label":"Weight","value":"380–550 kg","note":"riding horses; heavy breeds 700–1,000 kg"},{"label":"Top speed","value":"about 70 km/h","note":"record sprint; a normal gallop is 40–48 km/h"},{"label":"Field of view","value":"over 350°","note":"almost a full circle"}],"taxonomy":["Animals","Mammals · Mammalia","Odd-toed hoofed mammals · Perissodactyla","Horse family · Equidae","Equus caballus"]},"he":{"name":"סוס","habitat_text":"חוות, אורוות ושטחי מרעה בכל העולם","menu":"עשב ושחת, שהוא אוכל מעט־מעט לאורך כל היום: סוס של 450 ק״ג אוכל 7–11 ק״ג מזון ביום. חלק מהסוסים מקבלים גם גרעינים. תפוחים הם רק פינוק.","iucn_note":"בעל חיים מבוית, ולכן האיגוד העולמי לשימור הטבע (IUCN) אינו מדרג אותו.","page_facts":["אני יכול לישון בעמידה.","אני אוכל עשב ושחת.","התינוק שלי נקרא סייח.","אני דוהר מהר על הפרסות שלי."],"powers":[{"title":"עיניים בצדדים","kid":"העיניים הגדולות שלו נמצאות בצדי הראש, כך שהוא רואה כמעט את כל מה שמסביבו.","teen":"העיניים שלו מהגדולות ביותר מכל יונקי היבשה. הן ממוקמות בצדי הראש ונותנות שדה ראייה של יותר מ־350°: כ־65° בשתי העיניים, ו־285° בעין אחת.","part":"eyes"},{"title":"מנעול מובנה ברגליים","kid":"גידים ורצועות מיוחדים נועלים את הרגליים שלו, כך שהוא יכול לנמנם בעמידה בלי ליפול.","teen":"מנגנון העמידה, מערך של שרירים, גידים ורצועות, מחזיק את הרגליים ישרות כמעט בלי מאמץ שרירים, כך שסוס יכול להיכנס לשינה קלה בעמידה.","part":"legs"},{"title":"אוזניים מסתובבות","kid":"כל אוזן יכולה להסתובב ולקלוט צלילים מכיוונים שונים, בלי שהסוס יסובב את הראש.","teen":"כל אוזן חיצונית (אפרכסת) יכולה להסתובב עד 180°, וזה מאפשר לסוס שמיעה מכל הכיוונים, 360°, בלי להזיז את הראש.","part":"ears"}],"field_note":{"place":"Israel","text":"בתל מגידו מצאו ארכאולוגים מבנים מהמאה ה־9 לפני הספירה, עם אבוסים מאבן ועמודים מחוררים לקשירת סוסים. מומחים רבים חושבים שאלה היו אורוות למאות סוסי מרכבה; אחרים חושבים שאלה היו מחסנים."},"lab_note":"ב־1907 הראה הפסיכולוג אוסקר פפונגסט שהנס החכם, סוס שאמרו עליו שהוא יודע לחשב, בעצם קרא שינויים זעירים בתנוחה ובפנים של מי ששאל אותו. כשלא ראה את השואל, הנס צדק רק ב־2 מתוך 35.","myth":{"claim":"סוסים ישנים בעמידה.","verdict":"fact","why":"הם מנמנמים בעמידה, כשגידים שננעלים ברגליים מחזיקים אותם. אבל לשינה עמוקה עם חלומות (שנת REM) הם חייבים לשכב, והם צריכים לשכב לפחות כ־30 דקות ביום."},"clues":["יש לי פרסות ואני אוכל עשב.","אנשים רוכבים על הגב שלי.","רוכבי מרוץ מתחרים על גבי, והרעמה הארוכה שלי מתנופפת כשאני דוהר."],"compare":{"stat":"Top speed","value":70,"unit":"km/h","text":"כ־70 קמ״ש בריצת שיא קצרה"},"stats":[{"label":"גובה","value":"142–163 ס״מ","note":"בגובה הכתפיים, בסוסי רכיבה; בגזעים כבדים עד 183 ס״מ"},{"label":"משקל","value":"380–550 ק״ג","note":"סוסי רכיבה; בגזעים כבדים 700–1,000 ק״ג"},{"label":"מהירות שיא","value":"כ־70 קמ״ש","note":"שיא בריצה קצרה; דהירה רגילה היא 40–48 קמ״ש"},{"label":"שדה ראייה","value":"יותר מ־350°","note":"כמעט מעגל שלם"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","מפריסי פרסה · Perissodactyla","סוסיים · Equidae","Equus caballus"]}},"chick":{"id":"chick","i":16,"latin":"Gallus gallus domesticus","group":"bird","home":"farm","diet":"omni","active":"day","continents":["Worldwide (farms)"],"iucn":"domestic","en":{"name":"Chicken","habitat_text":"Farms and backyards worldwide","menu":"Seeds and grain, plus insects, and even lizards, small snakes and young mice. It scratches the soil with its feet to find food.","iucn_note":"A domestic animal, so the IUCN does not assess it. Its wild ancestor, the red junglefowl of South and Southeast Asia, is Least Concern. Over 26.5 billion chickens lived on Earth in 2023.","page_facts":["I hatch from an egg.","I eat seeds and bugs.","I scratch the ground for food.","I cannot fly very far."],"powers":[{"title":"A tooth for hatching","kid":"A chick has a tiny hard tip on its beak, the egg tooth, to chip its way out of the shell. Soon it falls off.","teen":"Near hatching the chick pierces the air sac at the blunt end, then 'pips', forcing its temporary egg tooth through the shell as it turns, cutting its way out.","part":"beak"},{"title":"Scratching feet","kid":"Strong feet with claws scratch the soil to uncover seeds and bugs hiding underneath.","teen":"Chickens are omnivores that scratch the soil with clawed feet to expose food: seeds and insects, and animals as large as lizards, small snakes and young mice.","part":"feet"},{"title":"Two kinds of alarm","kid":"Chickens have different warning calls: one for danger from the sky, like a hawk, and another for danger on the ground.","teen":"Chickens give distinct alarm calls for predators approaching from the air and from the ground, so flockmates can react in the right way to each kind of threat.","part":"throat"}],"field_note":{"place":"Israel","text":"At Maresha, in the Judean lowlands, University of Haifa researchers found over a thousand chicken bones with butchery marks, from about 2,100–2,400 years ago: the earliest known place outside East Asia where chickens were raised for food."},"lab_note":"Protein pieces from a 68-million-year-old T. rex leg bone were studied by John Asara, Chris Organ and colleagues at Harvard (2007–2008). T. rex grouped with birds, chicken and ostrich, better than with alligators or lizards.","myth":{"claim":"Every egg could hatch into a chick.","verdict":"myth","why":"Hens lay eggs even without a rooster. Those eggs are not fertilised, so no chick can grow inside. Only fertilised eggs kept warm for about 21 days hatch."},"clues":["I am a bird that lives on farms.","I scratch the ground for seeds and bugs.","I cluck, and my chicks hatch after about 21 days."],"compare":{"stat":"Lifespan","value":10,"unit":"years","text":"up to about 10 years"},"stats":[{"label":"Weight","value":"about 1.5–3.6 kg","note":"a hen, depending on breed; roosters are heavier"},{"label":"Eggs","value":"over 300 a year","note":"a hen bred for laying"},{"label":"Hatching","value":"about 21 days","note":"from a warmed egg to a chick"},{"label":"Lifespan","value":"5–10 years","note":"depending on breed"}],"taxonomy":["Animals","Birds · Aves","Landfowl · Galliformes","Pheasant family · Phasianidae","Gallus gallus domesticus"]},"he":{"name":"תרנגולת","habitat_text":"חוות וחצרות בתים בכל העולם","menu":"זרעים וגרעינים, וגם חרקים, ואפילו לטאות, נחשים קטנים ועכברים צעירים. היא מגרדת את האדמה ברגליים כדי למצוא אוכל.","iucn_note":"ציפור מבויתת, ולכן האיגוד העולמי לשימור הטבע (IUCN) אינו מדרג אותה. אביה הקדמון בטבע הוא תרנגול הבר האדום של דרום אסיה ודרום־מזרח אסיה, ומצבו ללא חשש. ב־2023 חיו על כדור הארץ יותר מ־26.5 מיליארד תרנגולות.","page_facts":["בקעתי מביצה.","אני אוכלת זרעים וחרקים.","אני מגרדת באדמה ומחפשת אוכל.","אני לא יכולה לעוף רחוק."],"powers":[{"title":"שן לבקיעה","kid":"לאפרוח יש על המקור קצה קטנטן וקשה, שנקרא שן ביצה, שבעזרתו הוא מנקר את דרכו החוצה מהקליפה. זמן קצר אחר כך הוא נושר.","teen":"לקראת הבקיעה האפרוח מנקב את תא האוויר בקצה הקהה של הביצה, ואז מנקר: הוא דוחף את שן הביצה הזמנית דרך הקליפה, ותוך כדי שהוא מסתובב הוא חותך לעצמו דרך החוצה.","part":"beak"},{"title":"רגליים שמגרדות","kid":"רגליים חזקות עם טפרים מגרדות את האדמה וחושפות זרעים וחרקים שמסתתרים מתחת.","teen":"תרנגולות הן אוכלות־כול שמגרדות את האדמה ברגליים בעלות טפרים כדי לחשוף מזון: זרעים וחרקים, ואפילו בעלי חיים בגודל של לטאות, נחשים קטנים ועכברים צעירים.","part":"feet"},{"title":"שתי אזעקות שונות","kid":"לתרנגולות יש קריאות אזהרה שונות: אחת לסכנה מהשמיים, כמו נץ, ואחרת לסכנה על הקרקע.","teen":"תרנגולות משמיעות קריאות אזעקה נפרדות לטורפים שמתקרבים מהאוויר ומהקרקע, כך ששאר הלהקה יכולה להגיב נכון לכל סוג של איום.","part":"throat"}],"field_note":{"place":"Israel","text":"במרשה שבשפלת יהודה מצאו חוקרים מאוניברסיטת חיפה יותר מאלף עצמות תרנגולות עם סימני ביתור, מלפני כ־2,100–2,400 שנה: המקום הקדום ביותר הידוע מחוץ למזרח אסיה שבו גידלו תרנגולות למאכל."},"lab_note":"ג'ון אסרה, כריס אורגן ועמיתיהם בהרווארד (2007–2008) חקרו פיסות חלבון מעצם רגל של טי־רקס בן 68 מיליון שנה. הטי־רקס התאים לקבוצת הציפורים, תרנגולת ויען, יותר מאשר לאליגטורים או ללטאות.","myth":{"claim":"מכל ביצה יכול לבקוע אפרוח.","verdict":"myth","why":"תרנגולות מטילות ביצים גם בלי תרנגול. הביצים האלה לא מופרות, ולכן שום אפרוח לא יכול להתפתח בתוכן. רק ביצים מופרות שמחממים אותן כ־21 יום בוקעות."},"clues":["אני ציפור שגרה בחוות.","אני מגרדת באדמה ומחפשת זרעים וחרקים.","אני מקרקרת, והאפרוחים שלי בוקעים אחרי כ־21 יום."],"compare":{"stat":"Lifespan","value":10,"unit":"years","text":"עד כ־10 שנים"},"stats":[{"label":"משקל","value":"כ־1.5–3.6 ק״ג","note":"תרנגולת, לפי הגזע; התרנגולים כבדים יותר"},{"label":"ביצים","value":"יותר מ־300 בשנה","note":"תרנגולת מגזע מטילות"},{"label":"בקיעה","value":"כ־21 יום","note":"מביצה מחוממת ועד אפרוח"},{"label":"תוחלת חיים","value":"5–10 שנים","note":"לפי הגזע"}],"taxonomy":["בעלי חיים","עופות · Aves","תרנגולאים · Galliformes","פסיוניים · Phasianidae","Gallus gallus domesticus"]}},"frog":{"id":"frog","i":17,"latin":"Pelophylax bedriagae","group":"amphibian","home":"pond","diet":"carn","active":null,"continents":["Asia","Europe"],"iucn":"LC","en":{"name":"Levant water frog","habitat_text":"Rivers, streams, ponds and marshes that hold water all year, from northern Israel to the edge of the Negev","menu":"Mainly insects.","iucn_note":"Least Concern worldwide. It needs water all year, so drying streams and ponds are a danger; some populations in western Turkey have declined.","page_facts":["I live in streams and ponds.","I eat insects.","I was once a tadpole.","I am Israel's biggest frog."],"powers":[{"title":"Swimming legs","kid":"Its big back legs and webbed toes push it through the water like paddles.","teen":"Its hind limbs are much larger than its forelimbs and its toes are webbed, suiting a frog that spends its whole life cycle in or beside water.","part":"back legs"},{"title":"Balloon voice","kid":"A male calls by puffing up two white balloons, one on each side of its head.","teen":"Males make advertisement calls by inflating paired external vocal sacs. In 2023, Ulrich Sinsch's team recorded the calls of Turkish water frogs to test whether calls separate related species.","part":"vocal sacs"},{"title":"Mud hideout","kid":"When its pond dries up, it can move to wetter places or dig into the mud to wait for water.","teen":"Unlike Israel's desert-going green toad, it stores little water in its body, so in severe drought it relies on behaviour: moving to wetter sites or burrowing into mud.","part":"body"}],"field_note":{"place":"Israel","text":"The Levant water frog is Israel's largest frog. It lives in water all year, in rivers, streams, ponds and marshes from the north to the edge of the Negev, but not in the desert."},"lab_note":"Gad Degani of MIGAL–Galilee Research Institute compared Israel's water frog with the green toad: water frog tadpoles can stay in the water up to 7–8 months, while green toad tadpoles change into toads within 1–3 months.","myth":{"claim":"Touching a frog gives you warts.","verdict":"myth","why":"Warts are caused by a human virus, not by frogs or toads. This frog is not poisonous either, but wash your hands after touching any amphibian."},"clues":["I start my life as a tadpole.","I live in water all year round.","I am Israel's biggest frog, and males sing with two white balloons."],"compare":{"stat":"Length","value":9,"unit":"cm","text":"body about 6–9 cm"},"stats":[{"label":"Body length","value":"6–9 cm","note":"snout to rump, measured adults; females are bigger"},{"label":"Weight","value":"about 60 g","note":"a grown frog"},{"label":"Eggs","value":"1,000–3,000","note":"in one clutch"},{"label":"Tadpole time","value":"up to 7–8 months","note":"in the water before turning into a frog"}],"taxonomy":["Animals","Amphibians · Amphibia","Frogs and toads · Anura","True frogs · Ranidae","Pelophylax bedriagae"]},"he":{"name":"צפרדע הנחלים","habitat_text":"נהרות, נחלים, בריכות וביצות שיש בהם מים כל השנה, מצפון ישראל ועד שולי הנגב","menu":"בעיקר חרקים.","iucn_note":"ללא חשש בעולם כולו. היא צריכה מים כל השנה, ולכן נחלים ובריכות שמתייבשים הם סכנה עבורה; כמה אוכלוסיות במערב טורקיה הצטמצמו.","page_facts":["אני גרה בנחלים ובבריכות.","אני אוכלת חרקים.","פעם הייתי ראשן.","אני הצפרדע הגדולה ביותר בישראל."],"powers":[{"title":"רגלי שחייה","kid":"הרגליים האחוריות הגדולות שלה והאצבעות עם קרום השחייה דוחפות אותה במים כמו משוטים.","teen":"הגפיים האחוריות שלה גדולות בהרבה מהקדמיות, ובין אצבעותיה יש קרומי שחייה, כמו שמתאים לצפרדע שכל מחזור החיים שלה עובר במים או לידם.","part":"back legs"},{"title":"קול של בלונים","kid":"זכר קורא כשהוא מנפח שני בלונים לבנים, אחד בכל צד של הראש.","teen":"הזכרים משמיעים קריאות חיזור בעזרת זוג שקי קול חיצוניים שהם מנפחים. ב־2023 הקליט הצוות של אולריך זינש קריאות של צפרדעי מים בטורקיה, כדי לבדוק אם הקריאות מבדילות בין מינים קרובים.","part":"vocal sacs"},{"title":"מחבוא בבוץ","kid":"כשהבריכה שלה מתייבשת, היא יכולה לעבור למקום רטוב יותר או להתחפר בבוץ ולחכות למים.","teen":"בניגוד לקרפדה הירוקה של ישראל, שמסתדרת גם במדבר, היא אוגרת מעט מים בגופה, ולכן בבצורת קשה היא נשענת על התנהגות: מעבר למקומות רטובים יותר או התחפרות בבוץ.","part":"body"}],"field_note":{"place":"Israel","text":"צפרדע הנחלים היא הצפרדע הגדולה ביותר בישראל. היא חיה במים כל השנה, בנהרות, בנחלים, בבריכות ובביצות, מהצפון ועד שולי הנגב, אבל לא במדבר."},"lab_note":"גד דגני ממיגל – מכון מחקר גליל השווה בין צפרדע הנחלים לקרפדה הירוקה: ראשנים של צפרדע הנחלים יכולים להישאר במים עד 7–8 חודשים, ואילו ראשני הקרפדה הירוקה הופכים לקרפדות תוך 1–3 חודשים.","myth":{"claim":"נגיעה בצפרדע גורמת ליבלות.","verdict":"myth","why":"יבלות נגרמות מווירוס של בני אדם, לא מצפרדעים או מקרפדות. גם הצפרדע הזאת לא רעילה, אבל אחרי שנוגעים בדו־חי כלשהו, שוטפים ידיים."},"clues":["אני מתחילה את החיים כראשן.","אני גרה במים כל השנה.","אני הצפרדע הגדולה ביותר בישראל, והזכרים אצלנו שרים עם שני בלונים לבנים."],"compare":{"stat":"Length","value":9,"unit":"cm","text":"גוף באורך של כ־6–9 ס״מ"},"stats":[{"label":"אורך גוף","value":"6–9 ס״מ","note":"מקצה החוטם ועד סוף הגוף, בבוגרים שנמדדו; הנקבות גדולות יותר"},{"label":"משקל","value":"כ־60 גרם","note":"צפרדע בוגרת"},{"label":"ביצים","value":"1,000–3,000","note":"בהטלה אחת"},{"label":"תקופת הראשן","value":"עד 7–8 חודשים","note":"במים, לפני שהוא הופך לצפרדע"}],"taxonomy":["בעלי חיים","דו־חיים · Amphibia","צפרדעים וקרפדות · Anura","צפרדעיים · Ranidae","Pelophylax bedriagae"]}},"duck":{"id":"duck","i":18,"latin":"Anas platyrhynchos","group":"bird","home":"pond","diet":"omni","active":"day","continents":["North America","Europe","Asia","Africa"],"iucn":"LC","en":{"name":"Mallard","habitat_text":"Ponds, lakes, rivers, marshes, estuaries and city parks","menu":"Seeds, water plants and grain, plus snails, insects, worms and small crustaceans. Females laying eggs eat mostly small animals.","iucn_note":"Least Concern. One of the most widespread ducks on Earth, with more than 17 million adults. Where people have released mallards outside their home range, they crossbreed with local ducks.","page_facts":["I tip upside down to eat.","I paddle with webbed feet.","I can sleep with one eye open.","My ducklings swim on day one."],"powers":[{"title":"A bill with a built-in sieve","kid":"Comb-like edges along its bill let muddy water squirt out but keep seeds and tiny animals inside.","teen":"Rows of comb-like pecten line the edges of the bill. As water squirts out the sides, seeds and small invertebrates are strained out and trapped. The pecten also helps with preening.","part":"bill"},{"title":"Paddles that save heat","kid":"Its webbed feet push like paddles. In its legs, warm and cold blood vessels run side by side, so little heat is lost.","teen":"Webbed feet work as paddles. Arteries and veins in the legs form a countercurrent heat exchanger: blood flowing down warms blood flowing back, so little body heat escapes through the feet.","part":"feet"},{"title":"Half asleep, half on guard","kid":"It can rest one half of its brain while the other half stays awake, watching for foxes through one open eye.","teen":"In unihemispheric slow-wave sleep, one brain hemisphere sleeps while the other stays alert, linked to the open eye. Mallards sleep this way more often when the risk from predators is higher.","part":"eyes"}],"field_note":{"place":"Israel","text":"Mallards are winter guests in Israel. Each winter thousands rest and feed on ponds and lakes all over the country, and a growing number now stay all year and nest here."},"lab_note":"In 1999, Niels Rattenborg, Steven Lima and Charles Amlaner watched mallards sleeping in a row. Ducks at the ends slept with one eye open far more often, and kept that eye facing away from the group.","myth":{"claim":"A duck's quack does not echo.","verdict":"myth","why":"Acoustics professor Trevor Cox at the University of Salford tested a duck's quack in a room built to make echoes. It does echo. The echo is just quiet and hard to hear."},"clues":["I live on ponds, lakes and rivers.","I tip my tail up to find food underwater.","The males of my kind have a shiny green head and a white neck ring."],"compare":{"stat":"Wingspan","value":98,"unit":"cm","text":"up to 98 cm"},"stats":[{"label":"Length","value":"50–65 cm","note":"bill to tail"},{"label":"Wingspan","value":"79–98 cm","note":"tip to tip"},{"label":"Weight","value":"0.7–1.6 kg","note":"heavier than most dabbling ducks"},{"label":"Eggs","value":"up to 13","note":"ducklings can swim as soon as they hatch"}],"taxonomy":["Animals","Birds · Aves","Waterfowl · Anseriformes","Ducks, geese and swans · Anatidae","Anas platyrhynchos"]},"he":{"name":"ברווז (ברכייה)","habitat_text":"בריכות, אגמים, נהרות, ביצות, שפכי נהרות וגנים עירוניים","menu":"זרעים, צמחי מים ודגנים, וגם חלזונות, חרקים, תולעים וסרטנאים קטנים. נקבות שמטילות ביצים אוכלות בעיקר בעלי חיים קטנים.","iucn_note":"ללא חשש. אחד הברווזים הנפוצים ביותר בעולם, עם יותר מ־17 מיליון פרטים בוגרים. במקומות שבהם אנשים שחררו ברכיות מחוץ לתחום התפוצה הטבעי שלהן, הן מזדווגות עם ברווזים מקומיים ויוצרות כלאיים.","page_facts":["אני מתהפך במים כדי לאכול.","אני חותר ברגלי השחייה שלי.","אני יכול לישון עם עין אחת פקוחה.","הברווזונים שלי שוחים כבר ביום הראשון."],"powers":[{"title":"מקור עם מסננת מובנית","kid":"לאורך המקור שלו יש שוליים דמויי מסרק: המים הבוציים ניתזים החוצה, אבל זרעים ובעלי חיים זעירים נשארים בפנים.","teen":"שורות של בליטות דמויות מסרק (פקטן) מרפדות את שולי המקור. כשהמים ניתזים מהצדדים, זרעים וחסרי חוליות קטנים מסוננים ונלכדים. הפקטן עוזר גם בטיפוח הנוצות.","part":"bill"},{"title":"משוטים ששומרים על החום","kid":"כפות הרגליים שלו, עם קרומי השחייה, דוחפות כמו משוטים. ברגליים שלו כלי דם חמים וקרים עוברים זה לצד זה, ולכן מעט חום הולך לאיבוד.","teen":"כפות רגליים עם קרומי שחייה פועלות כמשוטים. העורקים והוורידים ברגליים יוצרים מחליף חום בזרימה נגדית: הדם שזורם למטה מחמם את הדם שחוזר למעלה, כך שמעט חום גוף בורח דרך כפות הרגליים.","part":"feet"},{"title":"חצי ישן, חצי שומר","kid":"הוא יכול לתת לחצי אחד של המוח שלו לנוח, בזמן שהחצי השני נשאר ער ושומר מפני שועלים דרך עין אחת פקוחה.","teen":"בשינת גלים איטיים חד־המיספרית, מחצית אחת של המוח ישנה והשנייה נשארת דרוכה, וקשורה לעין הפקוחה. ברכיות ישנות כך לעיתים קרובות יותר כשהסכנה מטורפים גבוהה יותר.","part":"eyes"}],"field_note":{"place":"Israel","text":"ברכיות הן אורחות חורף בישראל. בכל חורף אלפים מהן נחות וניזונות בבריכות ובאגמים בכל רחבי הארץ, ויותר ויותר מהן נשארות כאן כל השנה ומקננות."},"lab_note":"ב־1999 צפו נילס ראטנבורג, סטיבן לימה וצ'ארלס אמלנר בברכיות שישנו בשורה. הברווזים שבקצוות השורה ישנו עם עין אחת פקוחה הרבה יותר פעמים, והפנו את העין הזאת החוצה, הרחק מהקבוצה.","myth":{"claim":"לגעגוע של ברווז אין הד.","verdict":"myth","why":"פרופסור לאקוסטיקה טרוור קוקס מאוניברסיטת סלפורד בדק געגוע של ברווז בחדר שנבנה כדי ליצור הדים. יש לו הד. ההד פשוט שקט וקשה לשמוע אותו."},"clues":["אני גר בבריכות, באגמים ובנהרות.","אני מרים את הזנב למעלה כדי למצוא אוכל מתחת למים.","לזכרים מהמין שלי יש ראש ירוק ומבריק וטבעת לבנה על הצוואר."],"compare":{"stat":"Wingspan","value":98,"unit":"cm","text":"עד 98 ס״מ"},"stats":[{"label":"אורך","value":"50–65 ס״מ","note":"מהמקור עד הזנב"},{"label":"מוטת כנפיים","value":"79–98 ס״מ","note":"מקצה כנף אחת לקצה השנייה"},{"label":"משקל","value":"0.7–1.6 ק״ג","note":"כבד יותר מרוב הברווזים המשכשכים"},{"label":"ביצים","value":"עד 13","note":"הברווזונים יכולים לשחות מיד כשהם בוקעים"}],"taxonomy":["בעלי חיים","עופות · Aves","אווזאים · Anseriformes","ברווזיים · Anatidae","Anas platyrhynchos"]}},"lion":{"id":"lion","i":19,"latin":"Panthera leo","group":"mammal","home":"savanna","diet":"carn","active":"night","continents":["Africa","Asia"],"iucn":"VU","en":{"name":"Lion","habitat_text":"Grassland, savanna, scrub and open woodland in Africa; dry forest in India's Gir","menu":"Mostly medium and large hoofed animals such as wildebeest, zebra, buffalo, impala and warthog. A lioness eats about 5 kg of meat a day, a male about 7 kg.","iucn_note":"Vulnerable since 1996. African lions have declined by about 43% since the early 1990s and now live in about 8% of their old range. Main dangers: habitat loss and conflict with people and their livestock.","page_facts":["I rest about 20 hours a day.","My family is called a pride.","My roar can be heard far away.","I eat only meat."],"powers":[{"title":"A roar that carries","kid":"A lion's roar can be heard up to 8 km away. Lions roar to let other lions know where they are.","teen":"Prides split into smaller groups and keep in contact by roaring. A roar advertises a lion's presence and, in good conditions, carries about 8 km, most often at night.","part":"throat"},{"title":"A mane that sends a message","kid":"Male lions grow a big mane. A darker mane tells other lions that the male is strong and healthy.","teen":"Mane growth is driven by testosterone. Darker-maned males have higher testosterone and more breeding success, but pay a price: the surface of their body heats up more in the sun.","part":"mane"},{"title":"Hidden hooks","kid":"Its sharp claws slide back into its paws while it walks, then come out to grab and hold prey.","teen":"Sharp, retractable claws stay sheathed while the lion walks and extend to grip large prey. Upper canine teeth about 5 cm long then hold the prey fast.","part":"paws"}],"field_note":{"place":"Israel","text":"Lions once lived in the Land of Israel; the Bible tells how Samson met one. The latest lion bone found in Israel comes from a Crusader site of the 1100s. Lions vanished as farms and towns spread."},"lab_note":"In the Serengeti, Peyton West and Craig Packer set out life-size toy lions with different manes (2002). Lionesses preferred dark manes, while males kept away from long, dark-maned rivals.","myth":{"claim":"Lions live in the jungle.","verdict":"myth","why":"Lions live on grassy plains, savannas, scrub and open woodland, and rarely enter thick forest. 'King of the jungle' is just a saying."},"clues":["I sleep or rest for most of the day.","I live with my family in a group called a pride.","I am a big cat, and the males of my kind grow a shaggy mane."],"compare":{"stat":"Weight","value":225,"unit":"kg","text":"up to 225 kg"},"stats":[{"label":"Length","value":"1.6–2.5 m","note":"head and body; the tail adds 0.6–1 m"},{"label":"Shoulder height","value":"about 1.1–1.2 m","note":"males taller"},{"label":"Weight","value":"118–225 kg","note":"males heavier"},{"label":"Roar","value":"heard up to 8 km away","note":"most often at night"}],"taxonomy":["Animals","Mammals · Mammalia","Carnivores · Carnivora","Cats · Felidae","Panthera leo"]},"he":{"name":"אריה","habitat_text":"שטחי עשב, סוואנה, שיחים ויערות פתוחים באפריקה; יער יבש בגיר שבהודו","menu":"בעיקר בעלי פרסות בינוניים וגדולים, כמו גנו, זברה, תאו, אימפלה וחזיר יבלות. לביאה אוכלת כ־5 ק״ג בשר ביום, וזכר כ־7 ק״ג.","iucn_note":"פגיע מאז 1996. מספר האריות באפריקה ירד בכ־43% מאז תחילת שנות ה־90, והיום הם חיים בכ־8% מהשטח שבו חיו בעבר. הסכנות העיקריות: אובדן בתי גידול ועימותים עם בני אדם ועם משק החי שלהם.","page_facts":["אני נח בערך 20 שעות ביום.","המשפחה שלי נקראת להקה.","את השאגה שלי שומעים מרחוק.","אני אוכל רק בשר."],"powers":[{"title":"שאגה שמגיעה רחוק","kid":"את השאגה של אריה אפשר לשמוע למרחק של עד 8 ק״מ. אריות שואגים כדי להודיע לאריות אחרים איפה הם נמצאים.","teen":"להקות מתפצלות לקבוצות קטנות ושומרות על קשר בשאגות. שאגה מודיעה שהאריה נמצא באזור, ובתנאים טובים היא נשמעת למרחק של כ־8 ק״מ, לרוב בלילה.","part":"throat"},{"title":"רעמה ששולחת מסר","kid":"לאריות זכרים צומחת רעמה גדולה. רעמה כהה יותר אומרת לאריות אחרים שהזכר חזק ובריא.","teen":"צמיחת הרעמה תלויה בטסטוסטרון. לזכרים עם רעמה כהה יש יותר טסטוסטרון ויותר הצלחה ברבייה, אבל יש לכך מחיר: פני השטח של גופם מתחממים יותר בשמש.","part":"mane"},{"title":"ווים נסתרים","kid":"הטפרים החדים שלו נסוגים לתוך הכפות בזמן ההליכה, ויוצאים החוצה כדי לתפוס טרף ולהחזיק בו.","teen":"טפרים חדים ונסוגים נשארים מכוסים בזמן שהאריה הולך, ונשלפים כדי לאחוז בטרף גדול. ניבים עליונים באורך של כ־5 ס״מ מחזיקים אז את הטרף בחוזקה.","part":"paws"}],"field_note":{"place":"Israel","text":"פעם חיו אריות בארץ ישראל; התנ״ך מספר איך שמשון פגש אריה. עצם האריה המאוחרת ביותר שנמצאה בישראל מגיעה מאתר צלבני מהמאה ה־12. האריות נעלמו כששדות ויישובים התפשטו."},"lab_note":"בסרנגטי הציבו פייטון וסט וקרייג פאקר בובות אריה בגודל טבעי עם רעמות שונות (2002). הלביאות העדיפו רעמות כהות, והזכרים התרחקו מיריבים עם רעמה ארוכה וכהה.","myth":{"claim":"אריות חיים בג'ונגל.","verdict":"myth","why":"אריות חיים במישורי עשב, בסוואנות, בשטחי שיחים וביערות פתוחים, ורק לעיתים רחוקות נכנסים ליער סבוך. \"מלך הג'ונגל\" הוא סתם ביטוי."},"clues":["אני ישן או נח רוב שעות היום.","אני גר עם המשפחה שלי בקבוצה שנקראת להקה.","אני חתול גדול, ולזכרים מהמין שלי צומחת רעמה פרועה."],"compare":{"stat":"Weight","value":225,"unit":"kg","text":"עד 225 ק״ג"},"stats":[{"label":"אורך","value":"1.6–2.5 מ׳","note":"ראש וגוף; הזנב מוסיף 0.6–1 מ׳"},{"label":"גובה כתפיים","value":"כ־1.1–1.2 מ׳","note":"הזכרים גבוהים יותר"},{"label":"משקל","value":"118–225 ק״ג","note":"הזכרים כבדים יותר"},{"label":"שאגה","value":"נשמעת עד 8 ק״מ","note":"לרוב בלילה"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","טורפים · Carnivora","חתוליים · Felidae","Panthera leo"]}},"elephant":{"id":"elephant","i":20,"latin":"Loxodonta africana","group":"mammal","home":"savanna","diet":"herb","active":"day and night","continents":["Africa"],"iucn":"EN","en":{"name":"African bush elephant","habitat_text":"Savanna, grassland, woodland, forest and wetland across Africa south of the Sahara","menu":"Grasses, leaves, bark, herbs and climbing plants: about 150 kg of food a day, washed down with about 230 litres of water.","iucn_note":"Endangered since 2021. Numbers fell by more than half over three generations. Main dangers: loss of habitat and, in parts of Africa, poaching for meat and ivory.","page_facts":["I am the biggest land animal.","My nose is my long trunk.","I flap my ears to cool down.","I eat grass, leaves and bark."],"powers":[{"title":"A nose that works like a hand","kid":"Its trunk is its nose and top lip joined together. It is strong enough to lift 350 kg, yet gentle enough to crack a peanut.","teen":"The trunk is a boneless muscular hydrostat with up to 150,000 muscle bundles. It smells, touches with two finger-like tips, sucks up water and squirts it into the mouth.","part":"trunk"},{"title":"Built-in fans","kid":"Its huge ears are full of tiny blood vessels. Flapping them cools its blood on hot days.","teen":"Ear flaps only 1–2 mm thick in the middle are packed with capillaries that release heat; flapping speeds this up. Bush elephants live in the hottest climates and have the largest ears of any elephant.","part":"ears"},{"title":"Teeth that never stop growing","kid":"Its tusks are giant front teeth that keep growing, about 17 cm a year. It uses them to dig, strip bark and fight.","teen":"Tusks are modified upper incisors made of ivory (dentine). Both male and female African elephants grow them, and most elephants favour one 'master' tusk, like being right- or left-handed.","part":"tusks"}],"field_note":{"place":"Israel","text":"At Ramat Gan Safari near Tel Aviv, all six female African elephants gave birth in 1987, two of them on the same day. By 2013, 21 African elephant calves had been born and raised there."},"lab_note":"Mickey Pardo and colleagues studied 469 elephant rumbles recorded in Kenya (2024). Elephants answered faster and more strongly to calls first made to them, suggesting they call each other by name-like sounds.","myth":{"claim":"Elephants drink through their trunks like a straw.","verdict":"myth","why":"An elephant sucks water up into its trunk, then squirts it into its mouth or sprays it over its body. The trunk works more like a hose than a straw."},"clues":["My family is led by an older female.","I have a long trunk and two big tusks.","I am the biggest animal that walks on land."],"compare":{"stat":"Weight","value":6000,"unit":"kg","text":"about 6,000 kg for an adult male"},"stats":[{"label":"Height","value":"2.5–3.7 m","note":"at the shoulder; males taller"},{"label":"Length","value":"6–7.5 m","note":"trunk tip to tail"},{"label":"Weight","value":"2.6–6.9 tonnes","note":"males about twice as heavy"},{"label":"Food","value":"about 150 kg a day","note":"grass, leaves and bark"}],"taxonomy":["Animals","Mammals · Mammalia","Elephants · Proboscidea","Elephant family · Elephantidae","Loxodonta africana"]},"he":{"name":"פיל אפריקני","habitat_text":"סוואנות, שטחי עשב, חורשות, יערות ואזורי ביצה ברחבי אפריקה שמדרום לסהרה","menu":"עשבים, עלים, קליפת עצים, צמחים עשבוניים וצמחים מטפסים: כ־150 ק״ג מזון ביום, ואיתם כ־230 ליטר מים.","iucn_note":"בסכנת הכחדה מאז 2021. מספרם ירד ביותר ממחצית במשך שלושה דורות. הסכנות העיקריות: אובדן בתי גידול, ובחלקים מאפריקה גם ציד בלתי חוקי לשם בשר ושנהב.","page_facts":["אני חיית היבשה הגדולה ביותר.","האף שלי הוא החדק הארוך.","אני מנפנף באוזניים כדי להתקרר.","אני אוכל עשב, עלים וקליפות עצים."],"powers":[{"title":"אף שעובד כמו יד","kid":"החדק שלו הוא האף והשפה העליונה שהתחברו יחד. הוא חזק מספיק כדי להרים 350 ק״ג, ועדין מספיק כדי לפצח בוטן.","teen":"החדק הוא הידרוסטט שרירי בלי עצמות, עם עד 150,000 צרורות שריר. הוא מריח, ממשש בעזרת שני קצוות דמויי אצבעות, שואב מים ומתיז אותם לתוך הפה.","part":"trunk"},{"title":"מאווררים מובנים","kid":"האוזניים הענקיות שלו מלאות בכלי דם זעירים. כשהוא מנפנף בהן בימים חמים, הדם שלו מתקרר.","teen":"האוזניים, שעוביין באמצע רק 1–2 מ״מ, צפופות בנימים שמשחררים חום, והנפנוף מאיץ את זה. פילי הסוואנה חיים באקלים החם ביותר, ויש להם האוזניים הגדולות ביותר מכל הפילים.","part":"ears"},{"title":"שיניים שלא מפסיקות לגדול","kid":"החטים שלו הן שיני חזית ענקיות שממשיכות לגדול, כ־17 ס״מ בשנה. הוא משתמש בהן כדי לחפור, לקלף קליפת עצים ולהילחם.","teen":"החטים הן שיניים חותכות עליונות שהשתנו, עשויות שנהב (דנטין). גם לזכרים וגם לנקבות של פילים אפריקניים יש חטים, ורוב הפילים מעדיפים חט \"ראשי\" אחד, כמו אנשים ימניים או שמאליים.","part":"tusks"}],"field_note":{"place":"Israel","text":"בספארי ברמת גן, ליד תל אביב, כל שש נקבות הפיל האפריקני המליטו ב־1987, שתיים מהן באותו יום. עד 2013 נולדו וגדלו שם 21 פילונים אפריקניים."},"lab_note":"מיקי פרדו ועמיתיו חקרו 469 נהמות של פילים שהוקלטו בקניה (2024). הפילים הגיבו מהר יותר ובעוצמה רבה יותר לקריאות שנאמרו במקור אליהם, מה שמרמז שהם קוראים זה לזה בצלילים שדומים לשמות.","myth":{"claim":"פילים שותים דרך החדק כמו בקשית.","verdict":"myth","why":"פיל שואב מים לתוך החדק, ואז מתיז אותם לתוך הפה או מרסס אותם על הגוף. החדק עובד יותר כמו צינור מאשר כמו קשית."},"clues":["את המשפחה שלי מובילה נקבה מבוגרת.","יש לי חדק ארוך ושני חטים גדולים.","אני החיה הגדולה ביותר שהולכת על היבשה."],"compare":{"stat":"Weight","value":6000,"unit":"kg","text":"כ־6,000 ק״ג לזכר בוגר"},"stats":[{"label":"גובה","value":"2.5–3.7 מ׳","note":"בכתפיים; הזכרים גבוהים יותר"},{"label":"אורך","value":"6–7.5 מ׳","note":"מקצה החדק עד הזנב"},{"label":"משקל","value":"2.6–6.9 טון","note":"הזכרים כבדים בערך פי שניים"},{"label":"מזון","value":"כ־150 ק״ג ביום","note":"עשב, עלים וקליפת עצים"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","חדקנים · Proboscidea","פיליים · Elephantidae","Loxodonta africana"]}},"giraffe":{"id":"giraffe","i":21,"latin":"Giraffa reticulata","group":"mammal","home":"savanna","diet":"herb","active":"day and night","continents":["Africa"],"iucn":"EN","en":{"name":"Reticulated giraffe","habitat_text":"Savannas and open woodlands of Africa, south of the Sahara","menu":"Leaves, shoots, flowers, fruits and seed pods of trees and shrubs, especially acacias: around 34 kg of plant food a day.","iucn_note":"Endangered (listed in 2018). About 20,900 remain in the wild, more than 40% fewer than 35 years ago, and over 95% of them live outside protected parks. In 2025 the IUCN recognised four giraffe species; this is one of them.","page_facts":["I am the tallest animal.","My neck has seven bones.","I eat leaves from tall trees.","My tongue is long and dark."],"powers":[{"title":"A neck for the treetops","kid":"Its neck has seven bones, like yours, but each can be over 28 cm long, so it reaches leaves others can't.","teen":"Seven elongated neck vertebrae, each over 28 cm, make up about half the length of its spine, letting it browse far above the reach of other ground-dwelling plant-eaters.","part":"neck"},{"title":"A tongue that grabs","kid":"Its dark tongue, about 45–50 cm long, wraps around twigs and pulls off the leaves.","teen":"A prehensile tongue 45–50 cm long grips and strips foliage from branches. Its dark colour may help protect it from sunburn.","part":"tongue"},{"title":"A super-strong heart","kid":"Its heart weighs about 11 kg and pumps hard enough to push blood all the way up its long neck to its brain.","teen":"An 11 kg heart with walls up to 7.5 cm thick keeps average blood pressure around 200 mm Hg, high enough that about 100 mm Hg is still left at the head.","part":"chest"}],"field_note":{"place":"","text":"'Reticulated' means 'like a net': bright white lines form a net over its orange-brown patches, all the way down its legs."},"lab_note":"Anton Baotic, Florian Sicks and Angela Stoeger of the University of Vienna recorded over 947 hours of sound in three European zoos (2015). They discovered that giraffes hum softly at night.","myth":{"claim":"A giraffe's long neck has more bones than ours.","verdict":"myth","why":"Giraffes have seven neck bones, the same as people and almost all other mammals. Each giraffe neck bone is just much longer: over 28 cm."},"clues":["I have brown patches all over my coat.","I eat leaves from the tops of trees.","I am the tallest animal on Earth."],"compare":{"stat":"Height","value":5.7,"unit":"m","text":"up to 5.7 m"},"stats":[{"label":"Height","value":"4.2–5.7 m","note":"ground to head; males taller"},{"label":"Neck","value":"up to 2.4 m","note":"with just 7 neck bones"},{"label":"Weight","value":"700–1,400 kg","note":"males heavier"},{"label":"Top speed","value":"about 55–60 km/h","note":"in short sprints"}],"taxonomy":["Animals","Mammals · Mammalia","Even-toed hoofed mammals · Artiodactyla","Giraffes and okapi · Giraffidae","Giraffa reticulata"]},"he":{"name":"ג'ירפה","habitat_text":"סוואנות וחורשות פתוחות באפריקה, מדרום לסהרה","menu":"עלים, נצרים, פרחים, פירות ותרמילי זרעים של עצים ושיחים, בעיקר שיטים: כ־34 ק״ג מזון צמחי ביום.","iucn_note":"בסכנת הכחדה (נקבע ב־2018). בטבע נותרו כ־20,900, יותר מ־40% פחות מאשר לפני 35 שנה, ויותר מ־95% מהן חיות מחוץ לפארקים מוגנים. ב־2025 הכיר ה־IUCN בארבעה מינים של ג'ירפות, וזה אחד מהם.","page_facts":["אני החיה הגבוהה ביותר.","בצוואר שלי יש שבע עצמות.","אני אוכלת עלים מעצים גבוהים.","הלשון שלי ארוכה וכהה."],"powers":[{"title":"צוואר שמגיע לצמרות","kid":"בצוואר שלה יש שבע עצמות, כמו אצלנו, אבל כל אחת יכולה להיות ארוכה מ־28 ס״מ, ולכן היא מגיעה לעלים שאחרים לא מגיעים אליהם.","teen":"שבע חוליות צוואר מוארכות, כל אחת ארוכה מ־28 ס״מ, הן כמחצית מאורך עמוד השדרה שלה. כך היא אוכלת עלים גבוה הרבה מעל טווח ההשגה של אוכלי צמחים אחרים שחיים על הקרקע.","part":"neck"},{"title":"לשון שתופסת","kid":"הלשון הכהה שלה, באורך של כ־45–50 ס״מ, נכרכת סביב ענפים ותולשת מהם את העלים.","teen":"לשון אוחזת באורך 45–50 ס״מ תופסת עלווה ומפשיטה אותה מהענפים. ייתכן שהצבע הכהה שלה עוזר להגן עליה מכוויות שמש.","part":"tongue"},{"title":"לב חזק במיוחד","kid":"הלב שלה שוקל כ־11 ק״ג ושואב בכוח רב מספיק כדי לדחוף דם עד למעלה בצוואר הארוך, אל המוח.","teen":"לב במשקל 11 ק״ג, עם דפנות בעובי של עד 7.5 ס״מ, שומר על לחץ דם ממוצע של כ־200 מ״מ כספית, גבוה מספיק כדי שבראש יישאר עדיין כ־100 מ״מ כספית.","part":"chest"}],"field_note":{"place":"","text":"השם המלא שלה הוא ג'ירפה רשתית, כלומר \"כמו רשת\": קווים לבנים ובוהקים יוצרים רשת על הכתמים החומים־כתומים שלה, עד למטה ברגליים."},"lab_note":"אנטון באוטיץ', פלוריאן זיקס ואנגלה שטגר מאוניברסיטת וינה הקליטו יותר מ־947 שעות של צלילים בשלושה גני חיות באירופה (2015). הם גילו שג'ירפות מהמהמות חרש בלילה.","myth":{"claim":"בצוואר הארוך של הג'ירפה יש יותר עצמות מאשר אצלנו.","verdict":"myth","why":"לג'ירפות יש שבע עצמות צוואר, כמו לבני אדם ולכמעט כל היונקים האחרים. פשוט כל עצם בצוואר של ג'ירפה ארוכה הרבה יותר: יותר מ־28 ס״מ."},"clues":["יש לי כתמים חומים על כל הפרווה.","אני אוכלת עלים מצמרות העצים.","אני החיה הגבוהה ביותר על כדור הארץ."],"compare":{"stat":"Height","value":5.7,"unit":"m","text":"עד 5.7 מ׳"},"stats":[{"label":"גובה","value":"4.2–5.7 מ׳","note":"מהקרקע עד הראש; הזכרים גבוהים יותר"},{"label":"צוואר","value":"עד 2.4 מ׳","note":"עם 7 עצמות צוואר בלבד"},{"label":"משקל","value":"700–1,400 ק״ג","note":"הזכרים כבדים יותר"},{"label":"מהירות מרבית","value":"כ־55–60 קמ״ש","note":"בריצות קצרות"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","מכפילי פרסה · Artiodactyla","ג'ירפיים · Giraffidae","Giraffa reticulata"]}},"kangaroo":{"id":"kangaroo","i":22,"latin":"Osphranter rufus","group":"mammal","home":"savanna","diet":"herb","active":"dawn and dusk","continents":["Australia"],"iucn":"LC","en":{"name":"Red kangaroo","habitat_text":"Dry open plains, grassland, shrubland and desert across inland Australia","menu":"Mostly fresh green grasses, plus herbs and the leaves of shrubs. It gets much of its water from the plants it eats.","iucn_note":"Least Concern. Millions live across inland Australia, about 5.8 million in 2017. Farm dams and waterholes have helped them; they are also harvested under government quotas.","page_facts":["I hop on my big back legs.","My baby grows in my pouch.","My baby is born jellybean-small.","I rest in the shade by day."],"powers":[{"title":"Pogo-stick legs","kid":"Springy tendons in its back legs work like a pogo stick, so hopping faster costs it hardly any extra energy.","teen":"Long, springy leg tendons store and return energy with every bound. On a treadmill, red kangaroos used oxygen at nearly the same rate as they hopped faster.","part":"legs"},{"title":"A tail that walks","kid":"When it moves slowly, it plants its thick tail on the ground like a fifth leg and swings its back legs forward.","teen":"In slow 'pentapedal' walking, the tail and forelimbs take the body's weight while the hind legs swing forward. Force-plate studies show the tail actively pushes the body forward, like a leg.","part":"tail"},{"title":"Lick-to-cool arms","kid":"On hot days it licks its forearms. As the spit dries, it carries heat away and cools the kangaroo down.","teen":"It keeps cool by resting in shade, panting, sweating and spreading saliva on its forearms to evaporate. It can go long periods without drinking, getting water from the plants it eats.","part":"arms"}],"field_note":{"place":"","text":"A red kangaroo mother can care for three young at once: a joey at her feet still drinking milk, a baby in her pouch, and a tiny embryo waiting, paused, inside her."},"lab_note":"Shawn O'Connor, Max Donelan, Terence Dawson and Rodger Kram had five red kangaroos walk across a force-measuring platform (2014). Their tails pushed them forward, working just like a leg.","myth":{"claim":"Baby kangaroos are born inside the pouch.","verdict":"myth","why":"A joey is born after only 33 days, blind, hairless and a few centimetres long. It climbs through its mother's fur into the pouch by itself, which takes 3–5 minutes."},"clues":["I eat grass on dry, open plains.","I carry my baby in a pouch.","I am the biggest kangaroo in the world."],"compare":{"stat":"Top speed","value":56,"unit":"km/h","text":"about 56–60 km/h"},"stats":[{"label":"Height","value":"about 1.5 m","note":"standing; almost 2 m stretched up on its toes"},{"label":"Tail","value":"65–120 cm","note":"strong enough to lean on"},{"label":"Weight","value":"17–92 kg","note":"males up to twice as heavy"},{"label":"Top speed","value":"about 56–60 km/h","note":"hopping"}],"taxonomy":["Animals","Mammals · Mammalia","Kangaroos, koalas and wombats · Diprotodontia","Kangaroos and wallabies · Macropodidae","Osphranter rufus"]},"he":{"name":"קנגורו אדום","habitat_text":"מישורים פתוחים ויבשים, שטחי עשב, שטחי שיחים ומדבר ברחבי פנים אוסטרליה","menu":"בעיקר עשבים ירוקים ורעננים, וגם צמחים עשבוניים ועלים של שיחים. הוא מקבל חלק גדול מהמים שלו מהצמחים שהוא אוכל.","iucn_note":"ללא חשש. מיליונים חיים ברחבי פנים אוסטרליה, כ־5.8 מיליון ב־2017. מאגרי מים בחוות ובורות מים עזרו להם; הם גם ניצודים לפי מכסות שהממשלה קובעת.","page_facts":["אני קופץ על הרגליים האחוריות הגדולות שלי.","התינוק שלי גדל בכיס שלי.","התינוק שלי נולד קטן כמו סוכריית ג'לי.","ביום אני נח בצל."],"powers":[{"title":"רגליים כמו מקל קפיצה","kid":"גידים קפיציים ברגליים האחוריות שלו עובדים כמו מקל קפיצה, ולכן כשהוא קופץ מהר יותר, זה כמעט לא עולה לו אנרגיה נוספת.","teen":"גידים ארוכים וקפיציים ברגליים אוגרים אנרגיה ומחזירים אותה בכל קפיצה. על הליכון, קנגורו אדומים צרכו חמצן כמעט באותו קצב גם כשקפצו מהר יותר.","part":"legs"},{"title":"זנב שהולך","kid":"כשהוא נע לאט, הוא מניח את הזנב העבה שלו על הקרקע כמו רגל חמישית ומניף את הרגליים האחוריות קדימה.","teen":"בהליכה איטית \"חמש־רגלית\", הזנב והגפיים הקדמיות נושאים את משקל הגוף בזמן שהרגליים האחוריות מתנופפות קדימה. מחקרים עם משטחי מדידת כוח מראים שהזנב דוחף את הגוף קדימה באופן פעיל, כמו רגל.","part":"tail"},{"title":"ליקוק שמקרר","kid":"בימים חמים הוא מלקק את הזרועות שלו. כשהרוק מתייבש, הוא לוקח איתו חום ומקרר את הקנגורו.","teen":"הוא שומר על קור בכך שהוא נח בצל, מתנשף, מזיע ומורח רוק על האמות כדי שיתאדה. הוא יכול להחזיק זמן רב בלי לשתות, ומקבל מים מהצמחים שהוא אוכל.","part":"arms"}],"field_note":{"place":"","text":"אמא קנגורו אדומה יכולה לטפל בשלושה צאצאים בבת אחת: גור לרגליה שעדיין יונק חלב, תינוק בכיס שלה, ועובר זעיר שמחכה בתוכה כשהתפתחותו מושהית."},"lab_note":"שון אוקונור, מקס דונלן, טרנס דוסון ורוג'ר קראם העבירו חמישה קנגורו אדומים בהליכה על משטח שמודד כוח (2014). הזנבות שלהם דחפו אותם קדימה ועבדו בדיוק כמו רגל.","myth":{"claim":"גורי קנגורו נולדים בתוך הכיס.","verdict":"myth","why":"גור קנגורו נולד אחרי 33 ימים בלבד, עיוור, בלי שיער ובאורך של סנטימטרים ספורים. הוא מטפס לבד דרך הפרווה של אמו אל הכיס, וזה לוקח 3–5 דקות."},"clues":["אני אוכל עשב במישורים יבשים ופתוחים.","אני נושא את התינוק שלי בכיס.","אני הקנגורו הגדול ביותר בעולם."],"compare":{"stat":"Top speed","value":56,"unit":"km/h","text":"כ־56–60 קמ״ש"},"stats":[{"label":"גובה","value":"כ־1.5 מ׳","note":"בעמידה; כמעט 2 מ׳ כשהוא מתמתח על קצות האצבעות"},{"label":"זנב","value":"65–120 ס״מ","note":"חזק מספיק כדי להישען עליו"},{"label":"משקל","value":"17–92 ק״ג","note":"הזכרים כבדים עד פי שניים"},{"label":"מהירות מרבית","value":"כ־56–60 קמ״ש","note":"בקפיצות"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","קנגורו, קואלות ווומבטים · Diprotodontia","קנגורו וולבי · Macropodidae","Osphranter rufus"]}},"tiger":{"id":"tiger","i":23,"latin":"Panthera tigris sondaica","group":"mammal","home":"rainforest","diet":"carn","active":"day and night","continents":["Asia"],"iucn":"CR","en":{"name":"Sumatran tiger","habitat_text":"Lowland, hill and mountain rainforest on Sumatra, from sea level up to 3,200 m","menu":"Wild pigs, sambar and muntjac deer, mouse-deer, Malayan tapirs, porcupines, macaques and large ground birds such as the great argus.","iucn_note":"Critically Endangered (Sumatran tiger). Tigers as a whole are Endangered. Main dangers: forest cleared for oil palm and acacia plantations, poaching for illegal trade, and loss of prey.","page_facts":["My stripes help me hide.","I swim across rivers.","I live in a rainforest.","I'm the smallest tiger living today."],"powers":[{"title":"Stripes that vanish in shadow","kid":"Its dark stripes break up its shape among shadows and tree trunks, so deer and pigs find it hard to spot.","teen":"Vertical stripes match the light-and-shade pattern of forest and tall grass, and every tiger's pattern is unique. Sumatran tigers have dark fur and broad stripes that break into spots near their ends.","part":"stripes"},{"title":"The longest fangs of any cat","kid":"Tigers have the longest fangs of any cat, up to about 7.6 cm, for gripping big prey like deer and wild pigs.","teen":"Tiger canines reach 6.4–7.6 cm, the longest in the cat family, set among 30 robust teeth. Sumatran tigers use them on sambar deer, muntjac, wild pigs and even tapirs.","part":"teeth"},{"title":"Hidden hooks","kid":"Its claws stay tucked inside its paws while it walks, then slide out to grab and hold prey.","teen":"Retractile claws, compact, curved and up to 10 cm long in tigers, stay sheathed while walking, which keeps the tips sharp, then extend to hold struggling prey.","part":"paws"}],"field_note":{"place":"","text":"Tigers once lived on the islands of Java and Bali too, but those island tigers died out in the 1900s. Sumatra's tigers are the last island tigers left on Earth."},"lab_note":"In 2014, Matthew Luskin and colleagues set camera traps in three Sumatran national parks. Tigers were 47% more common in untouched primary forest than in damaged forest.","myth":{"claim":"Tigers hate water.","verdict":"myth","why":"Tigers are powerful swimmers. They cross wide rivers and often lie in water to cool off on hot days."},"clues":["I am a big cat with an orange coat.","I have black stripes, and I am a strong swimmer.","I am the last tiger of the Indonesian islands, and I live only on Sumatra."],"compare":{"stat":"Weight","value":140,"unit":"kg","text":"up to 140 kg"},"stats":[{"label":"Length","value":"2.15–2.55 m","note":"nose to tail tip; males longer"},{"label":"Fangs","value":"up to 7.6 cm","note":"tigers have the longest fangs of any cat"},{"label":"Weight","value":"75–140 kg","note":"males heavier"},{"label":"Left in the wild","value":"a few hundred","note":"estimates range from about 200 to 900, all on Sumatra"}],"taxonomy":["Animals","Mammals · Mammalia","Carnivores · Carnivora","Cats · Felidae","Panthera tigris sondaica"]},"he":{"name":"טיגריס סומטרה","habitat_text":"יערות גשם בשפלה, בגבעות ובהרים של סומטרה, מגובה פני הים ועד 3,200 מ׳","menu":"חזירי בר, צבאי סמבר ומונטג'ק, צבאי־עכבר, טפירים מלאיים, דורבנים, מקוקים ועופות קרקע גדולים כמו הארגוס הגדול.","iucn_note":"בסכנת הכחדה חמורה (טיגריס סומטרה). הטיגריס כמין כולו בסכנת הכחדה. הסכנות העיקריות: בירוא יערות לטובת מטעי דקל שמן ושיטה, ציד לסחר בלתי חוקי, ואובדן חיות הטרף.","page_facts":["הפסים שלי עוזרים לי להסתתר.","אני חוצה נהרות בשחייה.","אני גר ביער גשם.","אני הטיגריס הקטן ביותר שחי היום."],"powers":[{"title":"פסים שנעלמים בצל","kid":"הפסים הכהים שלו מפרקים את צורת הגוף שלו בין הצללים וגזעי העצים, ולכן לצבאים ולחזירים קשה לזהות אותו.","teen":"פסים אנכיים תואמים את דפוס האור והצל של היער והעשב הגבוה, ודפוס הפסים של כל טיגריס הוא ייחודי. לטיגריסי סומטרה יש פרווה כהה ופסים רחבים שמתפרקים לכתמים לקראת קצותיהם.","part":"stripes"},{"title":"הניבים הארוכים ביותר מכל החתולים","kid":"לטיגריסים יש הניבים הארוכים ביותר מכל החתולים, עד כ־7.6 ס״מ, כדי לאחוז בטרף גדול כמו צבאים וחזירי בר.","teen":"הניבים של טיגריס מגיעים ל־6.4–7.6 ס״מ, הארוכים ביותר במשפחת החתוליים, בין 30 שיניים חזקות. טיגריסי סומטרה משתמשים בהם נגד צבאי סמבר, מונטג'קים, חזירי בר ואפילו טפירים.","part":"teeth"},{"title":"ווים נסתרים","kid":"הטפרים שלו נשארים מקופלים בתוך הכפות בזמן ההליכה, ואז נשלפים החוצה כדי לתפוס טרף ולהחזיק בו.","teen":"טפרים נסוגים, קומפקטיים ומעוקלים, באורך של עד 10 ס״מ אצל טיגריסים, נשארים מכוסים בזמן ההליכה, וכך הקצוות נשארים חדים. אחר כך הם נשלפים כדי להחזיק טרף שנאבק.","part":"paws"}],"field_note":{"place":"","text":"פעם חיו טיגריסים גם באיים ג'אווה ובאלי, אבל טיגריסי האיים האלה נכחדו במאה ה־20. הטיגריסים של סומטרה הם טיגריסי האיים האחרונים שנותרו על פני כדור הארץ."},"lab_note":"ב־2014 הציבו מתיו לסקין ועמיתיו מצלמות מלכודת בשלושה פארקים לאומיים בסומטרה. טיגריסים היו נפוצים יותר ב־47% ביער ראשוני שלא נפגע מאשר ביער פגוע.","myth":{"claim":"טיגריסים שונאים מים.","verdict":"myth","why":"טיגריסים הם שחיינים חזקים. הם חוצים נהרות רחבים, ולעיתים קרובות שוכבים במים כדי להתקרר בימים חמים."},"clues":["אני חתול גדול עם פרווה כתומה.","יש לי פסים שחורים, ואני שחיין חזק.","אני הטיגריס האחרון של איי אינדונזיה, ואני חי רק בסומטרה."],"compare":{"stat":"Weight","value":140,"unit":"kg","text":"עד 140 ק״ג"},"stats":[{"label":"אורך","value":"2.15–2.55 מ׳","note":"מהאף עד קצה הזנב; הזכרים ארוכים יותר"},{"label":"ניבים","value":"עד 7.6 ס״מ","note":"לטיגריסים יש הניבים הארוכים ביותר מכל החתולים"},{"label":"משקל","value":"75–140 ק״ג","note":"הזכרים כבדים יותר"},{"label":"נותרו בטבע","value":"כמה מאות","note":"ההערכות נעות בין כ־200 ל־900, כולם בסומטרה"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","טורפים · Carnivora","חתוליים · Felidae","Panthera tigris sondaica"]}},"monkey":{"id":"monkey","i":24,"latin":"Cebus imitator","group":"mammal","home":"rainforest","diet":"omni","active":"day","continents":["North America"],"iucn":"VU","en":{"name":"Panamanian white-faced capuchin","habitat_text":"Many kinds of forest in Central America: rainforest, dry forest, mangroves and mountain forest","menu":"Mostly fruit, such as figs, plus insects and caterpillars. It also eats flowers, seeds, eggs, frogs, lizards, crabs and small birds.","iucn_note":"Vulnerable (assessed 2020) and declining. Its forests are cleared for crops and cattle, and some capuchins are hunted or trapped.","page_facts":["I live in a big family group.","I eat fruit, bugs and eggs.","Some of us crack crabs with rocks.","I rub plants into my fur."],"powers":[{"title":"A helping tail","kid":"Its curly tail can wrap around a branch to steady it while it reaches for food. It is not strong enough to hang from.","teen":"The tail is prehensile: coiled around a branch, it supports the monkey while it feeds beneath that branch. But it is too weak to hang from by itself.","part":"tail"},{"title":"Stone hammers","kid":"On one island in Panama, these monkeys use stones as hammers to crack open crabs, snails and hard nuts.","teen":"On Jicarón Island in Coiba National Park, capuchins smash hermit crabs, sea snails and tropical almond seeds with a hammerstone on an anvil. Camera traps never caught adult females doing it.","part":"hands"},{"title":"A big brain","kid":"Its brain is bigger than the brain of the mantled howler, a larger monkey that shares its forests.","teen":"Its brain weighs about 79 g, more than the brains of several larger monkeys such as the mantled howler. Capuchins are known for varied foraging and tool use.","part":"head"}],"field_note":{"place":"","text":"Capuchins rub citrus fruit, leaves, ants and even millipedes into their fur, perhaps to keep pests away. In Costa Rica, one stole a visitor's insect repellent, bit the bottle open and rubbed it all over himself."},"lab_note":"In 2018, Brendan Barrett and colleagues reported camera-trap evidence from Coiba National Park, Panama: capuchins there habitually crack crabs, snails and nuts with stone hammers, the first stone-tool habit known in this group of capuchins.","myth":{"claim":"Monkeys mostly eat bananas.","verdict":"myth","why":"Wild white-faced capuchins eat many kinds of fruit, plus insects, eggs, lizards and even crabs. Bananas first grew wild in Asia and reached the Americas only about 500 years ago, and capuchins eat them only now and then."},"clues":["I live high in the trees of Central America.","My body is black, but my face, throat and chest are pale.","On an island in Panama, some of us crack crabs with stones."],"compare":{"stat":"Weight","value":3.9,"unit":"kg","text":"up to 3.9 kg"},"stats":[{"label":"Length","value":"34–45 cm","note":"head and body"},{"label":"Tail","value":"up to 55 cm","note":"longer than its body"},{"label":"Weight","value":"up to 3.9 kg","note":"males about 27% bigger"},{"label":"Lifespan","value":"over 54 years","note":"record age, in captivity"}],"taxonomy":["Animals","Mammals · Mammalia","Primates · Primates","Capuchin and squirrel monkeys · Cebidae","Cebus imitator"]},"he":{"name":"קוף קפוצ'ין","habitat_text":"סוגים רבים של יער במרכז אמריקה: יער גשם, יער יבש, מנגרובים ויער הררי","menu":"בעיקר פירות, כמו תאנים, וגם חרקים וזחלים. הוא אוכל גם פרחים, זרעים, ביצים, צפרדעים, לטאות, סרטנים וציפורים קטנות.","iucn_note":"פגיע (הוערך ב־2020), ומספרו יורד. היערות שלו מבוראים לטובת גידולים חקלאיים ובקר, וחלק מהקפוצ'ינים ניצודים או נלכדים.","page_facts":["אני גר בקבוצה משפחתית גדולה.","אני אוכל פירות, חרקים וביצים.","חלק מאיתנו מפצחים סרטנים באבנים.","אני משפשף צמחים לתוך הפרווה שלי."],"powers":[{"title":"זנב עוזר","kid":"הזנב המסולסל שלו יכול להיכרך סביב ענף ולייצב אותו בזמן שהוא מושיט יד לאוכל. הזנב לא חזק מספיק כדי להיתלות עליו.","teen":"הזנב הוא זנב אוחז: כשהוא כרוך סביב ענף, הוא תומך בקוף בזמן שהוא אוכל מתחת לאותו ענף. אבל הוא חלש מדי כדי שהקוף ייתלה עליו לבדו.","part":"tail"},{"title":"פטישי אבן","kid":"באי אחד בפנמה, הקופים האלה משתמשים באבנים כפטישים כדי לפצח סרטנים, חלזונות ואגוזים קשים.","teen":"באי חיקרון שבפארק הלאומי קויבה, קפוצ'ינים מרסקים סרטנים נזירים, חלזונות ים וזרעי שקד טרופי באבן־פטיש על גבי סדן. מצלמות המלכודת מעולם לא קלטו נקבות בוגרות עושות זאת.","part":"hands"},{"title":"מוח גדול","kid":"המוח שלו גדול יותר מהמוח של המיילל הגלימתי, קוף גדול יותר שחי באותם יערות.","teen":"המוח שלו שוקל כ־79 גרם, יותר מהמוח של כמה קופים גדולים ממנו, כמו המיילל הגלימתי. קפוצ'ינים ידועים בדרכים מגוונות להשגת מזון ובשימוש בכלים.","part":"head"}],"field_note":{"place":"","text":"קפוצ'ינים משפשפים לתוך הפרווה פירות הדר, עלים, נמלים ואפילו רבי־רגליים, אולי כדי להרחיק מזיקים. בקוסטה ריקה אחד מהם גנב ממבקר תכשיר נגד חרקים, פתח את הבקבוק בנשיכה ומרח אותו על כל הגוף."},"lab_note":"ב־2018 דיווחו ברנדן בארט ועמיתיו על עדויות ממצלמות מלכודת בפארק הלאומי קויבה שבפנמה: הקפוצ'ינים שם מפצחים באופן קבוע סרטנים, חלזונות ואגוזים בפטישי אבן. זהו הרגל השימוש בכלי אבן הראשון שידוע בקבוצת הקפוצ'ינים הזאת.","myth":{"claim":"קופים אוכלים בעיקר בננות.","verdict":"myth","why":"קפוצ'ינים לבני ראש בטבע אוכלים סוגים רבים של פירות, וגם חרקים, ביצים, לטאות ואפילו סרטנים. בננות גדלו בטבע לראשונה באסיה והגיעו ליבשת אמריקה רק לפני כ־500 שנה, וקפוצ'ינים אוכלים אותן רק מדי פעם."},"clues":["אני גר גבוה על העצים במרכז אמריקה.","הגוף שלי שחור, אבל הפנים, הגרון והחזה שלי בהירים.","באי בפנמה, חלק מאיתנו מפצחים סרטנים באבנים."],"compare":{"stat":"Weight","value":3.9,"unit":"kg","text":"עד 3.9 ק״ג"},"stats":[{"label":"אורך","value":"34–45 ס״מ","note":"ראש וגוף"},{"label":"זנב","value":"עד 55 ס״מ","note":"ארוך מהגוף שלו"},{"label":"משקל","value":"עד 3.9 ק״ג","note":"הזכרים גדולים בכ־27%"},{"label":"אורך חיים","value":"יותר מ־54 שנים","note":"שיא גיל, בשבי"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","פרימטים · Primates","קפוצ'ינים וקופי סנאי · Cebidae","Cebus imitator"]}},"parrot":{"id":"parrot","i":25,"latin":"Ara macao","group":"bird","home":"rainforest","diet":"herb","active":"day","continents":["North America","South America"],"iucn":"LC","en":{"name":"Scarlet macaw","habitat_text":"Tall rainforest, open woodland and river edges, from southern Mexico to the Amazon","menu":"Fruit, nuts, seeds, flowers and nectar. It often eats a fruit just to reach the seed inside, and it licks clay from riverbanks.","iucn_note":"Least Concern worldwide (2022), but numbers are falling. Habitat loss and capture for the pet trade have wiped it out in some areas; the US Fish and Wildlife Service lists the northern race as endangered.","page_facts":["I crack hard nuts with my beak.","I eat clay from riverbanks.","I stay with one mate for life.","I hold food with my feet."],"powers":[{"title":"Nutcracker beak","kid":"Its huge curved beak cracks hard nuts and seeds. The lower half presses against the upper half like a nutcracker.","teen":"The upper mandible is not fused to the skull, so it moves on its own; the lower mandible's sharp edge works against it like an anvil. Large macaws bite nearly as hard as big dogs.","part":"beak"},{"title":"Hand-like feet","kid":"Two toes point forward and two point back, so it can grip branches and lift food to its beak like a hand.","teen":"Zygodactyl feet, with two toes forward and two back, give a strong grip and let parrots handle food with great dexterity, much as we use our hands.","part":"feet"},{"title":"Beak as a third leg","kid":"When it climbs, it grabs the branch with its beak too, using its neck and beak like an extra leg.","teen":"Parrots are the only animals known to climb with true 'tripedalism': on vertical surfaces their neck and beak push with forces equal to or greater than a primate's arms.","part":"beak and neck"}],"field_note":{"place":"","text":"About 1,000 years ago, people in Chaco Canyon, New Mexico, kept scarlet macaws far north of their forests. DNA shows the birds came from one breeding colony, probably in the US Southwest or northern Mexico."},"lab_note":"At 18 clay licks in south-eastern Peru, Donald Brightsmith's team found that the soil parrots eat holds about four times more sodium than soil they leave alone. Sodium is scarce in rainforest food.","myth":{"claim":"Wild macaws talk like people.","verdict":"myth","why":"In the wild, scarlet macaws call with loud honks, squawks and screams that carry for kilometres. Only macaws living with people learn to copy human words."},"clues":["I live high in the rainforest treetops.","I crack nuts with my strong, curved beak.","I am a big red parrot with yellow and blue on my wings."],"compare":{"stat":"Length","value":89,"unit":"cm","text":"about 89 cm"},"stats":[{"label":"Length","value":"84–89 cm","note":"beak to tail tip, on average"},{"label":"Tail","value":"about half its length","note":"long and pointed"},{"label":"Weight","value":"about 1–1.2 kg","note":"adult"},{"label":"Lifespan","value":"40–50 years","note":"typical in captivity; some reach 75"}],"taxonomy":["Animals","Birds · Aves","Parrots · Psittaciformes","New World and African parrots · Psittacidae","Ara macao"]},"he":{"name":"תוכי ארה","habitat_text":"יער גשם גבוה, חורש פתוח וגדות נהרות, מדרום מקסיקו ועד האמזונס","menu":"פירות, אגוזים, זרעים, פרחים וצוף. הרבה פעמים הוא אוכל פרי רק כדי להגיע לזרע שבתוכו, והוא מלקק חימר מגדות נהרות.","iucn_note":"ללא חשש ברמה העולמית (2022), אבל מספרו יורד. אובדן בתי גידול ולכידה לסחר בחיות מחמד העלימו אותו מאזורים מסוימים; שירות הדגה וחיות הבר של ארה״ב מגדיר את התת־מין הצפוני כנמצא בסכנת הכחדה.","page_facts":["אני מפצח אגוזים קשים במקור.","אני אוכל חימר מגדות נהרות.","יש לי בת זוג אחת לכל החיים.","אני מחזיק אוכל ברגליים."],"powers":[{"title":"מקור מפצח אגוזים","kid":"המקור הענק והמעוקל שלו מפצח אגוזים וזרעים קשים. החלק התחתון לוחץ על החלק העליון, כמו מפצח אגוזים.","teen":"הלסת העליונה של המקור אינה מאוחה לגולגולת, ולכן היא זזה באופן עצמאי; השפה החדה של הלסת התחתונה פועלת מולה כמו סדן. תוכי ארה גדולים נושכים כמעט בכוח של כלבים גדולים.","part":"beak"},{"title":"רגליים כמו ידיים","kid":"שתי אצבעות מופנות קדימה ושתיים אחורה, ולכן הוא יכול לאחוז בענפים ולהרים אוכל אל המקור כמו ביד.","teen":"רגליים זיגודקטיליות, עם שתי אצבעות קדימה ושתיים אחורה, נותנות אחיזה חזקה ומאפשרות לתוכים לטפל במזון במיומנות רבה, בדומה לאופן שבו אנחנו משתמשים בידיים.","part":"feet"},{"title":"מקור כרגל שלישית","kid":"כשהוא מטפס, הוא תופס את הענף גם במקור, ומשתמש בצוואר ובמקור כמו ברגל נוספת.","teen":"תוכים הם בעלי החיים היחידים שידוע שהם מטפסים ב\"תלת־רגליות\" אמיתית: על משטחים אנכיים, הצוואר והמקור שלהם דוחפים בכוח השווה לכוח של זרועות פרימט, או גדול ממנו.","part":"beak and neck"}],"field_note":{"place":"","text":"לפני כ־1,000 שנה החזיקו אנשים בקניון צ'אקו שבניו מקסיקו תוכי ארה מהמין הזה, הרחק צפונה מהיערות שלהם. ה־DNA מראה שהציפורים הגיעו ממושבת רבייה אחת, כנראה בדרום־מערב ארה״ב או בצפון מקסיקו."},"lab_note":"ב־18 אתרי ליקוק חימר בדרום־מזרח פרו, הצוות של דונלד ברייטסמית' גילה שבאדמה שהתוכים אוכלים יש בערך פי ארבעה יותר נתרן מאשר באדמה שהם לא נוגעים בה. נתרן נדיר במזון של יער הגשם.","myth":{"claim":"תוכי ארה בטבע מדברים כמו בני אדם.","verdict":"myth","why":"בטבע, תוכי ארה מהמין הזה קוראים בצפירות, בצווחות ובצרחות רמות שנשמעות למרחק קילומטרים. רק תוכי ארה שחיים עם בני אדם לומדים לחקות מילים של בני אדם."},"clues":["אני גר גבוה בצמרות של יער הגשם.","אני מפצח אגוזים במקור החזק והמעוקל שלי.","אני תוכי גדול ואדום, עם צהוב וכחול בכנפיים."],"compare":{"stat":"Length","value":89,"unit":"cm","text":"כ־89 ס״מ"},"stats":[{"label":"אורך","value":"84–89 ס״מ","note":"מהמקור עד קצה הזנב, בממוצע"},{"label":"זנב","value":"כמחצית מאורכו","note":"ארוך ומחודד"},{"label":"משקל","value":"כ־1–1.2 ק״ג","note":"בוגר"},{"label":"אורך חיים","value":"40–50 שנים","note":"בדרך כלל בשבי; יש שמגיעים ל־75"}],"taxonomy":["בעלי חיים","עופות · Aves","תוכאים · Psittaciformes","תוכיים · Psittacidae","Ara macao"]}},"crocodile":{"id":"crocodile","i":26,"latin":"Crocodylus niloticus","group":"reptile","home":"savanna","diet":"carn","active":"day and night","continents":["Africa"],"iucn":"LC","en":{"name":"Nile crocodile","habitat_text":"Rivers, lakes, swamps and marshes across Africa south of the Sahara, the Nile valley and Madagascar","menu":"Mostly fish. Big adults also ambush antelope, zebras, wildebeest and birds at the water's edge. Babies start on insects, then frogs and small fish.","iucn_note":"Least Concern worldwide (assessed 2017), with a stable population. Hunted heavily in the mid-1900s, it recovered in many countries under protection. It vanished from Israel in the early 1900s.","page_facts":["I have up to 68 teeth.","My babies call to me from eggs.","I carry my babies in my mouth.","I open my mouth to cool off."],"powers":[{"title":"Hiding in plain sight","kid":"Its eyes, ears and nostrils sit on top of its head, so it can watch, listen and breathe while the rest stays underwater.","teen":"With eyes, ears and nostrils along the top of the skull, a crocodile can see, hear and breathe while almost completely submerged, then lunge at animals that come to drink.","part":"head"},{"title":"Super-sensitive jaws","kid":"Tiny bumps all over its jaws sense touch and vibration. Tests showed they are more sensitive than human fingertips.","teen":"A Nile crocodile has about 9,000 tiny sense organs in its skin, packed most densely on the jaws. Leitch and Catania (2012) found they respond to pressures fainter than our fingertips can feel.","part":"jaws"},{"title":"Teeth that come back","kid":"It has 64 to 68 cone-shaped teeth for gripping. When one breaks, a new tooth grows in to replace it.","teen":"Its 64–68 conical teeth grip and hold prey rather than chew it; chunks are torn off and swallowed. For most of its life, broken teeth are replaced.","part":"teeth"}],"field_note":{"place":"Israel","text":"Nile crocodiles lived in Nahal Taninim, the Crocodile Stream, until the early 1900s. The one called Israel's last, hunted there around 1912, stands in Tel Aviv University's Steinhardt Museum of Natural History."},"lab_note":"Amélie Vergne and Nicolas Mathevon (Jean Monnet University, France, 2008) showed that Nile crocodile babies call from inside their eggs. The calls tell brothers and sisters to hatch, and tell the mother to dig open the nest.","myth":{"claim":"Little birds clean crocodiles' teeth.","verdict":"myth","why":"A 1974 review of the evidence found only a few reports of sandpipers picking leeches off crocodiles and snapping at insects on them. A bird may grab a scrap now and then, but there is no good evidence of tooth cleaning."},"clues":["I lie as still as a log in rivers and lakes.","Only my eyes and nose show above the water.","I am named after Africa's longest river, and I once lived in Israel's Crocodile Stream."],"compare":{"stat":"Weight","value":750,"unit":"kg","text":"up to about 750 kg (big males)"},"stats":[{"label":"Length","value":"3.5–5 m","note":"grown males; females 2.2–3.8 m"},{"label":"Hatchling","value":"28–30 cm","note":"length when it hatches"},{"label":"Weight","value":"225–750 kg","note":"grown males; females 40–250 kg"},{"label":"Teeth","value":"64–68","note":"broken teeth are replaced"}],"taxonomy":["Animals","Reptiles · Reptilia","Crocodilians · Crocodilia","True crocodiles · Crocodylidae","Crocodylus niloticus"]},"he":{"name":"תנין היאור","habitat_text":"נהרות, אגמים, ביצות ואזורי ביצה ברחבי אפריקה שמדרום לסהרה, בעמק הנילוס ובמדגסקר","menu":"בעיקר דגים. בוגרים גדולים גם אורבים לאנטילופות, לזברות, לגנו ולציפורים על שפת המים. התנינונים מתחילים בחרקים, ואחר כך עוברים לצפרדעים ולדגים קטנים.","iucn_note":"ללא חשש ברמה העולמית (הוערך ב־2017), עם אוכלוסייה יציבה. באמצע המאה ה־20 ניצוד בכמויות גדולות, ובמדינות רבות התאושש בזכות הגנה. מישראל הוא נעלם בתחילת המאה ה־20.","page_facts":["יש לי עד 68 שיניים.","התינוקות שלי קוראים לי מתוך הביצים.","אני נושא את התינוקות שלי בפה.","אני פותח את הפה כדי להתקרר."],"powers":[{"title":"מסתתר מול העיניים","kid":"העיניים, האוזניים והנחיריים שלו נמצאים בחלק העליון של הראש, ולכן הוא יכול לראות, לשמוע ולנשום בזמן ששאר הגוף נשאר מתחת למים.","teen":"בזכות עיניים, אוזניים ונחיריים לאורך החלק העליון של הגולגולת, תנין יכול לראות, לשמוע ולנשום כשהוא שקוע במים כמעט לגמרי, ואז לזנק על בעלי חיים שבאים לשתות.","part":"head"},{"title":"לסתות רגישות במיוחד","kid":"בליטות זעירות על כל הלסתות שלו חשות מגע ורעידות. ניסויים הראו שהן רגישות יותר מקצות האצבעות של בני אדם.","teen":"לתנין היאור יש כ־9,000 איברי חישה זעירים בעור, והם הכי צפופים על הלסתות. לייץ' וקטניה (2012) מצאו שהם מגיבים ללחצים חלשים יותר ממה שקצות האצבעות שלנו יכולים להרגיש.","part":"jaws"},{"title":"שיניים שחוזרות","kid":"יש לו 64 עד 68 שיניים בצורת חרוט, שמיועדות לאחיזה. כששן נשברת, צומחת שן חדשה במקומה.","teen":"השיניים החרוטיות שלו, 64–68 במספר, אוחזות בטרף ומחזיקות בו במקום ללעוס אותו; התנין קורע ממנו נתחים ובולע אותם. במשך רוב חייו, שיניים שנשברו מוחלפות.","part":"teeth"}],"field_note":{"place":"Israel","text":"תניני היאור חיו בנחל תנינים עד תחילת המאה ה־20. התנין שנקרא האחרון בישראל, שניצוד שם בסביבות 1912, מוצג במוזיאון שטיינהרדט לטבע של אוניברסיטת תל אביב."},"lab_note":"אמלי ורן וניקולא מתבון (אוניברסיטת ז'אן מונה, צרפת, 2008) הראו שתינוקות של תנין היאור קוראים מתוך הביצים. הקריאות אומרות לאחים ולאחיות לבקוע, ולאמא לחפור ולפתוח את הקן.","myth":{"claim":"ציפורים קטנות מנקות לתנינים את השיניים.","verdict":"myth","why":"סקירה של העדויות מ־1974 מצאה רק כמה דיווחים על ביצניות שמלקטות עלוקות מתנינים וחוטפות חרקים שעליהם. ציפור עשויה לחטוף שארית מזון מדי פעם, אבל אין עדות טובה לניקוי שיניים."},"clues":["אני שוכב דומם כמו בול עץ בנהרות ובאגמים.","רק העיניים והאף שלי מציצים מעל המים.","קוראים לי על שם הנהר הארוך ביותר באפריקה, ופעם חייתי בנחל תנינים בישראל."],"compare":{"stat":"Weight","value":750,"unit":"kg","text":"עד כ־750 ק״ג (זכרים גדולים)"},"stats":[{"label":"אורך","value":"3.5–5 מ׳","note":"זכרים בוגרים; נקבות 2.2–3.8 מ׳"},{"label":"בבקיעה","value":"28–30 ס״מ","note":"האורך כשהוא בוקע מהביצה"},{"label":"משקל","value":"225–750 ק״ג","note":"זכרים בוגרים; נקבות 40–250 ק״ג"},{"label":"שיניים","value":"64–68","note":"שיניים שנשברו מוחלפות"}],"taxonomy":["בעלי חיים","זוחלים · Reptilia","תנינאים · Crocodilia","תניניים · Crocodylidae","Crocodylus niloticus"]}},"rabbit":{"id":"rabbit","i":27,"latin":"Oryctolagus cuniculus","group":"mammal","home":"farm","diet":"herb","active":"dawn and dusk","continents":["Europe"],"iucn":"EN","en":{"name":"European rabbit","habitat_text":"Grassland, scrub and farm fields with soft, sandy soil for burrows; tame rabbits live on farms and in homes","menu":"Grasses and leaves, plus clover, buds, roots, bark and farm crops. It swallows some of its own soft droppings to digest its food a second time.","iucn_note":"Endangered worldwide (assessed 2018): wild rabbits in Spain, Portugal and France have declined from disease, hunting and habitat loss. A newer Europe-only assessment (2023) lists it Near Threatened. Tame and introduced rabbits are common.","page_facts":["I live in tunnels called a warren.","I thump my feet to warn others.","My teeth never stop growing.","My babies are born blind."],"powers":[{"title":"Teeth that keep growing","kid":"Its teeth grow all its life. Chewing tough grass and leaves all day wears them down and keeps them from getting too long.","teen":"Its teeth grow continuously throughout life, so a rabbit must keep grinding them down by chewing tough, high-fibre grass and leaves.","part":"teeth"},{"title":"Danger drum","kid":"When it senses danger, it thumps the ground hard with its back feet to warn other rabbits.","teen":"Rabbits thump the ground with their hind feet to signal a threat, such as a predator, and also when they are stressed.","part":"back feet"},{"title":"Eating it twice","kid":"It eats some of its own soft droppings! This lets its gut digest the grass a second time and get more goodness from it.","teen":"In caecotrophy, partly digested food is formed into soft, protein-rich pellets in the hindgut. The rabbit swallows them whole and digests them again; only the leftovers come out as hard pellets.","part":"belly"}],"field_note":{"place":"","text":"In 1859 a farmer in Australia let some wild rabbits loose for hunting. They spread across southern Australia and became a major pest, while back home in Spain, Portugal and France they are now Endangered."},"lab_note":"In 2018, Evan Irving-Pease, Greger Larson and colleagues used history, archaeology and genetics to show that French monks did not tame rabbits around AD 600, as often claimed. Taming rabbits was a slow, gradual process.","myth":{"claim":"Rabbits should eat lots of carrots.","verdict":"myth","why":"Wild rabbits mostly eat grass and leaves, not roots like carrots. Carrots are high in sugar, so a pet rabbit should get only a small piece as a treat. Hay and grass should be most of its food."},"clues":["I nibble grass in fields at dawn and dusk.","I live underground in a maze of tunnels.","All the world's pet rabbits come from my wild kind."],"compare":{"stat":"Weight","value":3,"unit":"kg","text":"up to 3 kg"},"stats":[{"label":"Length","value":"36–50 cm","note":"head and body"},{"label":"Ears","value":"7–8 cm","note":"no black tips, unlike a hare's"},{"label":"Weight","value":"1.5–3 kg","note":"wild adults"},{"label":"Pregnancy","value":"about 30 days","note":"several litters a year"}],"taxonomy":["Animals","Mammals · Mammalia","Rabbits, hares and pikas · Lagomorpha","Rabbits and hares · Leporidae","Oryctolagus cuniculus"]},"he":{"name":"ארנבון","habitat_text":"שטחי עשב, שיחים ושדות חקלאיים עם אדמה רכה וחולית לחפירת מחילות; ארנבונים מבויתים חיים בחוות ובבתים","menu":"עשבים ועלים, וגם תלתן, ניצנים, שורשים, קליפת עצים וגידולים חקלאיים. הוא בולע חלק מהגללים הרכים של עצמו כדי לעכל את המזון פעם שנייה.","iucn_note":"בסכנת הכחדה ברמה העולמית (הערכה משנת 2018): מספר הארנבונים הבריים בספרד, בפורטוגל ובצרפת ירד בגלל מחלות, ציד ואובדן בתי גידול. הערכה חדשה יותר, לאירופה בלבד (2023), מגדירה אותו קרוב לסיכון. ארנבונים מבויתים וארנבונים שהובאו לארצות חדשות נפוצים.","page_facts":["אני גר במחילות שנקראות מאורה.","אני רוקע ברגליים כדי להזהיר אחרים.","השיניים שלי לא מפסיקות לגדול.","הגורים שלי נולדים עיוורים."],"powers":[{"title":"שיניים שממשיכות לגדול","kid":"השיניים שלו גדלות כל החיים. לעיסה של עשב קשה ועלים כל היום שוחקת אותן ושומרת שלא יהיו ארוכות מדי.","teen":"השיניים שלו גדלות ללא הפסקה לאורך כל החיים, ולכן ארנבון חייב לשחוק אותן כל הזמן בלעיסת עשב ועלים קשים ועשירים בסיבים.","part":"teeth"},{"title":"תוף אזהרה","kid":"כשהוא מרגיש סכנה, הוא רוקע חזק באדמה ברגליים האחוריות כדי להזהיר ארנבונים אחרים.","teen":"ארנבונים רוקעים באדמה ברגליים האחוריות כדי לאותת על איום, למשל טורף, וגם כשהם לחוצים.","part":"back feet"},{"title":"לאכול פעמיים","kid":"הוא אוכל חלק מהגללים הרכים של עצמו! כך המעיים שלו מעכלים את העשב פעם שנייה ומפיקים ממנו עוד חומרים מזינים.","teen":"בתהליך שנקרא צקוטרופיה, מזון שעוכל בחלקו הופך במעי האחורי לגללים רכים ועשירים בחלבון. הארנבון בולע אותם שלמים ומעכל אותם שוב; רק השאריות יוצאות כגללים קשים.","part":"belly"}],"field_note":{"place":"","text":"בשנת 1859 חוואי באוסטרליה שחרר כמה ארנבונים בריים כדי לצוד אותם. הם התפשטו בכל דרום אוסטרליה והפכו למזיק גדול, ואילו בבית, בספרד, בפורטוגל ובצרפת, הם היום בסכנת הכחדה."},"lab_note":"בשנת 2018 הראו אוון אירווינג־פיס, גרגר לרסון ועמיתיהם, בעזרת היסטוריה, ארכאולוגיה וגנטיקה, שנזירים צרפתים לא בייתו ארנבונים בסביבות שנת 600 לספירה, כפי שנטען לעיתים קרובות. ביות הארנבונים היה תהליך איטי והדרגתי.","myth":{"claim":"ארנבונים צריכים לאכול הרבה גזר.","verdict":"myth","why":"ארנבונים בטבע אוכלים בעיקר עשב ועלים, לא שורשים כמו גזר. בגזר יש הרבה סוכר, ולכן ארנבון מחמד צריך לקבל רק חתיכה קטנה כפינוק. רוב המזון שלו צריך להיות חציר ועשב."},"clues":["אני מכרסם עשב בשדות עם שחר ולפנות ערב.","אני גר מתחת לאדמה, במבוך של מחילות.","כל ארנבוני המחמד בעולם הם צאצאים של המין הבר שלי."],"compare":{"stat":"Weight","value":3,"unit":"kg","text":"עד 3 ק״ג"},"stats":[{"label":"אורך","value":"36–50 ס״מ","note":"ראש וגוף"},{"label":"אוזניים","value":"7–8 ס״מ","note":"בלי קצוות שחורים, בשונה מאוזני הארנבת"},{"label":"משקל","value":"1.5–3 ק״ג","note":"בוגרים בטבע"},{"label":"היריון","value":"בערך 30 יום","note":"כמה המלטות בשנה"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","ארנבאים · Lagomorpha","ארנביים · Leporidae","Oryctolagus cuniculus"]}},"bee":{"id":"bee","i":28,"latin":"Apis mellifera","group":"insect","home":"farm","diet":"herb","active":"day","continents":["Europe","Africa","Asia"],"iucn":"DD","en":{"name":"Western honey bee","habitat_text":"Anywhere with flowers: meadows, orchards, farms and gardens. Wild colonies nest in hollows such as tree holes; many live in beekeepers' hives","menu":"Nectar and pollen from flowers. Nectar is turned into honey in the hive; pollen becomes 'bee bread', the protein food for the young.","iucn_note":"No worldwide assessment. IUCN's 2025 Europe assessment lists it Data Deficient, with numbers decreasing. People keep it on every continent except Antarctica; the Varroa mite and diseases are major threats.","page_facts":["I dance to show where flowers are.","I carry pollen on my back legs.","My wings beat 230 times a second.","I make wax to build our home."],"powers":[{"title":"Pollen baskets","kid":"Each back leg has a pollen basket. The bee packs pollen into it and flies home carrying two little loads.","teen":"The corbicula, or pollen basket, on each hind leg holds packed pollen. In the hive the pollen ferments into 'bee bread', the colony's protein source for raising young.","part":"back legs"},{"title":"Buzzing wings","kid":"Its wings flap about 230 times every second, in short quick strokes that keep it hovering over flowers.","teen":"High-speed filming at Caltech showed hovering honey bees use short strokes of about 90 degrees at about 230 beats a second, and widen the stroke when they need more lift.","part":"wings"},{"title":"Wax makers","kid":"Glands under its belly make tiny flakes of wax, which the bees shape into honeycomb cells for honey and young.","teen":"Workers secrete wax from eight glands on the underside of abdominal segments 4 to 7. Gland size depends on the worker's age, and the glands shrink after many foraging flights.","part":"abdomen"}],"field_note":{"place":"Israel","text":"At Tel Rehov in Israel's Jordan Valley, archaeologists found clay beehives about 3,000 years old, the oldest yet discovered. Tests of the bees inside showed a kind now living in parts of Turkey."},"lab_note":"Karl von Frisch decoded the honey bee's waggle dance: the angle of the waggle run shows the direction of food compared with the sun, and how long it lasts shows the distance. He shared the 1973 Nobel Prize.","myth":{"claim":"A bee always dies after it stings.","verdict":"myth","why":"A worker honey bee's sting is barbed. In the skin of people and other mammals it usually catches and tears away, and the bee dies. But the barbs do not always catch. Bees of other kinds have stings without barbs."},"clues":["I live with thousands of sisters in one home.","I carry pollen home in baskets on my back legs.","I make honey and dance to tell my sisters where flowers are."],"compare":{"stat":"Length","value":1.5,"unit":"cm","text":"up to 1.5 cm"},"stats":[{"label":"Length","value":"10–15 mm","note":"worker bee"},{"label":"Weight","value":"about 0.1 g","note":"about 100 mg"},{"label":"Wing beats","value":"about 230 a second","note":"when hovering"},{"label":"Lifespan","value":"2–6 weeks","note":"summer workers; autumn-born ones live months"}],"taxonomy":["Animals","Insects · Insecta","Bees, wasps and ants · Hymenoptera","Honey bees, bumblebees and relatives · Apidae","Apis mellifera"]},"he":{"name":"דבורת הדבש","habitat_text":"בכל מקום שיש בו פרחים: שטחי אחו, מטעים, חוות וגינות. מושבות בר מקננות בחללים, כמו חורים בעצים; רבות חיות בכוורות של כוורנים","menu":"צוף ואבקה מפרחים. בכוורת הצוף הופך לדבש; האבקה הופכת למה שנקרא לחם דבורים: מזון החלבון של הצאצאים.","iucn_note":"אין הערכה עולמית. בהערכה של IUCN לאירופה משנת 2025 היא מוגדרת חסרת מידע, ומספרה הולך ויורד. בני אדם מגדלים אותה בכל היבשות חוץ מאנטארקטיקה; קרדית הווארואה ומחלות הן איומים גדולים.","page_facts":["אני רוקדת כדי להראות איפה יש פרחים.","אני נושאת אבקה על הרגליים האחוריות.","אני מנפנפת בכנפיים 230 פעמים בשנייה.","אני מכינה שעווה לבניית הבית שלנו."],"powers":[{"title":"סלסלות אבקה","kid":"בכל רגל אחורית יש לה סלסלת אבקה. הדבורה דוחסת לתוכה אבקה וטסה הביתה עם שני מטענים קטנים.","teen":"הקורביקולה, או סלסלת האבקה, שעל כל רגל אחורית מחזיקה אבקה דחוסה. בכוורת האבקה תוססת והופכת למה שנקרא לחם דבורים, מקור החלבון של המושבה לגידול הצאצאים.","part":"back legs"},{"title":"כנפיים מזמזמות","kid":"הכנפיים שלה נעות בערך 230 פעמים בכל שנייה, בתנועות קצרות ומהירות שמחזיקות אותה מרחפת מעל הפרחים.","teen":"צילום מהיר בקאלטק הראה שדבורי דבש מרחפות משתמשות במשקים קצרים של כ־90 מעלות, בקצב של כ־230 משקים בשנייה, ומרחיבות את המשק כשהן צריכות יותר עילוי.","part":"wings"},{"title":"יצרניות שעווה","kid":"בלוטות מתחת לבטן שלה מייצרות פתיתים זעירים של שעווה, והדבורים מעצבות מהם תאים של חלת דבש בשביל הדבש והצאצאים.","teen":"הפועלות מפרישות שעווה משמונה בלוטות בצד התחתון של מקטעי הבטן 4 עד 7. גודל הבלוטות תלוי בגיל הפועלת, והן מתכווצות אחרי טיסות איסוף רבות.","part":"abdomen"}],"field_note":{"place":"Israel","text":"בתל רחוב, בבקעת הירדן בישראל, מצאו ארכאולוגים כוורות חרס בנות כ־3,000 שנה, העתיקות ביותר שהתגלו עד היום. בדיקות של הדבורים שבתוכן הראו שהן מזן שחי היום באזורים של טורקיה."},"lab_note":"קרל פון פריש פענח את ריקוד הכשכוש של דבורת הדבש: הזווית של ריצת הכשכוש מראה את הכיוון אל המזון ביחס לשמש, ומשך הריצה מראה את המרחק. הוא היה שותף לפרס נובל של שנת 1973.","myth":{"claim":"דבורה תמיד מתה אחרי שהיא עוקצת.","verdict":"myth","why":"לעוקץ של דבורת דבש פועלת יש זיזים. בעור של בני אדם ושל יונקים אחרים הוא בדרך כלל נתפס ונתלש, והדבורה מתה. אבל הזיזים לא תמיד נתפסים. לדבורים ממינים אחרים יש עוקץ בלי זיזים."},"clues":["אני גרה עם אלפי אחיות בבית אחד.","אני מביאה אבקה הביתה בסלסלות שעל הרגליים האחוריות שלי.","אני מכינה דבש ורוקדת כדי לספר לאחיות שלי איפה יש פרחים."],"compare":{"stat":"Length","value":1.5,"unit":"cm","text":"עד 1.5 ס״מ"},"stats":[{"label":"אורך","value":"10–15 מ״מ","note":"דבורה פועלת"},{"label":"משקל","value":"בערך 0.1 גרם","note":"בערך 100 מיליגרם"},{"label":"משקי כנפיים","value":"בערך 230 בשנייה","note":"בזמן ריחוף"},{"label":"אורך חיים","value":"2–6 שבועות","note":"פועלות של הקיץ; פועלות שנולדות בסתיו חיות חודשים"}],"taxonomy":["בעלי חיים","חרקים · Insecta","דבוראים · Hymenoptera","דבוריים · Apidae","Apis mellifera"]}},"butterfly":{"id":"butterfly","i":29,"latin":"Papilio machaon","group":"insect","home":"farm","diet":"herb","active":"day","continents":["Europe","Asia","Africa","North America"],"iucn":"LC","en":{"name":"Old World swallowtail","habitat_text":"Sunny open places: meadows, hillsides, fields, fens and gardens, wherever carrot-family plants grow","menu":"Adults sip nectar from flowers. Caterpillars eat the leaves of carrot-family plants such as wild carrot, fennel and dill; in Israel also rue and young citrus leaves.","iucn_note":"Not assessed worldwide. Least Concern in IUCN's Europe (2025) and Mediterranean (2014) assessments. In Britain a rare local race lives only in Norfolk's fens and is protected by law.","page_facts":["I sip nectar from flowers.","I taste with my feet.","My wings have tails, like swallows.","When tiny, I looked like bird poop."],"powers":[{"title":"Tasting feet","kid":"It tastes with its feet. A mother lands on a leaf and tastes it to check that her caterpillars will be able to eat it.","teen":"Taste receptors on the tarsi work on contact. An egg-laying female uses them to test whether a leaf, such as fennel or wild carrot, can feed her caterpillars before she lays.","part":"feet"},{"title":"Painted with scales","kid":"Its wings are covered in tiny scales. The scales give the wings their yellow, black and blue colours.","teen":"Butterfly wings are covered in scales that carry their colour. Some colours come from pigments in the scales; in many butterflies, blues come from microscopic structures that scatter light.","part":"wings"},{"title":"Smelling antennae","kid":"The little clubs at the tips of its antennae are full of sensors that pick up smells.","teen":"Its antennae end in clubs, unlike the thread-like or feathery antennae of many moths. Sensory receptors concentrated in the tips detect odours.","part":"antennae"}],"field_note":{"place":"Israel","text":"One of Israel's largest and commonest butterflies, it flies from March to November everywhere except the harshest desert. Its caterpillars eat rue, fennel, carrot and young citrus leaves, and there are about five generations a year."},"lab_note":"Butterfly Conservation's counts in Britain show swallowtail numbers rose about 51% between 1976 and 2019, but the area where they live shrank by about 27% between 1996 and 2019. There they survive only in Norfolk's fens.","myth":{"claim":"Caterpillars and butterflies are two different animals.","verdict":"myth","why":"They are the same animal at different stages. The caterpillar eats and grows, then forms a chrysalis, and inside it the body is rebuilt into the winged butterfly."},"clues":["I hatch from an egg as a hungry caterpillar.","As a young caterpillar, I look like a bird dropping.","I am a big yellow-and-black butterfly with tails on my back wings, like a swallow."],"compare":{"stat":"Wingspan","value":9.3,"unit":"cm","text":"up to 9.3 cm"},"stats":[{"label":"Wingspan","value":"6.5–9.3 cm","note":"tip to tip; females larger"},{"label":"Caterpillar","value":"about 4.5 cm","note":"fully grown"},{"label":"Chrysalis","value":"3–3.5 cm","note":"the pupa"},{"label":"Generations","value":"1–5 a year","note":"about 5 in Israel, 1 in parts of the north"}],"taxonomy":["Animals","Insects · Insecta","Butterflies and moths · Lepidoptera","Swallowtails · Papilionidae","Papilio machaon"]},"he":{"name":"פרפר זנב־סנונית","habitat_text":"מקומות פתוחים ושטופי שמש: שטחי אחו, מדרונות, שדות, ביצות וגינות, בכל מקום שגדלים בו צמחים ממשפחת הגזר","menu":"הפרפרים הבוגרים שותים צוף מפרחים. הזחלים אוכלים עלים של צמחים ממשפחת הגזר, כמו גזר בר, שומר ושמיר; בישראל גם פיגם ועלים צעירים של הדרים.","iucn_note":"לא הוערך ברמה העולמית. בהערכות של IUCN לאירופה (2025) ולאגן הים התיכון (2014) הוא מוגדר ללא חשש. בבריטניה חי זן מקומי נדיר רק בביצות של נורפוק, והוא מוגן בחוק.","page_facts":["אני שותה צוף מפרחים.","אני טועם ברגליים.","לכנפיים שלי יש זנבות, כמו לסנוניות.","כשהייתי קטן, נראיתי כמו קקי של ציפור."],"powers":[{"title":"רגליים טועמות","kid":"הוא טועם ברגליים. אמא נוחתת על עלה וטועמת אותו כדי לבדוק שהזחלים שלה יוכלו לאכול אותו.","teen":"קולטני טעם בכפות הרגליים פועלים במגע. נקבה שמטילה ביצים משתמשת בהם כדי לבדוק אם עלה, למשל של שומר או גזר בר, יכול להזין את הזחלים שלה, לפני שהיא מטילה.","part":"feet"},{"title":"צבוע בקשקשים","kid":"הכנפיים שלו מכוסות בקשקשים זעירים. הקשקשים נותנים לכנפיים את הצבעים הצהוב, השחור והכחול.","teen":"כנפי הפרפרים מכוסות בקשקשים שנושאים את הצבע שלהן. חלק מהצבעים באים מפיגמנטים שבקשקשים; אצל פרפרים רבים, הגוונים הכחולים באים ממבנים מיקרוסקופיים שמפזרים אור.","part":"wings"},{"title":"מחושים שמריחים","kid":"הקצוות המעובים של המחושים שלו מלאים בחיישנים שקולטים ריחות.","teen":"המחושים שלו מסתיימים בעיבוי דמוי אלה, בשונה מהמחושים דמויי החוט או הנוצה של עשים רבים. קולטני חישה שמרוכזים בקצוות מזהים ריחות.","part":"antennae"}],"field_note":{"place":"Israel","text":"זה אחד הפרפרים הגדולים והנפוצים ביותר בישראל. הוא עף ממרץ עד נובמבר בכל מקום חוץ מהמדבר הקשה ביותר. הזחלים שלו אוכלים פיגם, שומר, גזר ועלים צעירים של הדרים, ויש בערך חמישה דורות בשנה."},"lab_note":"ספירות של ארגון Butterfly Conservation בבריטניה מראות שמספר פרפרי הזנב־סנונית עלה בכ־51% בין 1976 ל־2019, אבל השטח שבו הם חיים הצטמצם בכ־27% בין 1996 ל־2019. שם הם שורדים רק בביצות של נורפוק.","myth":{"claim":"זחלים ופרפרים הם שני בעלי חיים שונים.","verdict":"myth","why":"זה אותו בעל חיים בשלבים שונים. הזחל אוכל וגדל, אחר כך הופך לגולם, ובתוך הגולם הגוף נבנה מחדש לפרפר עם כנפיים."},"clues":["אני בוקע מביצה כזחל רעב.","כשאני זחל צעיר, אני נראה כמו לשלשת של ציפור.","אני פרפר גדול, צהוב ושחור, עם זנבות בכנפיים האחוריות, כמו סנונית."],"compare":{"stat":"Wingspan","value":9.3,"unit":"cm","text":"עד 9.3 ס״מ"},"stats":[{"label":"מוטת כנפיים","value":"6.5–9.3 ס״מ","note":"מקצה לקצה; הנקבות גדולות יותר"},{"label":"זחל","value":"בערך 4.5 ס״מ","note":"בסוף הגדילה"},{"label":"גולם","value":"3–3.5 ס״מ","note":"שלב הגולם"},{"label":"דורות","value":"1–5 בשנה","note":"בערך 5 בישראל, 1 בחלק מאזורי הצפון"}],"taxonomy":["בעלי חיים","חרקים · Insecta","פרפרים · Lepidoptera","זנב־סנוניתיים · Papilionidae","Papilio machaon"]}},"bat":{"id":"bat","i":30,"latin":"Pipistrellus kuhlii","group":"mammal","home":"farm","diet":"carn","active":"night","continents":["Europe","Africa","Asia"],"iucn":"LC","en":{"name":"Kuhl's pipistrelle","habitat_text":"Towns, villages and farmland; also woodland edges, oases and deserts","menu":"Small flying insects such as flies and midges, moths, beetles and tiny wasps, caught in the air, often around street lamps.","iucn_note":"Least Concern. Common and adaptable; its range has been spreading as it settles in towns and roosts in buildings.","page_facts":["I hunt bugs near street lamps.","I sleep in cracks in buildings.","I find bugs by listening to echoes.","My babies are often twins."],"powers":[{"title":"Seeing with sound","kid":"It calls out sounds too high for us to hear, then listens for the echoes bouncing back from insects.","teen":"It emits frequency-modulated calls peaking around 34–41 kHz, above human hearing, through its open mouth, and locates insects from the returning echoes.","part":"ears"},{"title":"A built-in insect net","kid":"The skin between its legs and tail works like a little net. It can scoop a flying insect into it.","teen":"It can catch insects in flight by scooping them up with a wing or with the tail membrane (uropatagium) stretched between its hind legs and tail.","part":"tail membrane"},{"title":"Two-speed flyer","kid":"It flies fast when travelling between its roost and hunting spots, then slows down to chase insects.","teen":"Measured commuting flight is about 9.3 m/s (about 33 km/h), nearly twice its foraging speed of about 4.7 m/s while it hunts insects in the air.","part":"wings"}],"field_note":{"place":"Israel","text":"It is Israel's most common insect-eating bat. As people built settlements in the Negev desert, it spread in from the greener north. It drinks by swooping low over open water."},"lab_note":"At Tel Aviv University, Yossi Yovel's team tracked Kuhl's pipistrelles landing on a target in the lab. When aiming, a bat opened its mouth about 3.6 mm wider, making its sound beam about half as wide.","myth":{"claim":"Bats are blind.","verdict":"myth","why":"Bats can see: the US Geological Survey says their small eyes are very sensitive. At night this bat finds insects mainly by echolocation."},"clues":["I fly in the dark.","By day I sleep in cracks in buildings.","I am the little bat most often seen catching insects around street lamps in Israel."],"compare":{"stat":"Wingspan","value":23,"unit":"cm","text":"up to 23 cm"},"stats":[{"label":"Body length","value":"4–5.5 cm","note":"head and body, plus a 3–4.5 cm tail"},{"label":"Wingspan","value":"21–23 cm","note":"tip to tip"},{"label":"Weight","value":"5–10 g","note":"adult"},{"label":"Call pitch","value":"34–41 kHz","note":"too high for people to hear"}],"taxonomy":["Animals","Mammals · Mammalia","Bats · Chiroptera","Vesper bats · Vespertilionidae","Pipistrellus kuhlii"]},"he":{"name":"עטלפון","habitat_text":"ערים, כפרים ושטחים חקלאיים; גם שולי חורש, נאות מדבר ומדבריות","menu":"חרקים מעופפים קטנים כמו זבובים ויבחושים, עשים, חיפושיות וצרעות זעירות, שהוא תופס באוויר, לעיתים קרובות ליד פנסי רחוב.","iucn_note":"ללא חשש. הוא נפוץ ומסתגל בקלות; תחום התפוצה שלו מתרחב ככל שהוא מתיישב בערים ולן בבניינים.","page_facts":["אני צד חרקים ליד פנסי רחוב.","אני ישן בסדקים של בניינים.","אני מוצא חרקים כשאני מקשיב להדים.","הרבה פעמים נולדים לי תאומים."],"powers":[{"title":"לראות בעזרת קול","kid":"הוא משמיע קולות גבוהים מדי בשביל האוזניים שלנו, ואז מקשיב להדים שחוזרים מהחרקים.","teen":"הוא משמיע דרך הפה הפתוח קריאות שהתדר שלהן משתנה, עם שיא סביב 34–41 קילוהרץ, מעל טווח השמיעה של האדם, ומאתר חרקים לפי ההדים שחוזרים.","part":"ears"},{"title":"רשת חרקים מובנית","kid":"העור שבין הרגליים לזנב שלו עובד כמו רשת קטנה. הוא יכול לגרוף לתוכו חרק מעופף.","teen":"הוא יכול לתפוס חרקים במעופם, כשהוא גורף אותם בכנף או בקרום הזנב (uropatagium) שמתוח בין הרגליים האחוריות לזנב.","part":"tail membrane"},{"title":"מעופף בשתי מהירויות","kid":"הוא עף מהר כשהוא בדרך ממקום המנוחה שלו אל מקומות הציד, ואז מאט כדי לרדוף אחרי חרקים.","teen":"המהירות שנמדדה בטיסות המעבר שלו היא כ־9.3 מ׳ לשנייה (כ־33 קמ״ש), כמעט פי שניים ממהירות החיפוש שלו, כ־4.7 מ׳ לשנייה, בזמן שהוא צד חרקים באוויר.","part":"wings"}],"field_note":{"place":"Israel","text":"זה העטלף אוכל החרקים הנפוץ ביותר בישראל. כשבני אדם בנו יישובים במדבר הנגב, הוא התפשט לשם מהצפון הירוק יותר. הוא שותה כשהוא צולל נמוך מעל מים פתוחים."},"lab_note":"באוניברסיטת תל אביב עקב הצוות של יוסי יובל אחרי עטלפונים לבני־שוליים שנחתו על מטרה במעבדה. כשעטלף כיוון אל המטרה, הוא פתח את הפה בכ־3.6 מ״מ יותר, וכך רוחב אלומת הקול שלו קטן בערך בחצי.","myth":{"claim":"עטלפים עיוורים.","verdict":"myth","why":"עטלפים רואים: לפי הסקר הגאולוגי של ארצות הברית, העיניים הקטנות שלהם רגישות מאוד. בלילה העטלף הזה מוצא חרקים בעיקר באקולוקציה, איתור בעזרת הדים."},"clues":["אני עף בחושך.","ביום אני ישן בסדקים של בניינים.","אני העטלף הקטן שרואים הכי הרבה צד חרקים סביב פנסי רחוב בישראל."],"compare":{"stat":"Wingspan","value":23,"unit":"cm","text":"עד 23 ס״מ"},"stats":[{"label":"אורך הגוף","value":"4–5.5 ס״מ","note":"ראש וגוף, ועוד זנב של 3–4.5 ס״מ"},{"label":"מוטת כנפיים","value":"21–23 ס״מ","note":"מקצה לקצה"},{"label":"משקל","value":"5–10 גרם","note":"בוגר"},{"label":"גובה הקריאה","value":"34–41 קילוהרץ","note":"גבוה מדי לאוזניים של בני אדם"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","עטלפים · Chiroptera","עטלפיים · Vespertilionidae","Pipistrellus kuhlii"]}},"eagle":{"id":"eagle","i":31,"latin":"Aquila chrysaetos","group":"bird","home":"desert","diet":"carn","active":"day","continents":["North America","Europe","Asia","Africa"],"iucn":"LC","en":{"name":"Golden eagle","habitat_text":"Mountains, cliffs and open country; in Israel, desert canyons","menu":"Hares, rabbits, ground squirrels and marmots, birds such as partridges, and reptiles; in Israel also tortoises and spiny-tailed lizards. It eats carrion too.","iucn_note":"Least Concern worldwide. In Israel it is at risk of disappearing; dangers there include nest robbing, electrocution on power lines and low-flying aircraft near nests.","page_facts":["I have golden feathers on my neck.","I build my nest on cliffs.","I catch hares with my claws.","I hunt in the daytime."],"powers":[{"title":"Two sharp spots in each eye","kid":"Each eye has two extra-sharp spots, one for looking ahead and one for looking to the side, so it can spot prey from high up.","teen":"Each retina has two foveae: a deep one aimed about 45° to the side and a shallow one aimed about 15°. The related wedge-tailed eagle resolves over twice the detail humans can.","part":"eyes"},{"title":"Grappling-hook feet","kid":"Its feet end in huge curved claws. The back claw can be more than 6 cm long, for holding on to prey.","teen":"The hallux (rear) talon measures about 4.5–6.3 cm. After a plunge, the eagle seizes prey in its talons, holding animals as large as hares.","part":"talons"},{"title":"Soar, then stoop","kid":"Its long wings let it glide high over hills. Then it folds them back and drops into a very fast dive.","teen":"It soars at about 45–52 km/h; with wings folded into a stoop it can reach roughly 240 km/h, and some estimates go higher.","part":"wings"}],"field_note":{"place":"Israel","text":"In 1989 Israel had about 37 golden eagle pairs; by 2018 only 6 were left, rising to 11 by 2021. They nest on desert cliffs, and in the Judean Desert they often bring home tortoises."},"lab_note":"Israeli researchers Asaf Mayrose and Ohad Hatzofe tracked 26 young golden eagles by satellite and GPS. Most roamed a few hundred to about 1,000 km; a few flew up to 2,300 km, reaching Turkey and Yemen.","myth":{"claim":"A golden eagle is golden all over.","verdict":"myth","why":"Adults are dark brown. Only the pale golden feathers on the back of the head and neck give the eagle its name."},"clues":["I hunt by day from high in the sky.","I build a big nest of sticks on a cliff ledge.","I am a large brown eagle with golden feathers on the back of my head."],"compare":{"stat":"Wingspan","value":230,"unit":"cm","text":"up to about 2.3 m"},"stats":[{"label":"Length","value":"66–104 cm","note":"beak to tail"},{"label":"Wingspan","value":"1.8–2.3 m","note":"tip to tip"},{"label":"Weight","value":"2.5–6.7 kg","note":"females heavier"},{"label":"Dive speed","value":"about 240 km/h or more","note":"in a steep dive (stoop)"}],"taxonomy":["Animals","Birds · Aves","Birds of prey · Accipitriformes","Hawks and eagles · Accipitridae","Aquila chrysaetos"]},"he":{"name":"עיט זהוב","habitat_text":"הרים, מצוקים ושטחים פתוחים; בישראל, ערוצים במדבר","menu":"ארנבות, ארנבונים, סנאי קרקע ומרמיטות, עופות כמו חוגלות, וזוחלים; בישראל גם צבים וחרדוני־צב. הוא אוכל גם נבלות.","iucn_note":"ללא חשש ברמה העולמית. בישראל הוא בסכנת היעלמות; הסכנות שם כוללות שוד קינים, התחשמלות בקווי חשמל וכלי טיס שטסים נמוך ליד הקינים.","page_facts":["יש לי נוצות זהובות על הצוואר.","אני בונה את הקן שלי על מצוקים.","אני תופס ארנבות בציפורניים שלי.","אני צד בשעות היום."],"powers":[{"title":"שתי נקודות חדות בכל עין","kid":"בכל עין יש לו שתי נקודות חדות במיוחד, אחת להסתכל קדימה ואחת להסתכל הצידה, וכך הוא יכול לזהות טרף מגובה רב.","teen":"בכל רשתית יש שתי גומות ראייה: אחת עמוקה שמכוונת כ־45° הצידה, ואחת רדודה שמכוונת כ־15°. העיט טריז־הזנב, קרוב משפחה שלו, מבחין ביותר מפי שניים פרטים מבני אדם.","part":"eyes"},{"title":"רגליים כמו אנקולים","kid":"הרגליים שלו מסתיימות בטפרים ענקיים ומעוקלים. הטופר האחורי יכול להיות ארוך מ־6 ס״מ, והוא עוזר להחזיק את הטרף.","teen":"טופר הבוהן האחורית אורכו כ־4.5–6.3 ס״מ. אחרי צלילה, העיט תופס את הטרף בטפריו ומחזיק בעלי חיים גדולים כמו ארנבות.","part":"talons"},{"title":"לדאות, ואז לעוט","kid":"הכנפיים הארוכות שלו מאפשרות לו לדאות גבוה מעל גבעות. ואז הוא מקפל אותן לאחור וצולל צלילה מהירה מאוד.","teen":"הוא דואה במהירות של כ־45–52 קמ״ש; כשהוא מקפל את הכנפיים לצלילה (עטייה), הוא יכול להגיע לבערך 240 קמ״ש, ויש הערכות גבוהות יותר.","part":"wings"}],"field_note":{"place":"Israel","text":"בשנת 1989 היו בישראל כ־37 זוגות של עיטים זהובים; עד 2018 נשארו רק 6, והמספר עלה ל־11 עד 2021. הם מקננים על מצוקים במדבר, ובמדבר יהודה הם מביאים הרבה פעמים צבים הביתה."},"lab_note":"החוקרים הישראלים אסף מאירוז ואוהד הצופה עקבו בעזרת לוויין ו־GPS אחרי 26 עיטים זהובים צעירים. רובם נדדו בין כמה מאות לכ־1,000 ק״מ; כמה מהם עפו עד 2,300 ק״מ והגיעו לטורקיה ולתימן.","myth":{"claim":"העיט הזהוב זהוב בכל הגוף.","verdict":"myth","why":"העיטים הבוגרים חומים כהים. רק הנוצות בצבע זהוב בהיר בחלק האחורי של הראש והצוואר נותנות לעיט את שמו."},"clues":["ביום אני צד מגובה רב בשמיים.","אני בונה קן גדול מענפים על מדף של מצוק.","אני עיט חום וגדול, עם נוצות זהובות בחלק האחורי של הראש."],"compare":{"stat":"Wingspan","value":230,"unit":"cm","text":"עד בערך 2.3 מ׳"},"stats":[{"label":"אורך","value":"66–104 ס״מ","note":"מהמקור עד הזנב"},{"label":"מוטת כנפיים","value":"1.8–2.3 מ׳","note":"מקצה לקצה"},{"label":"משקל","value":"2.5–6.7 ק״ג","note":"הנקבות כבדות יותר"},{"label":"מהירות צלילה","value":"בערך 240 קמ״ש ויותר","note":"בצלילה תלולה (עטייה)"}],"taxonomy":["בעלי חיים","עופות · Aves","נצאים · Accipitriformes","נציים · Accipitridae","Aquila chrysaetos"]}},"mouse":{"id":"mouse","i":32,"latin":"Mus musculus","group":"mammal","home":"farm","diet":"omni","active":"night","continents":["Asia","Europe","Africa"],"iucn":"LC","en":{"name":"House mouse","habitat_text":"Homes, barns, farms and fields, wherever people live","menu":"Mostly seeds and grain, plus roots, leaves and insects. Near people it nibbles almost any food, even soap and glue.","iucn_note":"Least Concern. People have carried it to almost every part of the world.","page_facts":["I nibble seeds and grain.","I am busy mostly at night.","My whiskers help me feel my way.","I can squeeze through tiny holes."],"powers":[{"title":"Feelers in the dark","kid":"Its whiskers feel walls and moving air, so it can find its way in the dark.","teen":"Whiskers and guard hairs keep contact with walls and sense surfaces and air movement, guiding a mouse along its routes at night.","part":"whiskers"},{"title":"Teeth that never stop growing","kid":"Its front teeth keep growing, so it gnaws on hard things to keep them short.","teen":"Like all rodents it has ever-growing incisors, worn down by gnawing; fresh gnaw marks are less than 1 mm wide.","part":"front teeth"},{"title":"A nose for messages","kid":"It has a superb sense of smell. Mice leave smell messages, and males mark their home area with urine.","teen":"Its sense of smell is highly developed. House mice communicate with pheromones, chemical signals, and males scent-mark their territory with urine.","part":"nose"}],"field_note":{"place":"Israel","text":"Mouse teeth from Ain Mallaha, a hunter-gatherer settlement in Israel's Hula Valley, helped show that house mice began living with people in this region about 15,000 years ago, before farming."},"lab_note":"At Washington University in St. Louis, Timothy Holy and Zhongsheng Guo recorded male mice near females. Their squeaks, too high for people to hear, were songs with repeated phrases, and each male had his own style.","myth":{"claim":"Mice love cheese most of all.","verdict":"myth","why":"Mice mostly eat seeds and grain and prefer sweet, high-energy foods. Pest experts bait mouse traps with peanut butter or chocolate, not cheese."},"clues":["I am small and furry, and I squeak.","I nibble grain in houses and barns and slip through tiny gaps.","A gadget on your computer desk has my name."],"compare":{"stat":"Weight","value":30,"unit":"g","text":"up to 30 g"},"stats":[{"label":"Body length","value":"6.5–10 cm","note":"nose to rump, without the tail"},{"label":"Tail","value":"5–10.5 cm","note":"about as long as the body"},{"label":"Weight","value":"11–30 g","note":"adult"},{"label":"Litters a year","value":"5–10","note":"in good conditions, 3–14 babies each"}],"taxonomy":["Animals","Mammals · Mammalia","Rodents · Rodentia","Mice and rats · Muridae","Mus musculus"]},"he":{"name":"עכבר הבית","habitat_text":"בתים, אסמים, חוות ושדות, בכל מקום שבו גרים בני אדם","menu":"בעיקר זרעים ותבואה, וגם שורשים, עלים וחרקים. ליד בני אדם הוא מכרסם כמעט כל מזון, ואפילו סבון ודבק.","iucn_note":"ללא חשש. בני אדם הביאו אותו כמעט לכל מקום בעולם.","page_facts":["אני מכרסם זרעים ותבואה.","אני פעיל בעיקר בלילה.","השפם שלי עוזר לי למשש את הדרך.","אני יכול להשתחל דרך חורים קטנטנים."],"powers":[{"title":"משושים בחושך","kid":"השפם שלו מרגיש קירות ותנועת אוויר, וכך הוא יכול למצוא את הדרך בחושך.","teen":"שערות השפם ושערות המגן שומרות על מגע עם הקירות וחשות משטחים ותנועת אוויר, וכך הן מנחות את העכבר לאורך המסלולים שלו בלילה.","part":"whiskers"},{"title":"שיניים שלא מפסיקות לגדול","kid":"השיניים הקדמיות שלו ממשיכות לגדול, ולכן הוא מכרסם דברים קשים כדי לשמור שיישארו קצרות.","teen":"כמו לכל המכרסמים, יש לו חותכות שגדלות כל הזמן ונשחקות בכרסום; סימני כרסום טריים רחבים פחות מ־1 מ״מ.","part":"front teeth"},{"title":"אף שקולט הודעות","kid":"יש לו חוש ריח מצוין. עכברים משאירים הודעות של ריח, והזכרים מסמנים את אזור הבית שלהם בשתן.","teen":"חוש הריח שלו מפותח מאוד. עכברי בית מתקשרים בעזרת פרומונים, אותות כימיים, והזכרים מסמנים בריח את הטריטוריה שלהם בעזרת שתן.","part":"nose"}],"field_note":{"place":"Israel","text":"שיני עכברים מעין מלאחה (עינן), יישוב של ציידים־לקטים בעמק החולה בישראל, עזרו להראות שעכברי הבית התחילו לחיות עם בני אדם באזור הזה לפני כ־15,000 שנה, עוד לפני החקלאות."},"lab_note":"באוניברסיטת וושינגטון בסנט לואיס הקליטו טימותי הולי וג׳ונגשנג גואו עכברים זכרים ליד נקבות. הציוצים שלהם, גבוהים מדי לאוזן האדם, היו שירים עם משפטים חוזרים, ולכל זכר היה סגנון משלו.","myth":{"claim":"עכברים הכי אוהבים גבינה.","verdict":"myth","why":"עכברים אוכלים בעיקר זרעים ותבואה, ומעדיפים מזון מתוק ועתיר אנרגיה. מומחי הדברה שמים במלכודות עכברים חמאת בוטנים או שוקולד, לא גבינה."},"clues":["אני קטן ופרוותי, ואני מצייץ.","אני מכרסם תבואה בבתים ובאסמים ומשתחל דרך חריצים קטנטנים.","על שולחן המחשב יש מכשיר שנקרא בשם שלי."],"compare":{"stat":"Weight","value":30,"unit":"g","text":"עד 30 גרם"},"stats":[{"label":"אורך הגוף","value":"6.5–10 ס״מ","note":"מהאף עד האחוריים, בלי הזנב"},{"label":"זנב","value":"5–10.5 ס״מ","note":"בערך באורך הגוף"},{"label":"משקל","value":"11–30 גרם","note":"בוגר"},{"label":"המלטות בשנה","value":"5–10","note":"בתנאים טובים, 3–14 גורים בכל אחת"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","מכרסמים · Rodentia","עכבריים · Muridae","Mus musculus"]}},"fennec":{"id":"fennec","i":33,"latin":"Vulpes zerda","group":"mammal","home":"desert","diet":"omni","active":"night","continents":["Africa","Asia"],"iucn":"LC","en":{"name":"Fennec fox","habitat_text":"Sandy deserts of the Sahara and the Sinai Peninsula","menu":"Insects such as locusts and beetles, small rodents, lizards, birds and their eggs, plus fruit, leaves and roots.","iucn_note":"Least Concern (2015 assessment). It is listed on CITES Appendix II, which controls international trade in the species.","page_facts":["My ears are very, very big.","I dig my den in sand.","I hunt bugs at night.","My furry feet walk on hot sand."],"powers":[{"title":"Radar and radiator ears","kid":"Its giant ears hear insects and mice moving under the sand, and help let extra body heat escape.","teen":"Pinnae roughly 9–15 cm long locate prey moving beneath the sand, which it then digs out with all four feet; they also help shed body heat.","part":"ears"},{"title":"Built-in desert boots","kid":"Thick fur covers the bottoms of its feet, so it can walk on hot, loose sand.","teen":"Dense fur covers the foot pads, protecting them from scorching sand and giving traction on loose dunes.","part":"paws"},{"title":"Desert-ready coat","kid":"Its sandy-colored fur blends in with the desert.","teen":"Its buff coat, with fur about 2.7 cm long, camouflages it on sand; its coat, ears and kidneys are all adapted to desert heat and little water.","part":"fur"}],"field_note":{"place":"Sinai","text":"Fennecs live across the Sahara and east into Egypt's Sinai Peninsula, the desert that borders Israel's Negev."},"lab_note":"In a 1982 study, scientists including G. M. O. Maloiy and A. Shkolnik tested fennecs from the Sinai desert at different temperatures. The foxes had a low metabolism and lost very little water through their skin.","myth":{"claim":"A fennec fox must drink water every day.","verdict":"myth","why":"Fennecs can go a long time without drinking. They get water from their food, and their kidneys lose very little water in urine."},"clues":["I sleep in a den during the day.","I live in sandy deserts and hunt at night.","I am a tiny fox with giant ears and fur on the soles of my feet."],"compare":{"stat":"Weight","value":1.9,"unit":"kg","text":"up to 1.9 kg"},"stats":[{"label":"Body length","value":"30–41 cm","note":"head and body; the tail adds 12.5–30 cm"},{"label":"Ear length","value":"9–15 cm","note":"huge for its body"},{"label":"Weight","value":"0.8–1.9 kg","note":"adult"},{"label":"Jump","value":"60–70 cm","note":"straight up; about 1.2 m forward"}],"taxonomy":["Animals","Mammals · Mammalia","Carnivores · Carnivora","Dogs and foxes · Canidae","Vulpes zerda"]},"he":{"name":"פנק","habitat_text":"מדבריות החול של הסהרה וחצי האי סיני","menu":"חרקים כמו ארבה וחיפושיות, מכרסמים קטנים, לטאות, ציפורים והביצים שלהן, וגם פירות, עלים ושורשים.","iucn_note":"ללא חשש (הערכה משנת 2015). הוא רשום בנספח II של אמנת CITES, שמפקחת על הסחר הבין־לאומי במין.","page_facts":["האוזניים שלי גדולות מאוד, מאוד.","אני חופר את המאורה שלי בחול.","אני צד חרקים בלילה.","הרגליים הפרוותיות שלי הולכות על חול חם."],"powers":[{"title":"אוזניים של מכ״ם ושל מצנן","kid":"האוזניים הענקיות שלו שומעות חרקים ועכברים שזזים מתחת לחול, ועוזרות להוציא מהגוף חום עודף.","teen":"אפרכסות האוזניים, באורך של כ־9–15 ס״מ, מאתרות טרף שזז מתחת לחול, ואז הוא חופר אותו החוצה בכל ארבע הרגליים; הן גם עוזרות לפלוט חום מהגוף.","part":"ears"},{"title":"מגפי מדבר מובנים","kid":"פרווה עבה מכסה את כפות הרגליים שלו מלמטה, וכך הוא יכול ללכת על חול חם ותחוח.","teen":"פרווה צפופה מכסה את כריות כפות הרגליים, מגינה עליהן מפני החול הלוהט ונותנת אחיזה בדיונות תחוחות.","part":"paws"},{"title":"פרווה מוכנה למדבר","kid":"הפרווה שלו בצבע חול, והיא מתמזגת עם המדבר.","teen":"הפרווה הצהבהבה־בהירה, באורך של כ־2.7 ס״מ, מסווה אותו על החול; הפרווה, האוזניים והכליות שלו מותאמות כולן לחום המדבר ולמעט מים.","part":"fur"}],"field_note":{"place":"Sinai","text":"פנקים חיים בכל רחבי הסהרה, ומזרחה עד חצי האי סיני שבמצרים, המדבר שגובל בנגב שבישראל."},"lab_note":"במחקר משנת 1982 בדקו מדענים, ובהם ג׳ מ׳ או׳ מלואי וא׳ שקולניק, פנקים ממדבר סיני בטמפרטורות שונות. לשועלים היה חילוף חומרים נמוך, והם איבדו מעט מאוד מים דרך העור.","myth":{"claim":"פנק חייב לשתות מים כל יום.","verdict":"myth","why":"פנקים יכולים להחזיק מעמד זמן רב בלי לשתות. הם מקבלים מים מהמזון שלהם, והכליות שלהם מאבדות מעט מאוד מים בשתן."},"clues":["ביום אני ישן במאורה.","אני גר במדבריות חול וצד בלילה.","אני שועל קטנטן עם אוזניים ענקיות ופרווה מתחת לכפות הרגליים."],"compare":{"stat":"Weight","value":1.9,"unit":"kg","text":"עד 1.9 ק״ג"},"stats":[{"label":"אורך הגוף","value":"30–41 ס״מ","note":"ראש וגוף; הזנב מוסיף 12.5–30 ס״מ"},{"label":"אורך האוזן","value":"9–15 ס״מ","note":"ענקית ביחס לגוף"},{"label":"משקל","value":"0.8–1.9 ק״ג","note":"בוגר"},{"label":"קפיצה","value":"60–70 ס״מ","note":"ישר למעלה; בערך 1.2 מ׳ קדימה"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","טורפים · Carnivora","כלביים · Canidae","Vulpes zerda"]}},"peregrine":{"id":"peregrine","i":34,"latin":"Falco peregrinus","group":"bird","home":"desert","diet":"carn","active":"day","continents":["North America","South America","Europe","Africa","Asia","Australia"],"iucn":"LC","en":{"name":"Peregrine falcon","habitat_text":"Cliffs, coasts, open country, deserts and cities, almost worldwide","menu":"Mostly other birds caught in the air: pigeons and doves, ducks, shorebirds and songbirds. City falcons live mainly on pigeons.","iucn_note":"Least Concern. From the 1950s to the 1970s the pesticide DDT thinned its eggshells and it disappeared from many areas. After DDT was banned it recovered; the USA took it off its endangered list in 1999.","page_facts":["I dive faster than any animal.","I catch birds in the air.","I nest on cliffs and buildings.","I live on almost every continent."],"powers":[{"title":"Dive-proof nostrils","kid":"Little bony bumps inside its nostrils are thought to help it breathe during a super-fast dive.","teen":"Bony tubercles in the nostrils are thought to steer the rush of air during a stoop, reducing pressure changes so the falcon can keep breathing.","part":"nostrils"},{"title":"A tooth on the beak","kid":"A small notch near the tip of its beak works like a tooth.","teen":"The upper beak has a notch near the tip, the tomial tooth, which lets the falcon kill prey quickly by breaking the neck bones.","part":"beak"},{"title":"Wiper eyelids and fast eyes","kid":"A clear third eyelid wipes its eyes clean while it keeps watching, and it sees fast movement very sharply.","teen":"A nictitating membrane spreads tears and clears debris without blocking vision; a flicker fusion rate of 129 Hz lets it follow fast motion far better than mammals.","part":"eyes"}],"field_note":{"place":"Israel","text":"In the canyons of Israel's Judean Desert lives the Barbary falcon, a desert subspecies of the peregrine. It lays its eggs on cliff ledges, sharing the canyons with eagles and vultures."},"lab_note":"At the University of Oxford, Caroline Brighton and Graham Taylor tracked peregrines with onboard cameras and GPS. Their attacks followed proportional navigation, the same steering rule used by guided missiles.","myth":{"claim":"The cheetah is the fastest animal on Earth.","verdict":"myth","why":"The cheetah is the fastest runner. A peregrine diving after prey reaches about 320 km/h, roughly three times a cheetah's top sprint."},"clues":["I hunt other birds.","I nest on cliff ledges and on tall city buildings.","I am the falcon that dives faster than any other animal on Earth."],"compare":{"stat":"Speed","value":320,"unit":"km/h","text":"about 320 km/h in a dive"},"stats":[{"label":"Length","value":"34–58 cm","note":"beak to tail"},{"label":"Wingspan","value":"74–120 cm","note":"tip to tip"},{"label":"Weight","value":"330–1,500 g","note":"females up to 30% larger"},{"label":"Dive speed","value":"about 320 km/h","note":"hunting dive; 389 km/h recorded once"}],"taxonomy":["Animals","Birds · Aves","Falcons and caracaras · Falconiformes","Falcons · Falconidae","Falco peregrinus"]},"he":{"name":"בז נודד","habitat_text":"מצוקים, חופים, שטחים פתוחים, מדבריות וערים, כמעט בכל העולם","menu":"בעיקר ציפורים אחרות שהוא תופס באוויר: יונים ותורים, ברווזים, עופות חוף וציפורי שיר. בזים בערים ניזונים בעיקר מיונים.","iucn_note":"ללא חשש. משנות ה־50 עד שנות ה־70, חומר ההדברה DDT גרם לקליפות הביצים שלו להיות דקות, והוא נעלם מאזורים רבים. אחרי שה־DDT נאסר הוא התאושש; ארצות הברית הוציאה אותו מרשימת המינים בסכנת הכחדה שלה ב־1999.","page_facts":["אני צולל מהר יותר מכל בעל חיים.","אני תופס ציפורים באוויר.","אני מקנן על מצוקים ובניינים.","אני חי כמעט בכל היבשות."],"powers":[{"title":"נחיריים שעמידים בצלילה","kid":"חושבים שבליטות גרמיות קטנות בתוך הנחיריים שלו עוזרות לו לנשום בזמן צלילה מהירה במיוחד.","teen":"לפי ההשערה, גבשושיות גרמיות בנחיריים מכוונות את זרם האוויר החזק בזמן צלילה (עטייה), מקטינות את שינויי הלחץ וכך מאפשרות לבז להמשיך לנשום.","part":"nostrils"},{"title":"שן על המקור","kid":"חריץ קטן ליד קצה המקור שלו עובד כמו שן.","teen":"במקור העליון יש חריץ ליד הקצה, שן המקור, שמאפשר לבז להמית את הטרף במהירות בשבירת עצמות הצוואר.","part":"beak"},{"title":"עפעפי מגב ועיניים מהירות","kid":"עפעף שלישי שקוף מנגב לו את העיניים בזמן שהוא ממשיך להסתכל, והוא רואה תנועה מהירה בחדות רבה.","teen":"הקרום המצמץ מפזר דמעות ומנקה לכלוך בלי לחסום את הראייה; קצב היתוך הבהובים של 129 הרץ מאפשר לו לעקוב אחרי תנועה מהירה הרבה יותר טוב מיונקים.","part":"eyes"}],"field_note":{"place":"Israel","text":"בערוצים של מדבר יהודה בישראל חי בז המדבר, תת־מין מדברי של הבז הנודד. הוא מטיל את ביציו על מדפי מצוקים, וחולק את הערוצים עם עיטים ונשרים."},"lab_note":"באוניברסיטת אוקספורד עקבו קרוליין ברייטון וגרהם טיילור אחרי בזים נודדים בעזרת מצלמות ומכשירי GPS שהוצמדו אליהם. ההתקפות שלהם התנהלו לפי ניווט יחסי, אותו כלל היגוי שמשמש טילים מונחים.","myth":{"claim":"הברדלס הוא בעל החיים המהיר ביותר בעולם.","verdict":"myth","why":"הברדלס הוא הרץ המהיר ביותר. בז נודד שצולל אחרי טרף מגיע לבערך 320 קמ״ש, בערך פי שלושה ממהירות הריצה הגבוהה ביותר של ברדלס."},"clues":["אני צד ציפורים אחרות.","אני מקנן על מדפי מצוקים ועל בניינים גבוהים בעיר.","אני הבז שצולל מהר יותר מכל בעל חיים אחר בעולם."],"compare":{"stat":"Speed","value":320,"unit":"km/h","text":"בערך 320 קמ״ש בצלילה"},"stats":[{"label":"אורך","value":"34–58 ס״מ","note":"מהמקור עד הזנב"},{"label":"מוטת כנפיים","value":"74–120 ס״מ","note":"מקצה לקצה"},{"label":"משקל","value":"330–1,500 גרם","note":"הנקבות גדולות יותר, עד 30%"},{"label":"מהירות צלילה","value":"בערך 320 קמ״ש","note":"בצלילת ציד; פעם אחת נמדדו 389 קמ״ש"}],"taxonomy":["בעלי חיים","עופות · Aves","בזאים · Falconiformes","בזיים · Falconidae","Falco peregrinus"]}},"cheetah":{"id":"cheetah","i":35,"latin":"Acinonyx jubatus","group":"mammal","home":"savanna","diet":"carn","active":"day","continents":["Africa","Asia"],"iucn":"VU","en":{"name":"Cheetah","habitat_text":"Open grassland, savanna and other open country in Africa and Iran","menu":"Mostly small antelopes such as gazelles, impala, springbok and duikers. It kills by gripping the throat until the prey cannot breathe.","iucn_note":"Vulnerable worldwide; about 6,500 adults were counted in 2021. The Asiatic cheetah, the kind that once lived in Israel, is Critically Endangered and survives only in Iran.","page_facts":["I am the fastest runner on land.","Black lines run down from my eyes.","My long tail helps me turn.","I hunt in the daytime."],"powers":[{"title":"A tail like a rudder","kid":"Its long tail works like a boat's rudder, helping it turn sharply while chasing at full speed.","teen":"The 60–84 cm tail acts as a rudder during sharp turns; GPS-collar studies show wild cheetahs make huge sideways accelerations mid-chase.","part":"tail"},{"title":"Running-shoe claws","kid":"Its claws only partly pull in, so they grip the ground like the spikes on running shoes.","teen":"Unlike most cats, its claws are only partly retractile and fairly blunt, giving traction like cleats when it accelerates and swerves.","part":"paws"},{"title":"Big air intake","kid":"Its big nostrils and lungs pull in lots of air fast, which it needs during a sprint.","teen":"Enlarged nasal passages and lungs allow rapid air intake; it has the largest frontal sinuses of any cat, leaving little room for long canine tooth roots.","part":"nose"}],"field_note":{"place":"Israel","text":"Asiatic cheetahs once lived in the Land of Israel, hunting in open country. They have died out here and across the Middle East; wild Asiatic cheetahs now survive only in Iran, and very few remain."},"lab_note":"Alan Wilson's team (Royal Veterinary College) put GPS collars on five wild cheetahs in Botswana. Over 367 runs, top speed was 93 km/h, but most hunts were slower, with huge bursts of acceleration and braking.","myth":{"claim":"Cheetahs roar like lions.","verdict":"myth","why":"Cheetahs cannot roar. They purr, chirp, bark, growl and hiss, and a loud chirp can be heard far away."},"clues":["I am a spotted cat.","I hunt by day and sprint after gazelles.","I am the fastest runner on land, with black tear lines on my face."],"compare":{"stat":"Speed","value":93,"unit":"km/h","text":"93 km/h, measured on a wild cheetah"},"stats":[{"label":"Body length","value":"1.1–1.5 m","note":"head and body; the tail adds 60–84 cm"},{"label":"Shoulder height","value":"67–94 cm","note":"standing"},{"label":"Weight","value":"21–65 kg","note":"adult"},{"label":"Top speed","value":"93–104 km/h","note":"fastest sprints reliably measured"}],"taxonomy":["Animals","Mammals · Mammalia","Carnivores · Carnivora","Cats · Felidae","Acinonyx jubatus"]},"he":{"name":"ברדלס","habitat_text":"שטחי עשב פתוחים, סוואנה ושטחים פתוחים אחרים באפריקה ובאיראן","menu":"בעיקר אנטילופות קטנות כמו צבאים, אימפלות, ספרינגבוקים ודויקרים. הוא ממית את הטרף בלפיתת הגרון, עד שהטרף לא יכול לנשום.","iucn_note":"פגיע ברמה העולמית; בשנת 2021 נספרו כ־6,500 בוגרים. הברדלס האסייתי, זה שחי פעם בישראל, נמצא בסכנת הכחדה חמורה ושורד רק באיראן.","page_facts":["אני הרץ המהיר ביותר ביבשה.","פסים שחורים יורדים מהעיניים שלי.","הזנב הארוך שלי עוזר לי לפנות.","אני צד בשעות היום."],"powers":[{"title":"זנב כמו הגה","kid":"הזנב הארוך שלו עובד כמו הגה של סירה, ועוזר לו לפנות בחדות בזמן מרדף במהירות מלאה.","teen":"הזנב, באורך 60–84 ס״מ, משמש כהגה בפניות חדות; מחקרים עם קולרי GPS מראים שברדלסים בטבע מבצעים תאוצות צד עצומות באמצע מרדף.","part":"tail"},{"title":"ציפורניים של נעלי ריצה","kid":"הציפורניים שלו נכנסות פנימה רק בחלקן, ולכן הן אוחזות בקרקע כמו המסמרים בנעלי ריצה.","teen":"בשונה מרוב החתולים, הציפורניים שלו נאספות פנימה רק בחלקן והן די קהות, ולכן הן נותנות אחיזה כמו פקקים של נעלי כדורגל כשהוא מאיץ ומשנה כיוון בחדות.","part":"paws"},{"title":"פתח אוויר גדול","kid":"הנחיריים והריאות הגדולים שלו מכניסים הרבה אוויר מהר, והוא זקוק לזה בזמן ריצה מהירה.","teen":"מעברי אף וריאות מוגדלים מאפשרים קליטת אוויר מהירה; יש לו הסינוסים המצחיים הגדולים ביותר מבין כל החתולים, ולכן נשאר מעט מקום לשורשים ארוכים של שיני הניב.","part":"nose"}],"field_note":{"place":"Israel","text":"ברדלסים אסייתיים חיו פעם בארץ ישראל וצדו בשטחים פתוחים. הם נכחדו כאן ובכל המזרח התיכון; היום ברדלסים אסייתיים שורדים בטבע רק באיראן, ונשארו מעט מאוד."},"lab_note":"הצוות של אלן וילסון (המכללה המלכותית לרפואה וטרינרית) הצמיד קולרי GPS לחמישה ברדלסים בטבע בבוטסואנה. ב־367 ריצות, המהירות הגבוהה ביותר הייתה 93 קמ״ש, אבל רוב המרדפים היו איטיים יותר, עם פרצים עצומים של האצה ובלימה.","myth":{"claim":"ברדלסים שואגים כמו אריות.","verdict":"myth","why":"ברדלסים לא יכולים לשאוג. הם מגרגרים, מצייצים, נובחים, נוהמים ונושפים, וציוץ חזק אפשר לשמוע למרחק רב."},"clues":["אני חתול מנומר.","אני צד ביום ורץ מהר אחרי צבאים.","אני הרץ המהיר ביותר ביבשה, ועל הפנים שלי יש פסי דמעה שחורים."],"compare":{"stat":"Speed","value":93,"unit":"km/h","text":"93 קמ״ש, שנמדדו אצל ברדלס בטבע"},"stats":[{"label":"אורך הגוף","value":"1.1–1.5 מ׳","note":"ראש וגוף; הזנב מוסיף 60–84 ס״מ"},{"label":"גובה הכתפיים","value":"67–94 ס״מ","note":"בעמידה"},{"label":"משקל","value":"21–65 ק״ג","note":"בוגר"},{"label":"מהירות שיא","value":"93–104 קמ״ש","note":"הריצות המהירות ביותר שנמדדו באופן אמין"}],"taxonomy":["בעלי חיים","יונקים · Mammalia","טורפים · Carnivora","חתוליים · Felidae","Acinonyx jubatus"]}}}};
